function getGroupSenderColor(uid) {
    if (!uid) return '#00f3ff';
    const colors = [
        '#00f3ff', // Cyan
        '#ffb800', // Gold
        '#38bdf8', // Azul Claro
        '#a855f7', // Roxo
        '#4ade80', // Verde Neon
        '#f43f5e', // Rosa
        '#fb923c', // Laranja
        '#e879f9', // Magenta
        '#2dd4bf'  // Verde Água
    ];
    let hash = 0;
    for (let i = 0; i < uid.length; i++) {
        hash = uid.charCodeAt(i) + ((hash << 5) - hash);
    }
    const index = Math.abs(hash) % colors.length;
    return colors[index];
}

