// ===== SISTEMA DE NOTIFICAÇÕES PUSH NO CELULAR (PWA & NATIVO) =====
let inAppPushBannerTimer = null;
const lastKnownUnreadCountMap = new Map();

export async function requestPushNotificationPermission() {
    if (typeof window === 'undefined' || !('Notification' in window) || !window.Notification) {
        showToast('Notificações', 'Seu navegador não suporta notificações nativas.', 'yellow');
        updatePushSettingsUI('unsupported');
        return 'unsupported';
    }
    try {
        const permission = await window.Notification.requestPermission();
        updatePushSettingsUI(permission);
        if (permission === 'granted') {
            showToast('Notificações Ativadas', 'Você receberá alertas de mensagens e chamadas no celular! 🔔', 'green');
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('vortex_push_permission', 'granted');
            }
            registerPushToken();
        } else if (permission === 'denied') {
            showToast('Notificações Bloqueadas', 'Permissão bloqueada. Habilite nas configurações do navegador/celular.', 'red');
        }
        return permission;
    } catch (e) {
        console.warn('Erro ao solicitar permissão de notificações:', e);
        return 'denied';
    }
}

/* ===== PUSH DE CHAMADAS COM O APP FECHADO (FIREBASE CLOUD MESSAGING) ===== */

// Registra o aparelho para receber chamadas em segundo plano e salva o token no perfil
export async function registerPushToken() {
    try {
        if (!currentUser) return null;
        if (typeof window === 'undefined' || !('Notification' in window) || window.Notification.permission !== 'granted') return null;
        if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return null;
        if (typeof isMessagingSupported === 'function' && !(await isMessagingSupported())) return null;

        const registration = await navigator.serviceWorker.ready;
        const token = await getToken(getMessaging(app), { serviceWorkerRegistration: registration });
        if (!token) return null;

        const storageKey = `vortex_fcm_token_${currentUser.uid}`;
        const alreadySaved = typeof localStorage !== 'undefined' && localStorage.getItem(storageKey) === token;
        if (!alreadySaved) {
            await setDoc(doc(db, 'users', currentUser.uid), {
                fcmTokens: arrayUnion(token),
                fcmTokenUpdatedAt: Date.now()
            }, { merge: true });
            if (typeof localStorage !== 'undefined') localStorage.setItem(storageKey, token);
        }
        return token;
    } catch (e) {
        console.warn('[VORTEX] Não foi possível registrar o push de chamadas:', e);
        return null;
    }
}

// Ao sair da conta, este aparelho deixa de receber as chamadas dela
export async function unregisterPushToken(uid) {
    try {
        const targetUid = uid || (currentUser && currentUser.uid);
        if (!targetUid || typeof localStorage === 'undefined') return;
        const storageKey = `vortex_fcm_token_${targetUid}`;
        const token = localStorage.getItem(storageKey);
        if (!token) return;
        await updateDoc(doc(db, 'users', targetUid), { fcmTokens: arrayRemove(token) });
        localStorage.removeItem(storageKey);
    } catch (e) {
        console.warn('[VORTEX] Não foi possível remover o token de push:', e);
    }
}

// Pede ao servidor para enviar o push da chamada ao destinatário (que pode estar com o app fechado)
export async function notifyCallPush(callId) {
    if (!callId) return null;
    try {
        const res = await fetchApi('/api/notify-call', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ callId })
        });
        return await res.json().catch(() => null);
    } catch (e) {
        console.warn('[VORTEX] Não foi possível avisar o servidor da chamada:', e);
        return null;
    }
}

// Pede a permissão de notificações uma única vez, no primeiro toque do usuário (exigência dos navegadores)
export function setupPushPermissionAutoPrompt() {
    if (typeof window === 'undefined' || !('Notification' in window) || !window.Notification) return;
    if (window.Notification.permission !== 'default') return;
    if (typeof localStorage !== 'undefined' && localStorage.getItem('vortex_push_prompted') === '1') return;

    const onFirstTap = () => {
        document.removeEventListener('click', onFirstTap, true);
        if (typeof localStorage !== 'undefined') localStorage.setItem('vortex_push_prompted', '1');
        requestPushNotificationPermission();
    };
    document.addEventListener('click', onFirstTap, true);
}

// Chamada aberta a partir da notificação (?call=ID&answer=1 ou mensagem do Service Worker)
let pendingCallLink = null;

export function handleIncomingCallLink(callId, answer = false) {
    if (!callId) return;
    pendingCallLink = { callId: String(callId), answer: !!answer, at: Date.now() };
    if (currentCallId && currentCallId === pendingCallLink.callId) {
        consumePendingCallLink(currentCallId);
    }
}

function consumePendingCallLink(callId) {
    if (!pendingCallLink || pendingCallLink.callId !== callId) return;
    const shouldAnswer = pendingCallLink.answer;
    pendingCallLink = null;
    if (shouldAnswer) {
        acceptIncomingCall();
    }
}

function readCallLinkFromUrl() {
    try {
        if (typeof window === 'undefined' || !window.location || !window.location.search) return;
        const params = new URLSearchParams(window.location.search);
        const callId = params.get('call');
        if (!callId) return;
        handleIncomingCallLink(callId, params.get('answer') === '1');
        if (window.history && window.history.replaceState) {
            window.history.replaceState({}, document.title, window.location.pathname);
        }
    } catch (_) {}
}

if (typeof navigator !== 'undefined' && navigator.serviceWorker && typeof navigator.serviceWorker.addEventListener === 'function') {
    navigator.serviceWorker.addEventListener('message', (event) => {
        const msg = event.data || {};
        if (msg.type === 'INCOMING_CALL' && msg.callId) {
            handleIncomingCallLink(msg.callId, msg.answer);
        }
    });
}
readCallLinkFromUrl();

export function updatePushSettingsUI(permission) {
    const statusLabel = document.getElementById('push-perm-status-label') || document.getElementById('push-status-label');
    const permBtn = document.getElementById('push-permission-btn');
    const permText = document.getElementById('push-permission-text');
    const currentPerm = permission || (typeof window !== 'undefined' && window.Notification ? window.Notification.permission : 'default');

    if (currentPerm === 'granted') {
        if (statusLabel) statusLabel.innerText = 'Ativado • Alertas ativos no celular';
        if (permBtn) {
            permBtn.classList.add('granted');
            permBtn.title = 'Notificações push ativas';
        }
        if (permText) permText.innerText = 'Ativado';
    } else if (currentPerm === 'denied') {
        if (statusLabel) statusLabel.innerText = 'Bloqueado no navegador • Altere nas permissões';
        if (permBtn) {
            permBtn.classList.remove('granted');
            permBtn.title = 'Notificações bloqueadas';
        }
        if (permText) permText.innerText = 'Bloqueado';
    } else {
        if (statusLabel) statusLabel.innerText = 'Alertas no celular em segundo plano';
        if (permBtn) {
            permBtn.classList.remove('granted');
            permBtn.title = 'Ativar notificações push no celular';
        }
        if (permText) permText.innerText = 'Ativar';
    }
}

export function showMobilePushNotification({ title, body, icon, chatId, senderUid, avatar }) {
    if (typeof currentProfile !== 'undefined' && currentProfile && currentProfile.soundEnabled === false) {
        // Respeita modo silencioso
    } else {
        playSound(notificationSound);
        if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
            try { navigator.vibrate([200, 100, 200]); } catch (_) {}
        }
    }

    const notifTitle = title || 'VORTEX VIP ⚡';
    const notifBody = body || 'Nova mensagem recebida';
    const notifIcon = avatar || icon || '/icons/vortex-vip-192.png';

    // 1. Notificação Nativa do Sistema Operacional (Mobile e Desktop)
    if (typeof window !== 'undefined' && 'Notification' in window && window.Notification && window.Notification.permission === 'granted') {
        if (typeof navigator !== 'undefined' && navigator.serviceWorker && navigator.serviceWorker.ready) {
            navigator.serviceWorker.ready.then(registration => {
                registration.showNotification(notifTitle, {
                    body: notifBody,
                    icon: notifIcon,
                    badge: '/icons/vortex-vip-192.png',
                    vibrate: [200, 100, 200],
                    tag: `vortex-msg-${chatId || senderUid || 'general'}`,
                    data: {
                        chatId: chatId,
                        senderUid: senderUid,
                        url: '/'
                    }
                }).catch(() => {});
            }).catch(() => {});
        } else {
            try {
                const n = new window.Notification(notifTitle, {
                    body: notifBody,
                    icon: notifIcon,
                    badge: '/icons/vortex-vip-192.png'
                });
                n.onclick = () => {
                    window.focus();
                    if (chatId || senderUid) openChatByChatIdOrUid(chatId, senderUid);
                };
            } catch (_) {}
        }
    }

    // 2. Banner Push Flutuante VIP no Celular (In-App Push Banner)
    const isCurrentChatActive = activeChatContact && (activeChatContact.uid === senderUid || activeChatContact.chatId === chatId) && document.getElementById('chat-window')?.classList.contains('active');
    if (!isCurrentChatActive) {
        showInAppPushBanner({ title: notifTitle, body: notifBody, avatar: notifIcon, chatId, senderUid });
    }
}

export function showInAppPushBanner({ title, body, avatar, chatId, senderUid }) {
    const banner = document.getElementById('mobile-push-banner');
    if (!banner) return;
    const titleEl = document.getElementById('mobile-push-title');
    const bodyEl = document.getElementById('mobile-push-body');
    const avatarEl = document.getElementById('mobile-push-avatar');

    if (titleEl) titleEl.innerText = title || 'Nova Mensagem';
    if (bodyEl) bodyEl.innerText = body || 'Mensagem recebida';
    if (avatarEl) {
        if (avatar && (avatar.startsWith('http') || avatar.startsWith('data:'))) {
            avatarEl.style.backgroundImage = `url('${avatar}')`;
        } else {
            avatarEl.style.backgroundImage = '';
        }
    }

    banner.style.display = 'block';
    banner.classList.add('visible');
    banner.setAttribute('aria-hidden', 'false');

    banner.onclick = (e) => {
        if (e.target && e.target.closest('#mobile-push-close')) {
            dismissInAppPushBanner();
            return;
        }
        dismissInAppPushBanner();
        if (senderUid || chatId) {
            openChatByChatIdOrUid(chatId, senderUid);
        }
    };

    if (inAppPushBannerTimer) clearTimeout(inAppPushBannerTimer);
    inAppPushBannerTimer = setTimeout(() => {
        dismissInAppPushBanner();
    }, 4500);
}

export function dismissInAppPushBanner() {
    const banner = document.getElementById('mobile-push-banner');
    if (!banner) return;
    banner.classList.remove('visible');
    setTimeout(() => {
        if (!banner.classList.contains('visible')) {
            banner.style.display = 'none';
            banner.setAttribute('aria-hidden', 'true');
        }
    }, 350);
}

export async function openChatByChatIdOrUid(chatId, senderUid) {
    if (!senderUid && !chatId) return false;
    if (!currentUser) return false;
    let targetUid = senderUid;

    // Se targetUid não foi passado ou for o próprio usuário logado, tenta extrair o outro UID do chatId
    if ((!targetUid || (currentUser && targetUid === currentUser.uid)) && chatId) {
        if (chatId.startsWith('group_')) {
            targetUid = chatId.replace('group_', '');
        } else if (chatId.includes('_')) {
            const parts = chatId.split('_');
            if (currentUser) {
                targetUid = parts.find(u => u !== currentUser.uid) || targetUid;
            }
        }
    }

    if (!targetUid) targetUid = chatId;

    const contactCard = document.querySelector(`.chat-card[data-uid="${targetUid}"]`);
    if (contactCard) {
        contactCard.click();
        return true;
    } else {
        const contact = { uid: targetUid, name: 'Contato VIP' };
        if (typeof openDirectChat === 'function') {
            await openDirectChat(contact);
            return true;
        } else if (typeof openChat === 'function') {
            await openChat(contact);
            return true;
        }
    }
    return false;
}

const mediaSizeLimits = {
    image: { bytes: 26214400, label: 'imagem' },
    video: { bytes: 26214400, label: 'vídeo' },
    audio: { bytes: 26214400, label: 'música ou áudio' },
    file: { bytes: 26214400, label: 'arquivo' }
};

function getMediaSizeLimit(type) {
    return mediaSizeLimits[type] || mediaSizeLimits.file;
}

function showMediaSizeWarning(type) {
    const limit = getMediaSizeLimit(type);
    const limitLabel = limit.bytes >= 1048576 
        ? `${(limit.bytes / 1048576).toFixed(0)} MB` 
        : `${(limit.bytes / 1024).toFixed(0)} KB`;
    showToast('Arquivo muito grande', `O limite para ${limit.label} é ${limitLabel}.`, 'red');
}

