onAuthStateChanged(auth, async (user) => {
    const authScreen = document.getElementById('auth-screen');
    const lockScreen = document.getElementById('lock-screen');

    if (user) {
        currentUser = user;
        if (authScreen) authScreen.classList.add('unlocked');
        
        const userDocRef = doc(db, 'users', user.uid);
        const userSnap = await getDoc(userDocRef);

        if (!userSnap.exists()) {
            const rawEmailPrefix = user.email ? user.email.split('@')[0].replace(/[^a-zA-Z0-9_]/g, '') : 'user';
            const autoUsername = `@${rawEmailPrefix}_${Math.floor(1000 + Math.random() * 9000)}`;
            const nameParts = (user.displayName || 'Membro').split(' ');
            const isAdmin = !!(user.email && ['dxhub.oficial@gmail.com', 'vortex.dx.oficial@gmail.com', 'dxhubdigitalsuporte@gmail.com'].includes(user.email.toLowerCase()));

            currentProfile = {
                uid: user.uid,
                email: user.email || '',
                name: (nameParts[0] || 'Membro').slice(0, 15),
                surname: (nameParts.slice(1).join(' ') || '').slice(0, 15),
                username: autoUsername,
                status: 'Disponível no VORTEX ⚡',
                phone: '',
                pixKey: '',
                youtube: '',
                instagram: '',
                tiktok: '',
                socialLinks: {
                    youtube: '',
                    instagram: '',
                    tiktok: ''
                },
                avatar: user.photoURL || '',
                accentColor: '#fff01f',
                pin: '1234',
                pinEnabled: false,
                ghostMode: false,
                privacyMode: false,
                soundEnabled: true,
                ringtoneType: 'antigo',
                isVerified: isAdmin,
                isVip: isAdmin,
                online: true,
                lastSeen: Date.now(),
                pinnedChats: []
            };
            await setDoc(userDocRef, currentProfile);
        } else {
            currentProfile = { ...currentProfile, ...userSnap.data(), uid: user.uid };
        }

        pinnedChats = Array.isArray(currentProfile.pinnedChats) ? currentProfile.pinnedChats : [];
        applyUserTheme();
        updateProfileDOM();
        if (typeof updateChatPinUI === 'function') updateChatPinUI();
        if (typeof applyPinnedSortToChatList === 'function') applyPinnedSortToChatList();

        ensureUsernameReservation(currentProfile).catch((error) => {
            console.error('Erro ao reservar username inicial:', error);
        });

        setupPresence(user.uid);

        onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                currentProfile = { ...currentProfile, ...docSnap.data() };
                pinnedChats = Array.isArray(currentProfile.pinnedChats) ? currentProfile.pinnedChats : [];
                applyUserTheme();
                updateProfileDOM();
                checkBannedAccountState();
                updateAdminUIVisibility();
                if (typeof updateChatPinUI === 'function') updateChatPinUI();
                if (typeof applyPinnedSortToChatList === 'function') applyPinnedSortToChatList();
            }
        });

        if (currentProfile.pinEnabled && lockScreen) lockScreen.classList.remove('unlocked');
        checkBannedAccountState();
        updateAdminUIVisibility();

        listenToContacts();
        listenToBlockedContacts();
        listenToRequests();
        listenToStories();
        listenToIncomingCalls();
        registerPushToken();
        setupPushPermissionAutoPrompt();
        listenToNotifications();
        listenToAdminReports();
        listenToDeletedUsers();
        loadUserFavoriteTracks();
        showToast("Conectado", `Bem-vindo, ${currentProfile.name}!`, "green");
    } else {
        currentUser = null;
        loadUserFavoriteTracks();
        if (authScreen) authScreen.classList.remove('unlocked');
        detachListeners();
        updateAdminUIVisibility();
    }
});

export function updateNotificationsBadge() {
    const badge = document.getElementById('notifications-bell-badge');
    if (!badge) return;
    const unreadCount = allNotifications.filter(n => !n.read && !readNotifIds.has(n.id) && !deletedNotifIds.has(n.id)).length;
    badge.innerText = unreadCount;
    badge.style.display = unreadCount > 0 ? 'inline-block' : 'none';
}

export function combineAndRenderNotifications() {
    const mergedMap = new Map();
    const isAdmin = isUserAdmin(currentUser, currentProfile) || checkIsAdminUser(currentUser, currentProfile);
    [...userNotifications, ...broadcastNotifications, ...adminNotifications].forEach(n => {
        if (!deletedNotifIds.has(n.id)) {
            const isSecurityAiNotif = n.toUid === 'admin' || n.forAdmin || 
                /Seguran[çc]a IA/i.test(n.title || '') || 
                /algoritmo de den[úu]ncia/i.test(n.message || '') ||
                /algoritmo de seguran[çc]a/i.test(n.message || '');
            if (isSecurityAiNotif && !isAdmin) {
                return; // Usuário comum NUNCA vê notificações de moderação/segurança da IA!
            }
            mergedMap.set(n.id, n);
        }
    });
    allNotifications = Array.from(mergedMap.values());
    allNotifications.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

    updateNotificationsBadge();
    renderNotifications();
}

export function setAllNotifications(notifs) {
    allNotifications = Array.isArray(notifs) ? [...notifs] : [];
    renderNotifications();
}

export function setAdminNotifications(notifs) {
    adminNotifications = Array.isArray(notifs) ? [...notifs] : [];
    combineAndRenderNotifications();
}

export function getAdminNotifications() {
    return adminNotifications;
}

export async function cleanupLegacySecurityBroadcasts() {
    try {
        const isAdmin = isUserAdmin(currentUser, currentProfile) || checkIsAdminUser(currentUser, currentProfile);
        if (!isAdmin) return;
        const q = query(collection(db, 'notifications'), where('toUid', '==', 'all'), limit(30));
        const snap = await getDocs(q).catch(() => null);
        if (snap && snap.docs) {
            for (const d of snap.docs) {
                const data = d.data();
                if (/Seguran[çc]a IA/i.test(data.title || '') || /algoritmo de den[úu]ncia/i.test(data.message || '') || /algoritmo de seguran[çc]a/i.test(data.message || '')) {
                    await updateDoc(doc(db, 'notifications', d.id), {
                        toUid: 'admin',
                        forAdmin: true
                    }).catch(() => {});
                }
            }
        }
    } catch (e) {}
}

export function listenToNotifications() {
    if (!currentUser) return;
    if (notificationsUnsubscribe) notificationsUnsubscribe();
    if (broadcastUnsubscribe) broadcastUnsubscribe();
    if (adminNotifUnsubscribe) adminNotifUnsubscribe();

    try {
        // 1. Notificações diretas para o usuário (ex: Selo VIP aprovado)
        const userQuery = query(collection(db, 'notifications'), where('toUid', '==', currentUser.uid), limit(25));
        notificationsUnsubscribe = onSnapshot(userQuery, (snapshot) => {
            if (snapshot && typeof snapshot.docChanges === 'function') {
                snapshot.docChanges().forEach(change => {
                    if (change.type === 'added') {
                        const data = change.doc.data();
                        const notifId = change.doc.id;
                        if (!readNotifIds.has(notifId) && !deletedNotifIds.has(notifId)) {
                            const toastColor = data.type === 'vip' ? 'green' : (data.type === 'alert' ? 'red' : 'blue');
                            showToast(data.title || 'Notificação VIP', data.message || '', toastColor);
                            playSound(notificationSound);
                        }
                    }
                });
            }
            userNotifications = (snapshot && snapshot.docs) ? snapshot.docs.map(d => ({ id: d.id, ...d.data() })) : [];
            combineAndRenderNotifications();
        }, (error) => console.warn('Erro ao ouvir notificações do usuário:', error));

        // 2. Transmissões gerais da plataforma (toUid == 'all')
        const broadcastQuery = query(collection(db, 'notifications'), where('toUid', '==', 'all'), limit(25));
        broadcastUnsubscribe = onSnapshot(broadcastQuery, (snapshot) => {
            if (snapshot && typeof snapshot.docChanges === 'function') {
                snapshot.docChanges().forEach(change => {
                    if (change.type === 'added') {
                        const data = change.doc.data();
                        const notifId = change.doc.id;
                        const isSecurityAiNotif = data.toUid === 'admin' || data.forAdmin || 
                            /Seguran[çc]a IA/i.test(data.title || '') || 
                            /algoritmo de den[úu]ncia/i.test(data.message || '') ||
                            /algoritmo de seguran[çc]a/i.test(data.message || '');
                        
                        // Segurança estrita: usuário comum NUNCA é notificado sobre ações de segurança/moderação da IA
                        if (isSecurityAiNotif && !isUserAdmin(currentUser, currentProfile) && !checkIsAdminUser(currentUser, currentProfile)) {
                            return;
                        }

                        if (!readNotifIds.has(notifId) && !deletedNotifIds.has(notifId)) {
                            const toastColor = data.type === 'alert' ? 'red' : 'blue';
                            showToast(data.title || 'Aviso da Plataforma', data.message || '', toastColor);
                            playSound(notificationSound);
                        }
                    }
                });
            }
            broadcastNotifications = (snapshot && snapshot.docs) ? snapshot.docs.map(d => ({ id: d.id, ...d.data() })) : [];
            combineAndRenderNotifications();
        }, (error) => console.warn('Erro ao ouvir avisos e alertas gerais:', error));

        // 3. Notificações EXCLUSIVAS para Administradores da Plataforma (toUid == 'admin')
        const isAdmin = isUserAdmin(currentUser, currentProfile) || checkIsAdminUser(currentUser, currentProfile);
        if (isAdmin) {
            const adminQuery = query(collection(db, 'notifications'), where('toUid', '==', 'admin'), limit(25));
            adminNotifUnsubscribe = onSnapshot(adminQuery, (snapshot) => {
                if (snapshot && typeof snapshot.docChanges === 'function') {
                    snapshot.docChanges().forEach(change => {
                        if (change.type === 'added') {
                            const data = change.doc.data();
                            const notifId = change.doc.id;
                            if (!readNotifIds.has(notifId) && !deletedNotifIds.has(notifId)) {
                                const toastColor = data.type === 'alert' ? 'red' : 'yellow';
                                showToast(data.title || 'Alerta de Moderação ADM', data.message || '', toastColor);
                                playSound(notificationSound);
                            }
                        }
                    });
                }
                adminNotifications = (snapshot && snapshot.docs) ? snapshot.docs.map(d => ({ id: d.id, ...d.data() })) : [];
                combineAndRenderNotifications();
            }, (error) => console.warn('Erro ao ouvir notificações de administrador:', error));

            cleanupLegacySecurityBroadcasts();
        }
    } catch (err) {
        console.warn('Falha ao inicializar listeners de notificações:', err);
    }
}

export function openNotificationsPanel() {
    playSound(clickSound);
    const panel = document.getElementById('notifications-panel');
    if (!panel) return;
    panel.classList.add('active');

    // Ao abrir a central de notificações, marca todas visíveis como lidas
    allNotifications.forEach(n => readNotifIds.add(n.id));
    saveNotifStorage();
    updateNotificationsBadge();
    renderNotifications();
}

export function closeNotificationsPanel() {
    playSound(clickSound);
    document.getElementById('notifications-panel')?.classList.remove('active');
}

export function clearAllNotifications() {
    allNotifications.forEach(n => {
        deletedNotifIds.add(n.id);
        readNotifIds.add(n.id);
        if (currentUser && n.toUid === currentUser.uid) {
            deleteDoc(doc(db, 'notifications', n.id)).catch(() => {});
        }
    });
    saveNotifStorage();
    combineAndRenderNotifications();
    showToast("Notificações", "Todas as notificações foram limpas.", "blue");
}

export async function deleteSingleNotification(notifId) {
    if (!notifId) return;
    deletedNotifIds.add(notifId);
    readNotifIds.add(notifId);
    saveNotifStorage();

    const targetNotif = allNotifications.find(n => n.id === notifId);
    userNotifications = userNotifications.filter(n => n.id !== notifId);
    broadcastNotifications = broadcastNotifications.filter(n => n.id !== notifId);
    allNotifications = allNotifications.filter(n => n.id !== notifId);

    if (targetNotif && currentUser && targetNotif.toUid === currentUser.uid) {
        try {
            await deleteDoc(doc(db, 'notifications', notifId));
        } catch (err) {
            // Silencioso caso não tenha permissão ou já tenha sido removido
        }
    }

    updateNotificationsBadge();
    renderNotifications();
}

export function attachNotificationSwipeHandlers(listEl) {
    if (!listEl || typeof listEl.querySelectorAll !== 'function') return;
    const cards = listEl.querySelectorAll('.notification-card');
    cards.forEach(card => {
        const notifId = card.dataset?.id || card.getAttribute?.('data-id');
        const wrapper = card.closest ? card.closest('.notification-swipe-wrapper') : card.parentElement;
        let startX = 0;
        let startY = 0;
        let currentX = 0;
        let isDragging = false;
        let isHorizontal = null;

        const handleStart = (clientX, clientY) => {
            startX = Number(clientX) || 0;
            startY = Number(clientY) || 0;
            currentX = 0;
            isDragging = true;
            isHorizontal = null;
            if (card.style) card.style.transition = 'none';
        };

        const handleMove = (clientX, clientY, ev) => {
            if (!isDragging) return;
            const dx = (Number(clientX) || 0) - startX;
            const dy = (Number(clientY) || 0) - startY;

            if (isHorizontal === null) {
                if (Math.abs(dx) > 6 || Math.abs(dy) > 6) {
                    isHorizontal = Math.abs(dx) >= Math.abs(dy);
                }
            }
            if (!isHorizontal) return;

            if (dx < 0) {
                if (ev && typeof ev.preventDefault === 'function' && ev.cancelable) {
                    ev.preventDefault();
                }
                currentX = Math.max(-180, dx);
                if (card.style) card.style.transform = `translateX(${currentX}px)`;
                if (wrapper && wrapper.classList) {
                    wrapper.classList.toggle('swiping-left', currentX < -10);
                }
            } else {
                currentX = 0;
                if (card.style) card.style.transform = 'translateX(0px)';
                if (wrapper && wrapper.classList) {
                    wrapper.classList.remove('swiping-left');
                }
            }
        };

        const handleEnd = () => {
            if (!isDragging) return;
            isDragging = false;
            if (currentX <= -65) {
                if (card.style) {
                    card.style.transition = 'transform 0.2s ease-out, opacity 0.2s ease-out';
                    card.style.transform = 'translateX(-110%)';
                    card.style.opacity = '0';
                }
                if (wrapper && wrapper.classList) {
                    wrapper.classList.add('swipe-deleting');
                }
                deleteSingleNotification(notifId);
            } else {
                if (card.style) {
                    card.style.transition = 'transform 0.2s ease-out';
                    card.style.transform = 'translateX(0px)';
                }
                if (wrapper && wrapper.classList) {
                    wrapper.classList.remove('swiping-left');
                }
            }
        };

        card._swipeStart = handleStart;
        card._swipeMove = handleMove;
        card._swipeEnd = handleEnd;

        if (typeof card.addEventListener === 'function') {
            card.addEventListener('touchstart', (e) => {
                const t = e.touches && e.touches[0];
                if (t) handleStart(t.clientX, t.clientY);
            }, { passive: true });

            card.addEventListener('touchmove', (e) => {
                const t = e.touches && e.touches[0];
                if (t) handleMove(t.clientX, t.clientY, e);
            }, { passive: false });

            card.addEventListener('touchend', handleEnd);
            card.addEventListener('touchcancel', handleEnd);

            card.addEventListener('mousedown', (e) => {
                if (e.button !== undefined && e.button !== 0) return;
                handleStart(e.clientX, e.clientY);
            });
            card.addEventListener('mousemove', (e) => {
                if (!isDragging) return;
                handleMove(e.clientX, e.clientY, e);
            });
            card.addEventListener('mouseup', handleEnd);
            card.addEventListener('mouseleave', () => {
                if (isDragging) handleEnd();
            });
        }
    });
}

export function renderNotifications() {
    const listEl = document.getElementById('notifications-list');
    if (!listEl) return;

    const isAdmin = isUserAdmin(currentUser, currentProfile) || checkIsAdminUser(currentUser, currentProfile);

    let filtered = allNotifications.filter(n => {
        if (deletedNotifIds.has(n.id)) return false;
        const isSecurityAiNotif = n.toUid === 'admin' || n.forAdmin || 
            /Seguran[çc]a IA/i.test(n.title || '') || 
            /algoritmo de den[úu]ncia/i.test(n.message || '') ||
            /algoritmo de seguran[çc]a/i.test(n.message || '');
        if (isSecurityAiNotif && !isAdmin) return false;

        if (currentNotifFilter === 'vip') return n.type === 'vip';
        if (currentNotifFilter === 'warning') return !n.type || n.type === 'warning' || n.type === 'group_add' || n.type === 'group_promote';
        if (currentNotifFilter === 'alert') return n.type === 'alert';
        return true;
    });

    if (filtered.length === 0) {
        listEl.innerHTML = `
            <div class="admin-empty-state">
                <i data-lucide="bell-off" class="empty-state-icon"></i>
                <p>Nenhuma notificação no momento.</p>
                <small>Você receberá aqui avisos ⚠️, alertas da plataforma 🔴 e a aprovação do seu Selo VIP ⭐.</small>
            </div>
        `;
        if (window.lucide) lucide.createIcons();
        return;
    }

    listEl.innerHTML = filtered.map(n => {
        const type = n.type || 'warning';
        const titleRaw = String(n.title || '');
        const msgRaw = String(n.message || '');

        const isVip = type === 'vip';
        const isAlert = type === 'alert';
        const isGroupPromote = type === 'group_promote' ||
            /Você é admin do grupo|admin do grupo/i.test(titleRaw) ||
            /promovido a administrador/i.test(msgRaw);
        const isStoryLike = !isGroupPromote && (type === 'like_story' || type === 'story_like' || (/story/i.test(titleRaw) && /curtiu|reagiu/i.test(titleRaw)) || /ao seu story/i.test(msgRaw));
        const isLike = !isGroupPromote && !isStoryLike && (type === 'like_post' || type === 'like' || /curtiu|reagiu/i.test(titleRaw) || /curtiu a sua publica/i.test(msgRaw));
        const isComment = !isGroupPromote && (type === 'comment_post' || type === 'comment' || /comentou/i.test(titleRaw) || /comentou na sua publica/i.test(msgRaw));
        const isGroupAdd = !isGroupPromote && (type === 'group_add' || /adicionado a um grupo|adicionado ao grupo/i.test(titleRaw) || /adicionado ao grupo/i.test(msgRaw));
        const isSecurityAdmin = (n.toUid === 'admin' || n.forAdmin || /Seguran[çc]a IA/i.test(titleRaw) || /algoritmo de den[úu]ncia/i.test(msgRaw) || /algoritmo de seguran[çc]a/i.test(msgRaw));

        let typeClass = 'warning';
        let badgeText = 'AVISO ⚠️';
        let iconHTML = '<i data-lucide="alert-triangle"></i>';
        let displayTitle = titleRaw || 'Notificação';

        if (isVip) {
            typeClass = 'vip';
            badgeText = 'SELO VIP ⭐';
            iconHTML = '<i data-lucide="sparkles"></i>';
        } else if (isSecurityAdmin) {
            typeClass = isAlert ? 'alert' : 'warning';
            badgeText = 'MODERAÇÃO 🛡️';
            iconHTML = isAlert ? '<i data-lucide="shield-alert"></i>' : '<i data-lucide="shield"></i>';
        } else if (isAlert) {
            typeClass = 'alert';
            badgeText = 'ALERTA 🔴';
            iconHTML = '<i data-lucide="shield-alert"></i>';
        } else if (isGroupPromote) {
            typeClass = 'group-promote';
            badgeText = 'ADMIN 🎓';
            displayTitle = displayTitle.replace(/^🛡️\s*/, '').trim();
            if (!displayTitle.includes('🎓')) displayTitle = `🎓 ${displayTitle}`;
            iconHTML = `
                <svg class="notif-custom-svg notif-svg-group-promote" viewBox="0 0 24 24" width="22" height="22" fill="currentColor" aria-hidden="true">
                    <path d="M12 2L1 8.2l11 6.2 9.2-5.18V17h1.8V8.2L12 2z"/>
                    <path d="M5 12.3v3.2c0 2.8 3.1 5 7 5s7-2.2 7-5v-3.2l-7 3.9-7-3.9z"/>
                </svg>
            `;
        } else if (isStoryLike) {
            typeClass = 'story-like';
            badgeText = 'STORY';
            displayTitle = displayTitle.replace(/^(❤️|🩷|👍|🔥|😍|👏|😂|😮|😢)\s*/, '');
            iconHTML = `
                <svg class="notif-custom-svg notif-svg-story-like" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>
                </svg>
            `;
        } else if (isLike) {
            typeClass = 'like';
            badgeText = 'CURTIDA';
            displayTitle = displayTitle.replace(/^(❤️|👍)\s*/, '');
            iconHTML = `
                <svg class="notif-custom-svg notif-svg-like" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"></path>
                </svg>
            `;
        } else if (isComment) {
            typeClass = 'comment';
            badgeText = 'COMENTÁRIO';
            displayTitle = displayTitle.replace(/^💬\s*/, '');
            iconHTML = `
                <svg class="notif-custom-svg notif-svg-comment" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path>
                </svg>
            `;
        } else if (isGroupAdd) {
            typeClass = 'group-add';
            badgeText = 'GRUPO';
            iconHTML = `
                <svg class="notif-custom-svg notif-svg-group-add" viewBox="0 0 24 24" width="22" height="22" fill="none" aria-hidden="true">
                    <path d="M10.5 3C5.8 3 2 6.13 2 10c0 1.78.8 3.4 2.13 4.64-.18.96-.68 2.1-1.35 2.86-.2.22-.04.58.26.55 1.48-.15 3.02-.68 4.12-1.35.99.2 2.04.3 3.14.3 4.7 0 8.5-3.13 8.5-7S15.2 3 10.5 3z" fill="currentColor"/>
                    <path d="M19.87 17.64C21.2 16.4 22 14.78 22 13c0-2.98-2.26-5.52-5.46-6.52.29.88.46 1.82.46 2.82 0 4.86-4.48 8.7-10.12 8.98 1.25 1.65 3.51 2.72 6.12 2.72.9 0 1.77-.1 2.58-.28.98.6 2.34 1.08 3.66 1.22.28.03.44-.31.25-.52-.6-.68-1.05-1.7-1.22-2.58z" fill="currentColor"/>
                </svg>
            `;
        }

        const isUnread = !readNotifIds.has(n.id);
        const timeStr = n.createdAt ? formatLastSeen(n.createdAt) : 'Recentemente';

        return `
            <div class="notification-swipe-wrapper" data-id="${n.id}">
                <div class="notification-swipe-delete-bg" aria-hidden="true">
                    <i data-lucide="trash-2"></i>
                    <span>Apagar</span>
                </div>
                <div class="notification-card card-${typeClass} ${isUnread ? 'unread' : ''}" data-id="${n.id}">
                    <div class="notification-icon-box ${typeClass}">
                        ${iconHTML}
                    </div>
                    <div class="notification-card-content">
                        <div class="notification-card-top">
                            <span class="notification-card-title">${escapeHTML(displayTitle)}</span>
                            <span class="notification-badge ${typeClass}">${badgeText}</span>
                        </div>
                        <div class="notification-card-text">${escapeHTML(n.message || '')}</div>
                        <div class="notification-card-time">
                            <i data-lucide="clock" style="width:11px; height:11px;"></i> ${timeStr}
                        </div>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    if (window.lucide) lucide.createIcons();
    attachNotificationSwipeHandlers(listEl);
}

export const ONLINE_PRESENCE_TTL_MS = 75000; // 75s de tolerância máxima (heartbeat a cada 25s)
const rtdbContactPresenceMap = new Map();
const contactUserDataMap = new Map();
let activeContactProfileUid = null;
let activeContactProfileRtdbUnsubscribe = null;
let activeChatRtdbPresenceUnsubscribe = null;

export function extractPresenceTimestampMs(val) {
    if (!val) return 0;
    if (typeof val === 'number') return val;
    if (typeof val.toMillis === 'function') return val.toMillis();
    if (typeof val.seconds === 'number') return val.seconds * 1000;
    const parsed = new Date(val).getTime();
    return Number.isFinite(parsed) ? parsed : 0;
}

export function getContactLastSeenTimestamp(userData, contactUid = '') {
    const uid = contactUid || userData?.uid || '';
    const uData = userData || (uid ? contactUserDataMap.get(uid) : null);
    const fsMs = extractPresenceTimestampMs(uData?.lastSeen);
    const rtdbPres = uid ? rtdbContactPresenceMap.get(uid) : null;
    const rtdbMs = extractPresenceTimestampMs(rtdbPres?.last_changed);
    const best = Math.max(fsMs, rtdbMs);
    return best > 0 ? best : (uData?.lastSeen || null);
}

export function isContactTrulyOnline(userData, contactUid = '') {
    const uid = contactUid || userData?.uid || '';
    if (uid && (blockedContactsSet.has(uid) || (activeChatContact?.uid === uid && isBlockedByActiveContact))) {
        return false;
    }
    const uData = userData || (uid ? contactUserDataMap.get(uid) : null);
    if (!uData || uData.ghostMode || !uData.online) return false;

    if (uid && rtdbContactPresenceMap.has(uid)) {
        const rtdbPres = rtdbContactPresenceMap.get(uid);
        if (!rtdbPres || rtdbPres.state === 'offline') {
            const rtdbChangedMs = extractPresenceTimestampMs(rtdbPres?.last_changed);
            const fsLastSeenMs = extractPresenceTimestampMs(uData.lastSeen);
            if (!rtdbPres || !fsLastSeenMs || !rtdbChangedMs || rtdbChangedMs >= fsLastSeenMs - 5000) {
                return false;
            }
        } else if (rtdbPres.state === 'online') {
            const rtdbChangedMs = extractPresenceTimestampMs(rtdbPres.last_changed);
            const fsLastSeenMs = extractPresenceTimestampMs(uData.lastSeen);
            const latestMs = Math.max(rtdbChangedMs, fsLastSeenMs);
            if (latestMs > 0 && (Date.now() - latestMs) > ONLINE_PRESENCE_TTL_MS) {
                return false;
            }
        }
    }

    const lastSeenMs = extractPresenceTimestampMs(uData.lastSeen);
    if (lastSeenMs > 0 && (Date.now() - lastSeenMs) > ONLINE_PRESENCE_TTL_MS) {
        return false;
    }

    return true;
}

export function refreshContactProfilePresenceUI(contactUid = activeContactProfileUid) {
    if (!contactUid) return;
    const presenceEl = document.getElementById('contact-profile-presence');
    const onlineDotEl = document.getElementById('contact-profile-online-dot');
    const isBlocked = blockedContactsSet.has(contactUid) || !!(activeChatContact && activeChatContact.uid === contactUid && isBlockedByActiveContact);

    if (isBlocked) {
        if (presenceEl) presenceEl.innerText = 'Bloqueado';
        if (onlineDotEl) onlineDotEl.style.display = 'none';
        return;
    }

    const uData = (activeContactProfileUid === contactUid && activeContactProfileData)
        ? activeContactProfileData
        : contactUserDataMap.get(contactUid);

    const isOnline = isContactTrulyOnline(uData, contactUid);
    if (onlineDotEl) {
        onlineDotEl.style.display = isOnline ? 'block' : 'none';
    }
    if (presenceEl) {
        const lastSeenTs = getContactLastSeenTimestamp(uData, contactUid);
        presenceEl.innerText = isOnline
            ? 'Online agora'
            : (lastSeenTs ? `Visto por último: ${formatLastSeen(lastSeenTs)}` : 'Visto recentemente');
    }
}

function setupPresence(uid) {
    const userDocRef = doc(db, 'users', uid);
    const myConnectionsRef = ref(rtdb, `presence/${uid}`);
    const connectedRef = ref(rtdb, '.info/connected');

    if (!currentProfile.ghostMode) {
        const ts = Date.now();
        updateDoc(userDocRef, { online: true, lastSeen: ts }).catch(() => {});
        rtdbSet(myConnectionsRef, { state: 'online', last_changed: ts }).catch(() => {});
    }

    onValue(connectedRef, (snap) => {
        if (snap.val() === true) {
            onDisconnect(myConnectionsRef).set({ state: 'offline', last_changed: rtdbTimestamp() });
            if (!currentProfile.ghostMode) {
                const ts = Date.now();
                rtdbSet(myConnectionsRef, { state: 'online', last_changed: ts }).catch(() => {});
                updateDoc(userDocRef, { online: true, lastSeen: ts }).catch(() => {});
            } else {
                rtdbSet(myConnectionsRef, { state: 'offline', last_changed: Date.now() }).catch(() => {});
            }
        }
    });

    const setOffline = () => {
        if (currentUser) {
            const ts = Date.now();
            rtdbSet(myConnectionsRef, { state: 'offline', last_changed: ts }).catch(() => {});
            updateDoc(userDocRef, { online: false, lastSeen: ts }).catch(() => {});
        }
    };

    const setOnline = () => {
        if (!currentProfile.ghostMode && currentUser) {
            const ts = Date.now();
            rtdbSet(myConnectionsRef, { state: 'online', last_changed: ts }).catch(() => {});
            updateDoc(userDocRef, { online: true, lastSeen: ts }).catch(() => {});
        }
    };

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') setOffline();
        else if (document.visibilityState === 'visible') setOnline();
    });

    window.addEventListener('pagehide', setOffline);
    window.addEventListener('beforeunload', setOffline);

    // Heartbeat de presença ativo a cada 25s enquanto a aba estiver visível
    setInterval(() => {
        if (!currentProfile.ghostMode && currentUser && document.visibilityState === 'visible') {
            const ts = Date.now();
            updateDoc(userDocRef, { online: true, lastSeen: ts }).catch(() => {});
            rtdbSet(myConnectionsRef, { state: 'online', last_changed: ts }).catch(() => {});
        }
    }, 25000);

    // Verificação periódica para expirar status online fantasma de contatos inativos
    setInterval(() => {
        contactUserDataMap.forEach((uData, cUid) => {
            const dot = document.getElementById(`online-dot-${cUid}`);
            if (dot) {
                dot.style.display = isContactTrulyOnline(uData, cUid) ? 'block' : 'none';
            }
        });
        if (activeChatContact && !activeChatContact.isGroup) {
            refreshDirectChatStatus();
        }
        if (activeContactProfileUid) {
            refreshContactProfilePresenceUI(activeContactProfileUid);
        }
    }, 15000);
}

function applyPrivacyModeState() {
    const enabled = !!currentProfile.privacyMode;
    document.body.classList.toggle('privacy-mode', enabled);

    document.querySelectorAll('.message, .last-msg, .quoted-reply-box, .audio-player-ui, img, video, .file-attachment-card').forEach((el) => {
        if (el instanceof HTMLElement) {
            el.style.filter = enabled ? 'blur(8px)' : '';
            el.style.opacity = enabled ? '0.8' : '';
            el.style.transition = 'filter 0.2s ease, opacity 0.2s ease';
        }
    });

    document.querySelectorAll('.message:hover, .message:hover *, .message:hover .last-msg').forEach((el) => {
        if (el instanceof HTMLElement) {
            el.style.filter = '';
            el.style.opacity = '1';
        }
    });
}

export const VORTEX_ADMIN_EMAILS = [
    'dxhub.oficial@gmail.com',
    'vortex.dx.oficial@gmail.com',
    'dxhubdigitalsuporte@gmail.com'
];

export const adminUidsSet = new Set();
export const deletedUsersSet = new Set();

export function isUserAccountDeleted(uid) {
    if (!uid) return false;
    return deletedUsersSet.has(uid);
}

export function getVipSubscriptionState(user) {
    if (!user) return { status: 'none', isVip: false, daysRemaining: 0, graceDaysRemaining: 0 };
    const email = (user.email || '').toLowerCase().trim();
    const username = (user.username || '').toLowerCase().trim().replace(/^@/, '');
    const name = (user.name || '').trim();
    if (VORTEX_ADMIN_EMAILS.includes(email) || username === 'dxhuboficial' || user.role === 'admin' || name.includes('DX Hub')) {
        return { status: 'active', isVip: true, daysRemaining: 9999, graceDaysRemaining: 0 };
    }

    // Suporte flexível a diferentes formatos de data de expiração (Timestamp Firestore, Date, ISO string, número)
    let expiresAt = 0;
    if (user.vipExpiresAt) {
        if (typeof user.vipExpiresAt.toMillis === 'function') {
            expiresAt = user.vipExpiresAt.toMillis();
        } else if (typeof user.vipExpiresAt.toDate === 'function') {
            expiresAt = user.vipExpiresAt.toDate().getTime();
        } else if (user.vipExpiresAt.seconds) {
            expiresAt = user.vipExpiresAt.seconds * 1000;
        } else if (typeof user.vipExpiresAt === 'string') {
            expiresAt = isNaN(Number(user.vipExpiresAt)) ? new Date(user.vipExpiresAt).getTime() : Number(user.vipExpiresAt);
        } else {
            expiresAt = Number(user.vipExpiresAt) || 0;
        }
    }

    if (user.isVip === false && user.isVerified === false && !expiresAt) {
        return { status: 'none', isVip: false, daysRemaining: 0, graceDaysRemaining: 0 };
    }

    // Se for VIP manual/admin ou assinatura sem prazo de validade definido (vitalício/teste/aprovado)
    if ((user.isVip || user.isVerified || user.vipStatus === 'active' || user.vipRequestStatus === 'approved') && !expiresAt) {
        return { status: 'active', isVip: true, daysRemaining: 9999, graceDaysRemaining: 0 };
    }

    const now = Date.now();
    const graceMs = 7 * 24 * 60 * 60 * 1000; // 7 dias de tolerância
    const graceExpiresAt = expiresAt + graceMs;

    if (now < expiresAt) {
        const daysRemaining = Math.max(1, Math.ceil((expiresAt - now) / (24 * 60 * 60 * 1000)));
        return { status: 'active', isVip: true, daysRemaining, graceDaysRemaining: 0 };
    } else if (now <= graceExpiresAt) {
        const graceDaysRemaining = Math.max(0, Math.ceil((graceExpiresAt - now) / (24 * 60 * 60 * 1000)));
        return { status: 'grace_period', isVip: true, daysRemaining: 0, graceDaysRemaining };
    } else {
        return { status: 'expired', isVip: false, daysRemaining: 0, graceDaysRemaining: 0 };
    }
}

export function checkIsVipUser(user) {
    if (!user) return false;
    const sub = getVipSubscriptionState(user);
    return sub.isVip;
}

export function checkIsAdminUser(userOrData) {
    if (!userOrData) return false;

    // Extrai o email de qualquer propriedade conhecida do objeto
    const email = (
        userOrData.email || 
        userOrData.senderEmail || 
        userOrData.authorEmail || 
        userOrData.userEmail || 
        userOrData.contactEmail || 
        ''
    ).toLowerCase().trim();

    const uid = userOrData.uid || userOrData.userId || userOrData.authorUid || userOrData.senderUid || '';

    // Regra estrita: Se o email estiver presente, ele DEVE ser um dos 3 emails autorizados (e ninguém mais)
    if (email) {
        const isMatch = VORTEX_ADMIN_EMAILS.includes(email);
        if (isMatch && uid) adminUidsSet.add(uid);
        return isMatch;
    }

    // Se for o próprio usuário logado no cliente
    if (typeof currentUser !== 'undefined' && currentUser) {
        const myEmail = (currentUser.email || (typeof currentProfile !== 'undefined' && currentProfile?.email) || '').toLowerCase().trim();
        if ((userOrData === currentUser || (typeof currentProfile !== 'undefined' && userOrData === currentProfile) || (uid && uid === currentUser.uid))) {
            const isMatch = VORTEX_ADMIN_EMAILS.includes(myEmail);
            if (isMatch && currentUser.uid) adminUidsSet.add(currentUser.uid);
            return isMatch;
        }
    }

    // Se o UID foi previamente autenticado como pertencente a um dos 3 emails
    if (uid && adminUidsSet.has(uid)) {
        return true;
    }

    // Ninguém mais tem o selo de administrador
    return false;
}

export function updateVerifiedBadgeElement(badgeEl, userOrData) {
    if (!badgeEl) return;
    const isAdmin = !!(userOrData && checkIsAdminUser(userOrData));
    const isVip = !!(userOrData && (checkIsVipUser(userOrData) || userOrData.isVip || userOrData.isVerified || isAdmin));
    const displayVal = (badgeEl.id === 'user-verified-badge' || badgeEl.id === 'story-verified-badge') ? 'inline-block' : 'inline-flex';

    if (isAdmin) {
        if (badgeEl.style) badgeEl.style.display = displayVal;
        if (badgeEl.classList) badgeEl.classList.add('active', 'verified-badge-admin');
        if (typeof badgeEl.setAttribute === 'function') {
            badgeEl.setAttribute('data-admin-badge', 'true');
            badgeEl.setAttribute('title', '💥Admin⚡');
        }
    } else if (isVip) {
        if (badgeEl.style) badgeEl.style.display = displayVal;
        if (badgeEl.classList) {
            badgeEl.classList.add('active');
            badgeEl.classList.remove('verified-badge-admin');
        }
        if (typeof badgeEl.removeAttribute === 'function') badgeEl.removeAttribute('data-admin-badge');
        if (typeof badgeEl.setAttribute === 'function') badgeEl.setAttribute('title', 'Verificado VIP');
    } else {
        if (badgeEl.style) badgeEl.style.display = 'none';
        if (badgeEl.classList) badgeEl.classList.remove('active', 'verified-badge-admin');
        if (typeof badgeEl.removeAttribute === 'function') badgeEl.removeAttribute('data-admin-badge');
    }
}

export function showAdminBadgeToast(event, element) {
    if (event) {
        event.stopPropagation();
        if (event.cancelable) event.preventDefault?.();
    }
    
    if (typeof document !== 'undefined') {
        document.querySelectorAll('.admin-badge-toast-yellow').forEach(el => el.remove());

        const toast = document.createElement('div');
        toast.className = 'admin-badge-toast-yellow';
        toast.setAttribute('role', 'alert');
        toast.innerHTML = '<span>💥Admin⚡</span>';

        let left = typeof window !== 'undefined' ? window.innerWidth / 2 : 150;
        let top = 60;

        if (element && typeof element.getBoundingClientRect === 'function') {
            const rect = element.getBoundingClientRect();
            if (rect && (rect.width > 0 || rect.height > 0 || rect.top > 0 || rect.left > 0)) {
                const winWidth = typeof window !== 'undefined' ? window.innerWidth : 360;
                left = Math.max(55, Math.min(winWidth - 55, rect.left + rect.width / 2));
                top = rect.top;
            }
        }

        toast.style.left = `${left}px`;
        toast.style.top = `${top}px`;

        if (top < 55) {
            toast.classList.add('position-below');
        }

        document.body.appendChild(toast);

        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(() => toast.classList.add('active'));
        } else {
            toast.classList.add('active');
        }

        if (typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') {
            try { navigator.vibrate([35, 25, 35]); } catch (_) {}
        }

        if (typeof playSound === 'function' && typeof clickSound !== 'undefined') {
            try { playSound(clickSound); } catch (_) {}
        }

        setTimeout(() => {
            toast.classList.remove('active');
            setTimeout(() => toast.remove(), 250);
        }, 2200);
    }
}


export let vipGraceBannerDismissed = false;

export function dismissVipGraceBanner() {
    vipGraceBannerDismissed = true;
    const banner = document.getElementById('vip-grace-banner');
    if (banner) {
        banner.style.display = 'none';
    }
    try {
        if (typeof sessionStorage !== 'undefined') {
            sessionStorage.setItem('vortex_vip_grace_dismissed', 'true');
        }
    } catch (_) {}
}

export function checkVipSubscriptionLifecycle() {
    if (!currentUser || !currentProfile) return;
    const sub = getVipSubscriptionState(currentProfile);
    const banner = document.getElementById('vip-grace-banner');
    const daysLeftEl = document.getElementById('vip-grace-days-left');

    if (sub.status === 'grace_period') {
        let isDismissed = vipGraceBannerDismissed;
        try {
            if (!isDismissed && typeof sessionStorage !== 'undefined' && sessionStorage.getItem('vortex_vip_grace_dismissed') === 'true') {
                isDismissed = true;
            }
        } catch (_) {}
        if (banner) {
            banner.style.display = isDismissed ? 'none' : 'flex';
            if (daysLeftEl) {
                daysLeftEl.innerText = `${sub.graceDaysRemaining} ${sub.graceDaysRemaining === 1 ? 'dia' : 'dias'}`;
            }
        }
    } else {
        vipGraceBannerDismissed = false;
        try {
            if (typeof sessionStorage !== 'undefined') {
                sessionStorage.removeItem('vortex_vip_grace_dismissed');
            }
        } catch (_) {}
        if (banner) banner.style.display = 'none';
    }

    // Se a assinatura expirou após os 7 dias de tolerância
    if (sub.status === 'expired' && (currentProfile.isVip || currentProfile.isVerified || currentProfile.vipStatus !== 'expired')) {
        currentProfile.isVip = false;
        currentProfile.isVerified = false;
        currentProfile.vipStatus = 'expired';

        if (currentUser && currentUser.uid) {
            updateDoc(doc(db, 'users', currentUser.uid), {
                isVip: false,
                isVerified: false,
                vipStatus: 'expired'
            }).catch(() => {});
        }

        const userBadge = document.getElementById('user-verified-badge');
        if (userBadge) userBadge.style.display = 'none';

        const subscribeBtn = document.getElementById('subscribe-btn');
        if (subscribeBtn) {
            subscribeBtn.innerText = 'Assinar';
            subscribeBtn.className = 'danger-btn vip-action-btn';
        }

        showToast('Assinatura Expirada', 'Seu período de tolerância de 7 dias terminou. O Selo VIP foi removido.', 'orange');
    }
}

// ==========================================================================
// Chuva de Códigos Binários (0 e 1) - Tema Hacker Matrix VIP
// ==========================================================================
let matrixCanvasAnimId = null;
let matrixColumns = [];
let feedMatrixColumns = [];
let matrixCanvasInitialized = false;

export function initBinaryMatrixCanvas() {
    if (typeof document === 'undefined') return null;
    const canvas = document.getElementById('matrix-binary-canvas');
    const feedCanvas = document.getElementById('feed-matrix-canvas');
    if (!canvas && !feedCanvas) return null;
    const ctx = canvas && canvas.getContext ? canvas.getContext('2d') : null;

    function resize() {
        const winW = (typeof window !== 'undefined' && window.innerWidth) ? window.innerWidth : 800;
        const winH = (typeof window !== 'undefined' && window.innerHeight) ? window.innerHeight : 600;
        const fontSize = 15;

        if (canvas) {
            canvas.width = winW;
            canvas.height = winH;
            const cols = Math.floor(canvas.width / fontSize) || 20;
            matrixColumns = Array.from({ length: cols }, () => Math.floor(Math.random() * -50));
        }

        if (feedCanvas) {
            const parent = feedCanvas.parentElement;
            feedCanvas.width = (parent && parent.clientWidth) || winW;
            feedCanvas.height = (parent && parent.clientHeight) || winH;
            const feedCols = Math.floor(feedCanvas.width / fontSize) || 20;
            feedMatrixColumns = Array.from({ length: feedCols }, () => Math.floor(Math.random() * -50));
        }
    }

    if (!matrixCanvasInitialized && typeof window !== 'undefined' && window.addEventListener) {
        window.addEventListener('resize', resize);
        matrixCanvasInitialized = true;
    }
    resize();
    return { canvas, ctx };
}

export function startBinaryMatrix() {
    const setup = initBinaryMatrixCanvas();
    if (!setup) return;
    const { canvas, ctx } = setup;
    if (matrixCanvasAnimId) return;

    const fontSize = 15;
    let lastTime = 0;
    const fpsInterval = 1000 / 30;

    function drawColumns(targetCanvas, targetCtx, columns) {
        if (!targetCanvas || !targetCtx || typeof targetCtx.fillRect !== 'function') return;
        targetCtx.fillStyle = 'rgba(2, 6, 3, 0.08)';
        targetCtx.fillRect(0, 0, targetCanvas.width, targetCanvas.height);
        targetCtx.fillStyle = '#00ff66';
        targetCtx.font = `${fontSize}px monospace`;

        for (let i = 0; i < columns.length; i++) {
            const char = Math.random() > 0.5 ? '1' : '0';
            const x = i * fontSize;
            const y = columns[i] * fontSize;

            if (typeof targetCtx.fillText === 'function') targetCtx.fillText(char, x, y);

            if (y > targetCanvas.height && Math.random() > 0.975) {
                columns[i] = 0;
            } else {
                columns[i]++;
            }
        }
    }

    function drawMatrix(time) {
        if (typeof document !== 'undefined' && document.body && !document.body.classList.contains('theme-hacker')) {
            stopBinaryMatrix();
            return;
        }
        if (typeof requestAnimationFrame === 'function') {
            matrixCanvasAnimId = requestAnimationFrame(drawMatrix);
        }

        const elapsed = time - lastTime;
        if (elapsed < fpsInterval) return;
        lastTime = time - (elapsed % fpsInterval);

        // Desenhar no canvas principal
        drawColumns(canvas, ctx, matrixColumns);

        // Desenhar no canvas do Feed Reels (se presente)
        const feedCanvas = (typeof document !== 'undefined') ? document.getElementById('feed-matrix-canvas') : null;
        if (feedCanvas && typeof feedCanvas.getContext === 'function') {
            const feedCtx = feedCanvas.getContext('2d');
            if (feedMatrixColumns.length === 0 && feedCanvas.width) {
                const feedCols = Math.floor(feedCanvas.width / fontSize) || 20;
                feedMatrixColumns = Array.from({ length: feedCols }, () => Math.floor(Math.random() * -50));
            }
            drawColumns(feedCanvas, feedCtx, feedMatrixColumns);
        }
    }

    if (typeof requestAnimationFrame === 'function') {
        matrixCanvasAnimId = requestAnimationFrame(drawMatrix);
    }
}

export function stopBinaryMatrix() {
    if (matrixCanvasAnimId) {
        if (typeof cancelAnimationFrame === 'function') {
            cancelAnimationFrame(matrixCanvasAnimId);
        }
        matrixCanvasAnimId = null;
    }
    if (typeof document !== 'undefined') {
        const canvas = document.getElementById('matrix-binary-canvas');
        if (canvas && typeof canvas.getContext === 'function') {
            const ctx = canvas.getContext('2d');
            if (ctx && typeof ctx.clearRect === 'function') ctx.clearRect(0, 0, canvas.width || 800, canvas.height || 600);
        }
        const feedCanvas = document.getElementById('feed-matrix-canvas');
        if (feedCanvas && typeof feedCanvas.getContext === 'function') {
            const feedCtx = feedCanvas.getContext('2d');
            if (feedCtx && typeof feedCtx.clearRect === 'function') feedCtx.clearRect(0, 0, feedCanvas.width || 800, feedCanvas.height || 600);
        }
    }
}

let rgbThemeChromaInterval = null;
let rgbThemeHue = 0;

export function startRgbThemeChroma() {
    if (rgbThemeChromaInterval) return;
    const tick = () => {
        if (typeof document === 'undefined' || !document.body || !document.body.classList.contains('theme-rgb')) {
            stopRgbThemeChroma();
            return;
        }
        rgbThemeHue = (rgbThemeHue + 4) % 360;
        const color = `hsl(${rgbThemeHue}, 100%, 55%)`;
        if (document.documentElement && document.documentElement.style && typeof document.documentElement.style.setProperty === 'function') {
            document.documentElement.style.setProperty('--accent-color', color);
        }
        if (document.body && document.body.style && typeof document.body.style.setProperty === 'function') {
            document.body.style.setProperty('--accent-color', color);
        }
    };
    tick();
    rgbThemeChromaInterval = setInterval(tick, 60);
}

export function stopRgbThemeChroma() {
    if (rgbThemeChromaInterval) {
        clearInterval(rgbThemeChromaInterval);
        rgbThemeChromaInterval = null;
    }
    if (typeof document !== 'undefined') {
        const resetColor = currentProfile.accentColor || '#fff01f';
        if (document.documentElement && document.documentElement.style && typeof document.documentElement.style.setProperty === 'function') {
            document.documentElement.style.setProperty('--accent-color', resetColor);
        }
        if (document.body && document.body.style && typeof document.body.style.removeProperty === 'function') {
            document.body.style.removeProperty('--accent-color');
        }
    }
}

// ==========================================================================
// Formatação de Mensagens com Emojis Animados e Fontes VIP
// ==========================================================================
export function formatChatMessageText(rawText, isSenderVip = false, vipTextStyle = 'normal') {
    if (!rawText) return '';
    // Regex abrangente para cobrir todos os emojis Unicode (incluindo variação \uFE0F, tons de pele e sequências ZWJ como ❤️‍🔥 e 👩‍❤️‍👨)
    const EMOJI_REGEX = /(?:\p{Extended_Pictographic}|\p{Emoji_Presentation})(?:\uFE0F|\uD83C[\uDFFB-\uDFFF])?(?:\u200D(?:\p{Extended_Pictographic}|\p{Emoji_Presentation})(?:\uFE0F|\uD83C[\uDFFB-\uDFFF])?)*/gu;
    const trimmed = String(rawText).trim();

    if (isSenderVip) {
        const withoutEmojis = trimmed.replace(EMOJI_REGEX, '').trim();
        const matches = trimmed.match(EMOJI_REGEX);
        if (matches && withoutEmojis.length === 0 && matches.length <= 4) {
            const giantEmojis = matches.map(em => `<span class="vip-animated-emoji-giant" title="Emoji Animado VIP ⭐">${em}</span>`).join(' ');
            return `<div class="msg-text-content msg-giant-emojis">${giantEmojis}</div>`;
        }
    }

    let escaped = escapeHTML(rawText);

    if (isSenderVip) {
        escaped = escaped.replace(EMOJI_REGEX, (match) => {
            return `<span class="vip-animated-emoji" title="Emoji Animado VIP ⭐">${match}</span>`;
        });
    }

    const styleClass = (isSenderVip && vipTextStyle && vipTextStyle !== 'normal') ? ` vip-text-${vipTextStyle}` : '';
    return `<div class="msg-text-content${styleClass}">${escaped}</div>`;
}

