export function insertEmojiIntoChatInput(emoji) {
    const input = document.getElementById('chat-input-main');
    if (!input) return;
    const start = (input.selectionStart !== undefined && input.selectionStart !== null) ? input.selectionStart : input.value.length;
    const end = (input.selectionEnd !== undefined && input.selectionEnd !== null) ? input.selectionEnd : input.value.length;
    const val = input.value || '';
    input.value = val.slice(0, start) + emoji + val.slice(end);
    const newPos = start + emoji.length;
    if (input.setSelectionRange) {
        input.focus();
        input.setSelectionRange(newPos, newPos);
    }
    if (typeof input.dispatchEvent === 'function') {
        try {
            const evt = typeof Event !== 'undefined' ? new Event('input', { bubbles: true }) : { type: 'input', bubbles: true };
            input.dispatchEvent(evt);
        } catch (e) {}
    }
}

export function setupChatEmojiDrawer() {
    const emojiBtn = document.getElementById('chat-emoji-btn');
    const drawer = document.getElementById('chat-emoji-drawer');
    const closeBtn = document.getElementById('close-emoji-drawer-btn');
    const grid = document.getElementById('emoji-drawer-grid');
    if (!emojiBtn || !drawer || !grid) return;

    function renderCategory(cat) {
        const list = EMOJI_CATEGORIES[cat] || EMOJI_CATEGORIES.smileys;
        grid.innerHTML = '';
        list.forEach(emoji => {
            const item = document.createElement('div');
            item.className = 'emoji-item';
            item.innerText = emoji;
            item.title = emoji;
            item.onclick = (e) => {
                if (e && e.stopPropagation) e.stopPropagation();
                insertEmojiIntoChatInput(emoji);
            };
            grid.appendChild(item);
        });
    }

    renderCategory('smileys');

    emojiBtn.onclick = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();
        const isHidden = drawer.style.display === 'none' || !drawer.style.display;
        drawer.style.display = isHidden ? 'flex' : 'none';
        if (isHidden) renderCategory('smileys');
    };

    if (closeBtn) {
        closeBtn.onclick = (e) => {
            if (e && e.stopPropagation) e.stopPropagation();
            drawer.style.display = 'none';
        };
    }

    const tabs = drawer.querySelectorAll('.emoji-tab-btn');
    tabs.forEach(tab => {
        tab.onclick = (e) => {
            if (e && e.stopPropagation) e.stopPropagation();
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            renderCategory(tab.dataset.cat);
        };
    });

    if (typeof document !== 'undefined' && document.addEventListener) {
        document.addEventListener('click', (e) => {
            if (drawer.style.display !== 'none' && !drawer.contains(e.target) && e.target !== emojiBtn && !emojiBtn.contains(e.target)) {
                drawer.style.display = 'none';
            }
        });
    }
}

// ==========================================================================
// Plano de Fundo da Conversa (Chat Wallpaper)
// ==========================================================================
export function setActiveChatContact(contact) {
    activeChatContact = contact;
    if (typeof document !== 'undefined') {
        const win = document.getElementById('chat-window');
        if (win && contact) {
            win.dataset.chatId = contact.uid || '';
            win.dataset.isGroup = contact.isGroup ? 'true' : 'false';
        }
    }
}

export function getActiveChatContact() {
    return activeChatContact;
}

export function getChatWallpaperKeys(targetId) {
    const keys = new Set();
    const win = typeof document !== 'undefined' ? document.getElementById('chat-window') : null;
    const domChatId = win && win.dataset ? win.dataset.chatId : null;
    const domIsGroup = win && win.dataset ? win.dataset.isGroup === 'true' : false;

    const candidates = [
        targetId,
        domChatId,
        (typeof activeChatContact !== 'undefined' && activeChatContact) ? (activeChatContact.uid || activeChatContact.id || activeChatContact.groupId) : null
    ].filter(Boolean);

    for (const id of candidates) {
        const s = String(id);
        keys.add(s);
        if (s.startsWith('group_')) {
            keys.add(s.replace('group_', ''));
        } else {
            if (domIsGroup || (activeChatContact && activeChatContact.isGroup)) {
                keys.add(`group_${s}`);
            }
            if (!s.includes('_') && typeof currentUser !== 'undefined' && currentUser && currentUser.uid) {
                keys.add([currentUser.uid, s].sort().join('_'));
            }
        }
    }

    if (typeof activeChatContact !== 'undefined' && activeChatContact) {
        const cUid = String(activeChatContact.uid || activeChatContact.id || activeChatContact.groupId || '');
        if (cUid) {
            keys.add(cUid);
            if (activeChatContact.isGroup) {
                keys.add(`group_${cUid}`);
            } else if (typeof currentUser !== 'undefined' && currentUser && currentUser.uid) {
                keys.add([currentUser.uid, cUid].sort().join('_'));
            }
        }
    }

    const activeId = typeof getActiveChatId === 'function' ? getActiveChatId() : null;
    if (activeId) keys.add(String(activeId));

    if (keys.size === 0) {
        keys.add('current_chat');
    }

    return Array.from(keys);
}

export function getSavedChatWallpaper(targetId) {
    const keys = getChatWallpaperKeys(targetId);
    if (typeof localStorage !== 'undefined') {
        for (const k of keys) {
            const val = localStorage.getItem(`vortex_wallpaper_${k}`);
            if (val) return val;
        }
    }
    if (typeof currentProfile !== 'undefined' && currentProfile && currentProfile.chatWallpapers) {
        for (const k of keys) {
            if (currentProfile.chatWallpapers[k]) return currentProfile.chatWallpapers[k];
        }
    }
    // Fallback para papel de parede global
    if (typeof localStorage !== 'undefined') {
        const globalWp = localStorage.getItem('vortex_wallpaper_global');
        if (globalWp) return globalWp;
    }
    if (typeof currentProfile !== 'undefined' && currentProfile && currentProfile.chatWallpaperGlobal) {
        return currentProfile.chatWallpaperGlobal;
    }
    return 'default';
}

export function applyChatWallpaper(chatId) {
    if (typeof document === 'undefined') return;
    const container = document.getElementById('message-container');
    if (!container) return;
    const wp = getSavedChatWallpaper(chatId);

    if (!wp || wp === 'default') {
        container.style.backgroundColor = '';
        container.style.backgroundImage = '';
        container.style.background = '';
        container.classList.remove('has-custom-wallpaper');
        return;
    }

    container.classList.add('has-custom-wallpaper');
    container.style.backgroundPosition = 'center center';
    container.style.backgroundSize = 'cover';
    container.style.backgroundRepeat = 'no-repeat';

    if (wp.startsWith('data:image') || wp.startsWith('http')) {
        container.style.backgroundColor = '#0b141a';
        container.style.backgroundImage = `url("${wp}")`;
        container.style.background = `url("${wp}") center center / cover no-repeat`;
    } else if (wp.startsWith('linear-gradient')) {
        container.style.backgroundColor = '#0b141a';
        container.style.backgroundImage = wp;
        container.style.background = wp;
    } else if (wp.startsWith('#') || wp.startsWith('rgb')) {
        container.style.backgroundColor = wp;
        container.style.backgroundImage = 'none';
        container.style.background = wp;
    } else if (wp === 'total-black') {
        container.style.backgroundColor = '#030303';
        container.style.backgroundImage = 'none';
        container.style.background = '#030303';
    } else if (wp === 'cyber-dark') {
        container.style.backgroundColor = '#090d16';
        container.style.backgroundImage = 'linear-gradient(135deg, #090d16 0%, #030712 100%)';
        container.style.background = 'linear-gradient(135deg, #090d16 0%, #030712 100%)';
    } else if (wp === 'cosmic-purple') {
        container.style.backgroundColor = '#2e0854';
        container.style.backgroundImage = 'linear-gradient(135deg, #2e0854 0%, #0c021f 100%)';
        container.style.background = 'linear-gradient(135deg, #2e0854 0%, #0c021f 100%)';
    } else if (wp === 'matrix-green') {
        container.style.backgroundColor = '#021a08';
        container.style.backgroundImage = 'linear-gradient(135deg, #021a08 0%, #010803 100%)';
        container.style.background = 'linear-gradient(135deg, #021a08 0%, #010803 100%)';
    } else if (wp === 'deep-cyan') {
        container.style.backgroundColor = '#022026';
        container.style.backgroundImage = 'linear-gradient(135deg, #022026 0%, #010c10 100%)';
        container.style.background = 'linear-gradient(135deg, #022026 0%, #010c10 100%)';
    } else if (wp === 'sunset-glow') {
        container.style.backgroundColor = '#2b091f';
        container.style.backgroundImage = 'linear-gradient(135deg, #2b091f 0%, #10020d 100%)';
        container.style.background = 'linear-gradient(135deg, #2b091f 0%, #10020d 100%)';
    } else {
        container.style.backgroundImage = wp;
        container.style.background = wp;
    }
}

export function setupChatWallpaperModal() {
    const trigger = document.getElementById('chat-wallpaper-trigger');
    const modal = document.getElementById('chat-wallpaper-modal');
    const closeBtn = document.getElementById('close-wallpaper-modal');
    const previewBox = document.getElementById('wallpaper-preview-box');
    const presets = document.querySelectorAll('.wallpaper-preset-item');
    const fileInput = document.getElementById('wallpaper-file-input');
    const saveBtn = document.getElementById('save-wallpaper-btn');
    const resetBtn = document.getElementById('reset-wallpaper-btn');
    if (!modal) return;

    let selectedWp = 'default';

    function updatePreview(val) {
        selectedWp = val || 'default';
        if (!previewBox) return;
        previewBox.style.backgroundPosition = 'center center';
        previewBox.style.backgroundSize = 'cover';
        previewBox.style.backgroundRepeat = 'no-repeat';

        if (!val || val === 'default') {
            previewBox.style.backgroundColor = 'rgba(255, 255, 255, 0.05)';
            previewBox.style.backgroundImage = 'none';
            previewBox.style.background = '';
        } else if (val.startsWith('data:image') || val.startsWith('http')) {
            previewBox.style.backgroundColor = '#0b141a';
            previewBox.style.backgroundImage = `url("${val}")`;
            previewBox.style.background = `url("${val}") center center / cover no-repeat`;
        } else if (val.startsWith('linear-gradient')) {
            previewBox.style.backgroundColor = '#0b141a';
            previewBox.style.backgroundImage = val;
            previewBox.style.background = val;
        } else if (val === 'total-black') {
            previewBox.style.backgroundColor = '#030303';
            previewBox.style.backgroundImage = 'none';
            previewBox.style.background = '#030303';
        } else if (val === 'cyber-dark') {
            previewBox.style.backgroundColor = '#090d16';
            previewBox.style.backgroundImage = 'linear-gradient(135deg, #090d16 0%, #030712 100%)';
            previewBox.style.background = 'linear-gradient(135deg, #090d16 0%, #030712 100%)';
        } else if (val === 'cosmic-purple') {
            previewBox.style.backgroundColor = '#2e0854';
            previewBox.style.backgroundImage = 'linear-gradient(135deg, #2e0854 0%, #0c021f 100%)';
            previewBox.style.background = 'linear-gradient(135deg, #2e0854 0%, #0c021f 100%)';
        } else if (val === 'matrix-green') {
            previewBox.style.backgroundColor = '#021a08';
            previewBox.style.backgroundImage = 'linear-gradient(135deg, #021a08 0%, #010803 100%)';
            previewBox.style.background = 'linear-gradient(135deg, #021a08 0%, #010803 100%)';
        } else if (val === 'deep-cyan') {
            previewBox.style.backgroundColor = '#022026';
            previewBox.style.backgroundImage = 'linear-gradient(135deg, #022026 0%, #010c10 100%)';
            previewBox.style.background = 'linear-gradient(135deg, #022026 0%, #010c10 100%)';
        } else if (val === 'sunset-glow') {
            previewBox.style.backgroundColor = '#2b091f';
            previewBox.style.backgroundImage = 'linear-gradient(135deg, #2b091f 0%, #10020d 100%)';
            previewBox.style.background = 'linear-gradient(135deg, #2b091f 0%, #10020d 100%)';
        } else {
            previewBox.style.backgroundImage = val;
            previewBox.style.background = val;
        }
    }

    if (trigger) {
        trigger.onclick = () => {
            const dropdown = document.getElementById('chat-dropdown-menu');
            if (dropdown) dropdown.classList.remove('active');
            const currentWp = getSavedChatWallpaper();
            updatePreview(currentWp);
            presets.forEach(p => p.classList.toggle('active', p.dataset.wallpaper === currentWp));
            modal.classList.add('active');
        };
    }

    if (closeBtn) {
        closeBtn.onclick = () => modal.classList.remove('active');
    }
    modal.onclick = (e) => {
        if (e.target === modal) modal.classList.remove('active');
    };

    presets.forEach(preset => {
        preset.onclick = () => {
            presets.forEach(p => p.classList.remove('active'));
            preset.classList.add('active');
            updatePreview(preset.dataset.wallpaper);
        };
    });

    if (fileInput) {
        fileInput.onchange = async (e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;
            try {
                const compressed = await compressImageFileToKB(file, { maxDimension: 1080, targetMaxKB: 180, quality: 0.78 });
                updatePreview(compressed.data);
                presets.forEach(p => p.classList.remove('active'));
                fileInput.value = '';
                showToast('Foto Carregada', `Plano de fundo preparado (${compressed.sizeKB} KB)`, 'green');
            } catch (err) {
                console.error('Erro ao comprimir imagem de wallpaper:', err);
                showToast('Erro', 'Não foi possível processar a foto.', 'red');
            }
        };
    }

    if (saveBtn) {
        saveBtn.onclick = async () => {
            const scopeRadio = document.querySelector('input[name="wallpaper-scope"]:checked');
            const scope = scopeRadio ? scopeRadio.value : 'chat';
            const keys = getChatWallpaperKeys();

            if (scope === 'chat') {
                if (typeof currentProfile !== 'undefined' && currentProfile) {
                    if (!currentProfile.chatWallpapers) currentProfile.chatWallpapers = {};
                    for (const k of keys) {
                        if (selectedWp === 'default') {
                            delete currentProfile.chatWallpapers[k];
                        } else {
                            currentProfile.chatWallpapers[k] = selectedWp;
                        }
                    }
                }
                if (typeof localStorage !== 'undefined') {
                    for (const k of keys) {
                        try {
                            if (selectedWp === 'default') {
                                localStorage.removeItem(`vortex_wallpaper_${k}`);
                            } else {
                                localStorage.setItem(`vortex_wallpaper_${k}`, selectedWp);
                            }
                        } catch (err) {
                            console.warn('Erro ao gravar no localStorage:', err);
                        }
                    }
                }
            } else {
                if (typeof currentProfile !== 'undefined' && currentProfile) {
                    currentProfile.chatWallpaperGlobal = selectedWp === 'default' ? null : selectedWp;
                }
                if (typeof localStorage !== 'undefined') {
                    try {
                        if (selectedWp === 'default') {
                            localStorage.removeItem('vortex_wallpaper_global');
                        } else {
                            localStorage.setItem('vortex_wallpaper_global', selectedWp);
                        }
                    } catch (err) {
                        console.warn('Erro ao gravar no localStorage:', err);
                    }
                }
            }

            // Aplicar imediatamente sem aguardar chamada de rede
            applyChatWallpaper();
            modal.classList.remove('active');
            showToast('Plano de Fundo Salvo', 'Papel de parede aplicado com sucesso!', 'green');

            // Sincronizar com Firestore se o usuário estiver autenticado (background)
            if (typeof currentUser !== 'undefined' && currentUser && currentUser.uid && typeof db !== 'undefined') {
                try {
                    const userRef = doc(db, 'users', currentUser.uid);
                    if (scope === 'chat') {
                        if (currentProfile && currentProfile.chatWallpapers) {
                            await updateDoc(userRef, { chatWallpapers: currentProfile.chatWallpapers });
                        }
                    } else {
                        await updateDoc(userRef, { chatWallpaperGlobal: currentProfile.chatWallpaperGlobal });
                    }
                } catch (fireErr) {
                    console.warn('Erro ao sincronizar wallpaper no Firestore:', fireErr);
                }
            }
        };
    }

    if (resetBtn) {
        resetBtn.onclick = async () => {
            const scopeRadio = document.querySelector('input[name="wallpaper-scope"]:checked');
            const scope = scopeRadio ? scopeRadio.value : 'chat';
            const keys = getChatWallpaperKeys();

            if (scope === 'chat') {
                if (typeof currentProfile !== 'undefined' && currentProfile && currentProfile.chatWallpapers) {
                    for (const k of keys) {
                        delete currentProfile.chatWallpapers[k];
                    }
                }
                if (typeof localStorage !== 'undefined') {
                    for (const k of keys) {
                        try { localStorage.removeItem(`vortex_wallpaper_${k}`); } catch (e) {}
                    }
                }
            } else {
                if (typeof currentProfile !== 'undefined' && currentProfile) {
                    currentProfile.chatWallpaperGlobal = null;
                }
                if (typeof localStorage !== 'undefined') {
                    try { localStorage.removeItem('vortex_wallpaper_global'); } catch (e) {}
                }
            }

            updatePreview('default');
            applyChatWallpaper();
            modal.classList.remove('active');
            showToast('Plano de Fundo Restaurado', 'O papel de parede voltou ao padrão.', 'green');

            if (typeof currentUser !== 'undefined' && currentUser && currentUser.uid && typeof db !== 'undefined') {
                try {
                    const userRef = doc(db, 'users', currentUser.uid);
                    if (scope === 'chat') {
                        if (currentProfile && currentProfile.chatWallpapers) {
                            await updateDoc(userRef, { chatWallpapers: currentProfile.chatWallpapers });
                        }
                    } else {
                        await updateDoc(userRef, { chatWallpaperGlobal: null });
                    }
                } catch (e) {}
            }
        };
    }
}

// ==========================================================================
// Seletores de Recursos VIP nas Configurações (#vip-theme-selector & #vip-font-selector)
// ==========================================================================
export function setupVipSettingsControls() {
    const themeButtons = document.querySelectorAll('.vip-theme-option');
    themeButtons.forEach(btn => {
        btn.onclick = async () => {
            const theme = btn.dataset.theme;
            const isVip = checkIsVipUser(currentProfile);

            if (theme !== 'default' && !isVip) {
                showToast('Acesso Exclusivo VIP ⭐', 'Os temas Cyber Park, Hacker e RGB são exclusivos para membros VORTEX VIP. Assine agora!', 'orange');
                const subBtn = document.getElementById('subscribe-btn');
                if (subBtn) subBtn.click();
                return;
            }

            currentProfile.vipTheme = theme;
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('vortex_vip_theme', theme);
            }
            if (currentUser && typeof updateDoc === 'function' && typeof doc === 'function') {
                try {
                    await updateDoc(doc(db, 'users', currentUser.uid), { vipTheme: theme });
                } catch (e) {
                    console.warn('Erro ao salvar tema VIP no Firestore:', e);
                }
            }
            applyUserTheme();
            showToast('Tema VIP Aplicado', `Tema ${theme.toUpperCase()} ativado com sucesso!`, 'green');
        };
    });

    const fontButtons = document.querySelectorAll('.vip-font-option');
    fontButtons.forEach(btn => {
        btn.onclick = async () => {
            const styleKey = btn.dataset.style;
            const isVip = checkIsVipUser(currentProfile);

            if (styleKey !== 'normal' && !isVip) {
                showToast('Acesso Exclusivo VIP ⭐', 'As fontes animadas são exclusivas para membros VORTEX VIP. Assine agora!', 'orange');
                const subBtn = document.getElementById('subscribe-btn');
                if (subBtn) subBtn.click();
                return;
            }

            currentProfile.vipTextStyle = styleKey;
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('vortex_vip_font', styleKey);
            }
            if (currentUser && typeof updateDoc === 'function' && typeof doc === 'function') {
                try {
                    await updateDoc(doc(db, 'users', currentUser.uid), { vipTextStyle: styleKey });
                } catch (e) {
                    console.warn('Erro ao salvar estilo VIP no Firestore:', e);
                }
            }
            fontButtons.forEach(b => b.classList.toggle('active', b.dataset.style === styleKey));
            showToast('Fonte VIP Configurada', `Estilo de texto animado (${styleKey}) ativado!`, 'green');
        };
    });
}

function applyUserTheme() {
    // Temas VORTEX VIP (Cyberpunk, Hacker com chuva binária e RGB)
    const isVip = checkIsVipUser(currentProfile);
    const savedVipTheme = currentProfile.vipTheme || (typeof localStorage !== 'undefined' ? localStorage.getItem('vortex_vip_theme') : 'default') || 'default';
    const activeVipTheme = (isVip && savedVipTheme !== 'default') ? savedVipTheme : 'default';

    if (activeVipTheme !== 'rgb') {
        if (typeof document !== 'undefined' && document.documentElement && document.documentElement.style && typeof document.documentElement.style.setProperty === 'function') {
            document.documentElement.style.setProperty('--accent-color', currentProfile.accentColor || '#fff01f');
        }
        if (typeof document !== 'undefined' && document.body && document.body.style && typeof document.body.style.removeProperty === 'function') {
            document.body.style.removeProperty('--accent-color');
        }
    }
    applyPrivacyModeState();
    document.body.classList.toggle('total-black', currentProfile.themeEnabled === false);
    document.querySelectorAll('.color-option').forEach(opt => {
        opt.classList.toggle('active', opt.dataset.color === currentProfile.accentColor);
    });

    document.body.classList.toggle('theme-cyberpark', activeVipTheme === 'cyberpark');
    document.body.classList.toggle('theme-cyberpunk', activeVipTheme === 'cyberpark');
    document.body.classList.toggle('theme-hacker', activeVipTheme === 'hacker');
    document.body.classList.toggle('theme-rgb', activeVipTheme === 'rgb');

    if (activeVipTheme === 'hacker') {
        startBinaryMatrix();
    } else {
        stopBinaryMatrix();
    }

    if (activeVipTheme === 'rgb') {
        startRgbThemeChroma();
    } else {
        stopRgbThemeChroma();
    }

    document.querySelectorAll('.vip-theme-option').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.theme === activeVipTheme);
    });

    // Fontes Animadas VIP
    const savedVipFont = currentProfile.vipTextStyle || (typeof localStorage !== 'undefined' ? localStorage.getItem('vortex_vip_font') : 'normal') || 'normal';
    const activeVipFont = (isVip && savedVipFont !== 'normal') ? savedVipFont : 'normal';
    document.querySelectorAll('.vip-font-option').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.style === activeVipFont);
    });

    const soundTog = document.getElementById('sound-toggle');
    const ghostTog = document.getElementById('ghost-toggle');
    const privTog = document.getElementById('privacy-toggle');
    const pinTog = document.getElementById('pin-toggle');
    const themeTog = document.getElementById('theme-toggle');
    const ringtoneSelect = document.getElementById('ringtone-select');
    const subscribeBtn = document.getElementById('subscribe-btn');
    if (soundTog) soundTog.checked = !!currentProfile.soundEnabled;
    if (ringtoneSelect) {
        const savedTone = currentProfile.ringtoneType || (typeof localStorage !== 'undefined' ? localStorage.getItem('vortex_ringtone_type') : 'antigo') || 'antigo';
        ringtoneSelect.value = savedTone;
        if (typeof ringtoneSound !== 'undefined' && ringtoneSound.setToneType) {
            ringtoneSound.setToneType(savedTone);
        }
    }
    updatePushSettingsUI();
    if (ghostTog) ghostTog.checked = !!currentProfile.ghostMode;
    if (privTog) privTog.checked = !!currentProfile.privacyMode;
    if (pinTog) pinTog.checked = !!currentProfile.pinEnabled;
    if (themeTog) themeTog.checked = currentProfile.themeEnabled !== false;
    if (subscribeBtn) {
        const sub = getVipSubscriptionState(currentProfile);
        if (sub.status === 'active') {
            subscribeBtn.innerText = sub.daysRemaining < 9000 ? `Assinado (${sub.daysRemaining}d) ⭐` : 'Assinado ⭐';
            subscribeBtn.className = 'danger-btn vip-action-btn active';
        } else if (sub.status === 'grace_period') {
            subscribeBtn.innerText = `Renovar (${sub.graceDaysRemaining}d) ⚠️`;
            subscribeBtn.className = 'danger-btn vip-action-btn pending';
        } else if (currentProfile.vipRequestStatus === 'pending') {
            subscribeBtn.innerText = 'Em análise ⏳';
            subscribeBtn.className = 'danger-btn vip-action-btn pending';
        } else {
            subscribeBtn.innerText = 'Assinar';
            subscribeBtn.className = 'danger-btn vip-action-btn';
        }
    }
    checkVipSubscriptionLifecycle();
}

function updateProfileDOM() {
    const nameEl = document.getElementById('user-display-name');
    const avatarEl = document.getElementById('user-avatar-display');
    const editPreview = document.getElementById('profile-edit-avatar-preview');
    const userBadge = document.getElementById('user-verified-badge');
    const subscribeBtn = document.getElementById('subscribe-btn');

    if (nameEl) nameEl.innerText = `${currentProfile.name} ${currentProfile.surname}`.trim();
    if (avatarEl) avatarEl.style.backgroundImage = currentProfile.avatar ? `url('${currentProfile.avatar}')` : '';
    if (editPreview) editPreview.style.backgroundImage = currentProfile.avatar ? `url('${currentProfile.avatar}')` : '';
    if (currentUser && currentUser.uid && currentProfile.avatar && typeof updateAuthorAvatarsInDOM === 'function') {
        updateAuthorAvatarsInDOM(currentUser.uid, currentProfile.avatar);
    }

    const isVip = checkIsVipUser(currentProfile);
    const sub = getVipSubscriptionState(currentProfile);

    if (userBadge) {
        updateVerifiedBadgeElement(userBadge, currentProfile);
    }
    if (typeof updateCompanyLinkSectionVisibility === 'function') {
        updateCompanyLinkSectionVisibility(currentProfile);
    }
    if (typeof updateStatusBusinessLinkVisibility === 'function') {
        updateStatusBusinessLinkVisibility(currentProfile);
    }
    if (window.lucide) lucide.createIcons();
    if (subscribeBtn) {
        if (sub.status === 'active') {
            subscribeBtn.innerText = sub.daysRemaining < 9000 ? `Assinado (${sub.daysRemaining}d) ⭐` : 'Assinado ⭐';
            subscribeBtn.className = 'danger-btn vip-action-btn active';
        } else if (sub.status === 'grace_period') {
            subscribeBtn.innerText = `Renovar (${sub.graceDaysRemaining}d) ⚠️`;
            subscribeBtn.className = 'danger-btn vip-action-btn pending';
        } else if (currentProfile.vipRequestStatus === 'pending') {
            subscribeBtn.innerText = 'Em análise ⏳';
            subscribeBtn.className = 'danger-btn vip-action-btn pending';
        } else {
            subscribeBtn.innerText = 'Assinar';
            subscribeBtn.className = 'danger-btn vip-action-btn';
        }
    }
    checkVipSubscriptionLifecycle();
}

function detachListeners() {
    if (currentChatUnsubscribe) currentChatUnsubscribe();
    if (contactsUnsubscribe) contactsUnsubscribe();
    if (requestsUnsubscribe) requestsUnsubscribe();
    if (storiesUnsubscribe) storiesUnsubscribe();
    if (notificationsUnsubscribe) notificationsUnsubscribe();
    if (broadcastUnsubscribe) broadcastUnsubscribe();
    if (adminNotifUnsubscribe) {
        adminNotifUnsubscribe();
        adminNotifUnsubscribe = null;
    }
    adminNotifications = [];
    if (contactStatusUnsubscribe) contactStatusUnsubscribe();
    if (incomingCallUnsubscribe) incomingCallUnsubscribe();
    if (activeCallDocUnsubscribe) activeCallDocUnsubscribe();
    if (callerCandidatesUnsubscribe) callerCandidatesUnsubscribe();
    if (calleeCandidatesUnsubscribe) calleeCandidatesUnsubscribe();
    if (currentStoryDocUnsubscribe) currentStoryDocUnsubscribe();
    if (managedGroupUnsubscribe) managedGroupUnsubscribe();
    if (blockedUnsubscribe) blockedUnsubscribe();
    if (adminReportsUnsubscribe) adminReportsUnsubscribe();
    if (adminVipRequestsUnsubscribe) adminVipRequestsUnsubscribe();
    if (deletedUsersUnsubscribe) deletedUsersUnsubscribe();
}

/* ==========================================================================
   SISTEMA DE PIN E SEGURANÇA
   ========================================================================== */
function updatePinDots(containerId, input) {
    const dots = document.querySelectorAll(`#${containerId} .pin-dot`);
    dots.forEach((dot, i) => dot.classList.toggle('filled', i < input.length));
}

export function triggerNeonUnlock() {
    const neonAnim = document.getElementById('neon-unlock-anim');
    if (neonAnim) {
        neonAnim.classList.remove('active');
        void neonAnim.offsetWidth;
        neonAnim.classList.add('active');
        setTimeout(() => neonAnim.classList.remove('active'), 1200);
    }
}

export function unlockApp() {
    const lockScreen = document.getElementById('lock-screen');
    if (lockScreen) lockScreen.classList.add('unlocked');
    playSound(unlockSound);
    pinState.currentPinInput = "";
    updatePinDots('pin-dots', "");
    triggerNeonUnlock();
    if (typeof initBackNavigation === 'function') initBackNavigation();
}

export function unlockWithBiometrics() {
    const lockScreen = document.getElementById('lock-screen');
    if (!lockScreen || lockScreen.classList.contains('unlocked')) return;
    if ("vibrate" in navigator) navigator.vibrate([40, 50, 40]);
    unlockApp();
    showToast("Biometria VIP", "Acesso liberado por biometria!", "green");
}

export function enterDigit(digit) {
    playSound(clickSound);
    if (pinState.currentPinInput.length < 4) {
        pinState.currentPinInput += digit;
        updatePinDots('pin-dots', pinState.currentPinInput);
        if (pinState.currentPinInput.length === 4) {
            if (pinState.currentPinInput === (currentProfile.pin || '1234')) {
                unlockApp();
            } else {
                showToast("Segurança", "PIN incorreto!", "red");
                pinState.currentPinInput = "";
                updatePinDots('pin-dots', "");
            }
        }
    }
}

export function clearPin() {
    playSound(clickSound);
    pinState.currentPinInput = pinState.currentPinInput.slice(0, -1);
    updatePinDots('pin-dots', pinState.currentPinInput);
}

export function enterSetPinDigit(digit) {
    playSound(clickSound);
    const setPinOverlay = document.getElementById('set-pin-overlay');
    if (pinState.newPinInput.length < 4) {
        pinState.newPinInput += digit;
        updatePinDots('set-pin-dots', pinState.newPinInput);
        if (pinState.newPinInput.length === 4) {
            currentProfile.pin = pinState.newPinInput;
            currentProfile.pinEnabled = true;
            if (currentUser) {
                updateDoc(doc(db, 'users', currentUser.uid), { pin: currentProfile.pin, pinEnabled: true });
            }
            if (setPinOverlay) setPinOverlay.classList.add('unlocked');
            pinState.newPinInput = "";
            updatePinDots('set-pin-dots', "");
            showToast("Segurança", "Novo PIN salvo com sucesso!", "green");
        }
    }
}

export function clearSetPin() {
    playSound(clickSound);
    pinState.newPinInput = pinState.newPinInput.slice(0, -1);
    updatePinDots('set-pin-dots', pinState.newPinInput);
}

export function closeSetPin() {
    playSound(clickSound);
    document.getElementById('set-pin-overlay')?.classList.add('unlocked');
    pinState.newPinInput = "";
    updatePinDots('set-pin-dots', "");
}

window.enterDigit = enterDigit;
window.clearPin = clearPin;
window.enterSetPinDigit = enterSetPinDigit;
window.clearSetPin = clearSetPin;
window.closeSetPin = closeSetPin;
window.unlockApp = unlockApp;
window.unlockWithBiometrics = unlockWithBiometrics;
window.triggerNeonUnlock = triggerNeonUnlock;

// Event delegation para teclado de DESBLOQUEIO (lock-screen)
document.addEventListener('click', (e) => {
    if (e.target.closest('#lock-screen .key')) {
        const keyEl = e.target.closest('#lock-screen .key');
        const keyValue = keyEl.dataset.key;
        if (keyValue === 'clear') {
            clearPin();
        } else if (keyValue) {
            enterDigit(keyValue);
        } else if (keyEl.id === 'biometric-btn') {
            unlockWithBiometrics();
        }
    }
    // Event delegation para teclado de PIN (set-pin-overlay)
    else if (e.target.closest('#set-pin-overlay .key')) {
        const keyEl = e.target.closest('#set-pin-overlay .key');
        const keyValue = keyEl.dataset.key;
        if (keyValue === 'clear') {
            clearSetPin();
        } else if (keyValue) {
            enterSetPinDigit(keyValue);
        }
    }
});

/* ==========================================================================
   STORIES ENGINE EM TEMPO REAL (GRAVAÇÃO, REAÇÃO & GAVETA AO VIVO)
   ========================================================================== */
export function canUserViewStory(story, viewerUid, authorContactsSet = null) {
    if (!story || !viewerUid) return false;
    // O próprio autor sempre pode ver seus stories
    if (story.authorUid === viewerUid) return true;

    // Se o autor estiver bloqueado pelo visualizador, não exibe
    if (typeof blockedContactsSet !== 'undefined' && blockedContactsSet.has(story.authorUid)) {
        return false;
    }

    // Story de Anúncio da Conta Empresa: Visível para TODOS os usuários com conta na plataforma
    if (story.isAd || story.contentType === 'ad') {
        return true;
    }

    // Verificar se o autor do story é um contato aceito pelo visualizador
    const contacts = authorContactsSet || (typeof userContactsSet !== 'undefined' ? userContactsSet : null);
    if (contacts && contacts.has(story.authorUid)) {
        return true;
    }

    // Se o story possui lista explícita de contatos autorizados (gravada pelo autor)
    if (Array.isArray(story.allowedUids)) {
        return story.allowedUids.includes(viewerUid);
    }

    return false;
}

