// VORTEX VIP - MÓDULO DE CATÁLOGO & LOJA ONLINE COMPLETO (v1.0.116)
// ==========================================================================

export let activeCatalogSellerUid = null;
export let activeCatalogSellerData = null;
export let activeCatalogTab = 'stores';
export let currentEditingProductId = null;
export let currentEditorPhotos = [];
export let currentEditorColors = []; // até 5 cores: [{ hex, name }]
export let catalogSellerProductsCache = [];
export let catalogSellerCategoriesCache = [];
let catalogOrdersUnsubscribe = null;
let catalogPurchasesUnsubscribe = null;

// Helpers de Moeda e Validação
export function formatBRL(val) {
    const num = Number(val) || 0;
    return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

export function parseBRL(val) {
    if (typeof val === 'number') return isNaN(val) ? 0 : val;
    if (!val) return 0;
    let s = String(val).trim().replace(/[^\d.,]/g, '');
    if (!s) return 0;
    if (s.includes(',') && s.includes('.')) {
        s = s.replace(/\./g, '').replace(',', '.');
    } else if (s.includes(',')) {
        s = s.replace(',', '.');
    }
    const n = parseFloat(s);
    return isNaN(n) ? 0 : n;
}

// Sanitização e Bloqueio de Letras nos Campos Numéricos (Preço, Promoção e Estoque)
export function sanitizeCatalogDecimalInput(val) {
    if (val === null || val === undefined) return '';
    let s = String(val).replace(/[^\d.,]/g, '');
    const firstSep = s.search(/[.,]/);
    if (firstSep !== -1) {
        const sepChar = s[firstSep];
        const pre = s.substring(0, firstSep);
        const post = s.substring(firstSep + 1).replace(/[.,]/g, '');
        s = pre + sepChar + post;
    }
    return s;
}

export function sanitizeCatalogIntegerInput(val) {
    if (val === null || val === undefined) return '';
    return String(val).replace(/\D/g, '');
}

export function sanitizeCatalogHouseNumber(val) {
    if (val === null || val === undefined) return '';
    return String(val).replace(/\D/g, '');
}

export function sanitizeCatalogDiscountInput(val) {
    if (val === null || val === undefined) return '';
    let s = String(val).replace(/[^0-9.,%]/g, '');
    const pctIdx = s.indexOf('%');
    if (pctIdx !== -1) {
        s = s.substring(0, pctIdx + 1);
    }
    return s;
}

export function getDigitalCtaLabel(ctaKey) {
    switch (ctaKey) {
        case 'abrir': return 'Abrir';
        case 'assinar': return 'Assinar';
        case 'saiba_mais': return 'Saiba mais';
        case 'ver': return 'Ver';
        case 'testar': return 'Testar';
        default: return 'Abrir';
    }
}

export function getDigitalCtaIcon(ctaKey) {
    switch (ctaKey) {
        case 'abrir': return 'external-link';
        case 'assinar': return 'check-circle';
        case 'saiba_mais': return 'info';
        case 'ver': return 'eye';
        case 'testar': return 'play';
        default: return 'external-link';
    }
}

export function calculatePromoFromDiscount(basePrice, discountStr) {
    const price = parseBRL(basePrice);
    if (!price || price <= 0 || discountStr === null || discountStr === undefined) {
        return null;
    }
    const clean = String(discountStr).trim();
    if (!clean) return null;

    if (clean.includes('%')) {
        const pctVal = parseFloat(clean.replace('%', '').replace(',', '.'));
        if (isNaN(pctVal) || pctVal <= 0) return null;
        if (pctVal >= 100) return 0;
        const discounted = price * (1 - (pctVal / 100));
        return Math.max(0, Math.round(discounted * 100) / 100);
    } else {
        const val = parseBRL(clean);
        if (val <= 0) return null;
        const discounted = price - val;
        return Math.max(0, Math.round(discounted * 100) / 100);
    }
}

export function calculateDiscountFromPromo(basePrice, promoPrice) {
    const p = parseBRL(basePrice);
    const promo = parseBRL(promoPrice);
    if (!p || p <= 0 || !promo || promo <= 0 || promo >= p) return null;
    const diff = p - promo;
    const pct = Math.round((diff / p) * 100);
    if (pct > 0 && pct < 100) {
        return `${pct}%`;
    }
    return diff.toFixed(2).replace('.', ',');
}

export function attachCatalogNumericGuards() {
    const priceInp = document.getElementById('cat-prod-price');
    const promoInp = document.getElementById('cat-prod-promo');
    const stockInp = document.getElementById('cat-prod-stock');
    const discountInp = document.getElementById('cat-prod-discount');

    function syncCatalogPricing(triggerSource) {
        if (!priceInp || !promoInp || !discountInp) return;
        const priceVal = priceInp.value.trim();
        const discountVal = discountInp.value.trim();
        const promoVal = promoInp.value.trim();

        if (triggerSource === 'discount') {
            if (!discountVal) {
                if (promoInp._autoDiscount) {
                    promoInp.value = '';
                    promoInp._autoDiscount = false;
                }
                return;
            }
            if (priceVal) {
                const calculated = calculatePromoFromDiscount(priceVal, discountVal);
                if (calculated !== null) {
                    promoInp.value = calculated.toFixed(2).replace('.', ',');
                    promoInp._autoDiscount = true;
                }
            }
        } else if (triggerSource === 'price') {
            if (discountVal && priceVal) {
                const calculated = calculatePromoFromDiscount(priceVal, discountVal);
                if (calculated !== null) {
                    promoInp.value = calculated.toFixed(2).replace('.', ',');
                    promoInp._autoDiscount = true;
                }
            }
        } else if (triggerSource === 'promo') {
            if (!promoVal) {
                if (discountInp._autoPromo) {
                    discountInp.value = '';
                    discountInp._autoPromo = false;
                }
                return;
            }
            promoInp._autoDiscount = false;
            if (priceVal) {
                const calcDiscount = calculateDiscountFromPromo(priceVal, promoVal);
                if (calcDiscount) {
                    discountInp.value = calcDiscount;
                    discountInp._autoPromo = true;
                }
            }
        }
    }

    [priceInp, promoInp].forEach(inp => {
        if (!inp || inp._hasCatalogGuard) return;
        inp._hasCatalogGuard = true;

        inp.addEventListener('keydown', (e) => {
            if (['Backspace', 'Delete', 'Tab', 'Escape', 'Enter', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
                return;
            }
            if (e.ctrlKey || e.metaKey) {
                return;
            }
            if (e.key === ',' || e.key === '.') {
                if (inp.value.includes(',') || inp.value.includes('.')) {
                    e.preventDefault();
                }
                return;
            }
            if (/^[0-9]$/.test(e.key)) {
                return;
            }
            // Bloqueia qualquer letra ou símbolo
            e.preventDefault();
        });

        inp.addEventListener('input', () => {
            const sanitized = sanitizeCatalogDecimalInput(inp.value);
            if (inp.value !== sanitized) {
                inp.value = sanitized;
            }
            if (inp === priceInp) {
                syncCatalogPricing('price');
            } else if (inp === promoInp) {
                syncCatalogPricing('promo');
            }
        });

        inp.addEventListener('paste', (e) => {
            const pasteData = (e.clipboardData || window.clipboardData)?.getData('text') || '';
            const clean = sanitizeCatalogDecimalInput(pasteData);
            e.preventDefault();
            const start = inp.selectionStart ?? inp.value.length;
            const end = inp.selectionEnd ?? inp.value.length;
            const nextVal = inp.value.slice(0, start) + clean + inp.value.slice(end);
            inp.value = sanitizeCatalogDecimalInput(nextVal);
            inp.dispatchEvent(new Event('input', { bubbles: true }));
        });
    });

    if (discountInp && !discountInp._hasCatalogGuard) {
        discountInp._hasCatalogGuard = true;

        discountInp.addEventListener('keydown', (e) => {
            if (['Backspace', 'Delete', 'Tab', 'Escape', 'Enter', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
                return;
            }
            if (e.ctrlKey || e.metaKey) {
                return;
            }
            if (e.key === ',' || e.key === '.' || e.key === '%') {
                return;
            }
            if (/^[0-9]$/.test(e.key)) {
                return;
            }
            // Bloqueia qualquer letra ou símbolo
            e.preventDefault();
        });

        discountInp.addEventListener('input', () => {
            const sanitized = sanitizeCatalogDiscountInput(discountInp.value);
            if (discountInp.value !== sanitized) {
                discountInp.value = sanitized;
            }
            syncCatalogPricing('discount');
        });

        discountInp.addEventListener('paste', (e) => {
            const pasteData = (e.clipboardData || window.clipboardData)?.getData('text') || '';
            const clean = sanitizeCatalogDiscountInput(pasteData);
            e.preventDefault();
            const start = discountInp.selectionStart ?? discountInp.value.length;
            const end = discountInp.selectionEnd ?? discountInp.value.length;
            const nextVal = discountInp.value.slice(0, start) + clean + discountInp.value.slice(end);
            discountInp.value = sanitizeCatalogDiscountInput(nextVal);
            discountInp.dispatchEvent(new Event('input', { bubbles: true }));
        });
    }

    if (stockInp && !stockInp._hasCatalogGuard) {
        stockInp._hasCatalogGuard = true;

        stockInp.addEventListener('keydown', (e) => {
            if (['Backspace', 'Delete', 'Tab', 'Escape', 'Enter', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
                return;
            }
            if (e.ctrlKey || e.metaKey) {
                return;
            }
            if (/^[0-9]$/.test(e.key)) {
                return;
            }
            // Bloqueia 'e', 'E', '+', '-', '.', ',' e qualquer letra
            e.preventDefault();
        });

        stockInp.addEventListener('input', () => {
            const sanitized = sanitizeCatalogIntegerInput(stockInp.value);
            if (stockInp.value !== sanitized) {
                stockInp.value = sanitized;
            }
        });

        stockInp.addEventListener('paste', (e) => {
            const pasteData = (e.clipboardData || window.clipboardData)?.getData('text') || '';
            const clean = sanitizeCatalogIntegerInput(pasteData);
            e.preventDefault();
            const start = stockInp.selectionStart ?? stockInp.value.length;
            const end = stockInp.selectionEnd ?? stockInp.value.length;
            const nextVal = stockInp.value.slice(0, start) + clean + stockInp.value.slice(end);
            stockInp.value = sanitizeCatalogIntegerInput(nextVal);
            stockInp.dispatchEvent(new Event('input', { bubbles: true }));
        });
    }
}

// Expiração e Sincronização de Promoção e Desconto (v1.0.163)
export function formatExpirationDateTime(isoString) {
    if (!isoString) return '';
    try {
        const d = new Date(isoString);
        if (isNaN(d.getTime())) return '';
        const day = String(d.getDate()).padStart(2, '0');
        const monthNames = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
        const month = monthNames[d.getMonth()];
        const year = d.getFullYear();
        const hours = String(d.getHours()).padStart(2, '0');
        const minutes = String(d.getMinutes()).padStart(2, '0');
        return `${day} de ${month} de ${year} às ${hours}:${minutes}`;
    } catch(e) {
        return '';
    }
}

export function updateExpirationHint(inputId, hintId) {
    const input = document.getElementById(inputId);
    const hint = document.getElementById(hintId);
    if (!input || !hint) return;

    const val = input.value;
    if (!val) {
        hint.innerText = '';
        hint.style.display = 'none';
        return;
    }

    try {
        const d = new Date(val);
        if (isNaN(d.getTime())) {
            hint.innerText = '';
            hint.style.display = 'none';
            return;
        }
        const now = Date.now();
        const diffMs = d.getTime() - now;
        const formatted = formatExpirationDateTime(val);

        if (diffMs < 0) {
            hint.innerHTML = `<span style="color:#ff4444;"><i data-lucide="alert-triangle"></i> Atenção: data já expirada (${escapeHTML(formatted)})</span>`;
        } else {
            const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
            const diffDays = Math.floor(diffHours / 24);
            const remainHours = diffHours % 24;
            let remainStr = '';
            if (diffDays > 0) {
                remainStr = `${diffDays}d ${remainHours}h restantes`;
            } else {
                remainStr = `${diffHours}h restantes`;
            }
            hint.innerHTML = `<span style="color:var(--accent-color, #00e676);"><i data-lucide="check-circle-2"></i> Expira em: <strong>${escapeHTML(formatted)}</strong> (${remainStr})</span>`;
        }
        hint.style.display = 'block';
        if (window.lucide) lucide.createIcons();
    } catch(e) {
        hint.innerText = '';
        hint.style.display = 'none';
    }
}

export function applyQuickExpiration(targetInputId, durationType, durationValue) {
    const input = document.getElementById(targetInputId);
    if (!input) return;
    const now = new Date();
    if (durationType === 'hours') {
        now.setHours(now.getHours() + durationValue);
    } else if (durationType === 'days') {
        now.setDate(now.getDate() + durationValue);
    }
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const isoVal = `${year}-${month}-${day}T${hours}:${minutes}`;
    input.value = isoVal;

    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
}

export function updateVigenciaExpirationVisibility() {
    const promoTypeSel = document.getElementById('cat-prod-promo-type');
    const discountTypeSel = document.getElementById('cat-prod-discount-type');
    const promoExpRow = document.getElementById('cat-prod-promo-expires-row');
    const discountExpRow = document.getElementById('cat-prod-discount-expires-row');
    const syncRow = document.getElementById('cat-prod-sync-expires-row');
    const syncCheck = document.getElementById('cat-prod-sync-expires');
    const promoExpInp = document.getElementById('cat-prod-promo-expires');
    const discountExpInp = document.getElementById('cat-prod-discount-expires');

    const isPromoTemp = promoTypeSel ? promoTypeSel.value === 'temporario' : false;
    const isDiscountTemp = discountTypeSel ? discountTypeSel.value === 'temporario' : false;

    if (promoExpRow) {
        promoExpRow.style.display = isPromoTemp ? 'flex' : 'none';
    }
    if (discountExpRow) {
        discountExpRow.style.display = isDiscountTemp ? 'flex' : 'none';
    }

    if (syncRow) {
        syncRow.style.display = (isPromoTemp && isDiscountTemp) ? 'flex' : 'none';
    }

    if (isPromoTemp && isDiscountTemp && syncCheck && syncCheck.checked) {
        if (promoExpInp && promoExpInp.value && discountExpInp && !discountExpInp.value) {
            discountExpInp.value = promoExpInp.value;
        } else if (discountExpInp && discountExpInp.value && promoExpInp && !promoExpInp.value) {
            promoExpInp.value = discountExpInp.value;
        }
    }

    updateExpirationHint('cat-prod-promo-expires', 'cat-prod-promo-expires-hint');
    updateExpirationHint('cat-prod-discount-expires', 'cat-prod-discount-expires-hint');
}

export function setupVigenciaExpirationListeners() {
    const promoTypeSel = document.getElementById('cat-prod-promo-type');
    const discountTypeSel = document.getElementById('cat-prod-discount-type');
    const promoExpInp = document.getElementById('cat-prod-promo-expires');
    const discountExpInp = document.getElementById('cat-prod-discount-expires');
    const syncExpiresCheck = document.getElementById('cat-prod-sync-expires');

    if (promoTypeSel && !promoTypeSel.dataset.expBound) {
        promoTypeSel.dataset.expBound = 'true';
        promoTypeSel.addEventListener('change', () => {
            updateVigenciaExpirationVisibility();
        });
    }

    if (discountTypeSel && !discountTypeSel.dataset.expBound) {
        discountTypeSel.dataset.expBound = 'true';
        discountTypeSel.addEventListener('change', () => {
            updateVigenciaExpirationVisibility();
        });
    }

    if (syncExpiresCheck && !syncExpiresCheck.dataset.expBound) {
        syncExpiresCheck.dataset.expBound = 'true';
        syncExpiresCheck.addEventListener('change', () => {
            if (syncExpiresCheck.checked && promoExpInp && discountExpInp) {
                if (promoExpInp.value) {
                    discountExpInp.value = promoExpInp.value;
                } else if (discountExpInp.value) {
                    promoExpInp.value = discountExpInp.value;
                }
            }
            updateVigenciaExpirationVisibility();
        });
    }

    function handlePromoExpChange() {
        if (syncExpiresCheck && syncExpiresCheck.checked && discountExpInp && promoExpInp) {
            discountExpInp.value = promoExpInp.value;
        }
        updateExpirationHint('cat-prod-promo-expires', 'cat-prod-promo-expires-hint');
        if (syncExpiresCheck && syncExpiresCheck.checked) {
            updateExpirationHint('cat-prod-discount-expires', 'cat-prod-discount-expires-hint');
        }
    }

    function handleDiscountExpChange() {
        if (syncExpiresCheck && syncExpiresCheck.checked && promoExpInp && discountExpInp) {
            promoExpInp.value = discountExpInp.value;
        }
        updateExpirationHint('cat-prod-discount-expires', 'cat-prod-discount-expires-hint');
        if (syncExpiresCheck && syncExpiresCheck.checked) {
            updateExpirationHint('cat-prod-promo-expires', 'cat-prod-promo-expires-hint');
        }
    }

    if (promoExpInp && !promoExpInp.dataset.expBound) {
        promoExpInp.dataset.expBound = 'true';
        promoExpInp.addEventListener('input', handlePromoExpChange);
        promoExpInp.addEventListener('change', handlePromoExpChange);
    }

    if (discountExpInp && !discountExpInp.dataset.expBound) {
        discountExpInp.dataset.expBound = 'true';
        discountExpInp.addEventListener('input', handleDiscountExpChange);
        discountExpInp.addEventListener('change', handleDiscountExpChange);
    }

    if (typeof document !== 'undefined') {
        document.querySelectorAll('.catalog-quick-date-btn').forEach(btn => {
            if (!btn.dataset.bound) {
                btn.dataset.bound = 'true';
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    const targetId = btn.dataset.target;
                    const hours = parseInt(btn.dataset.hours, 10);
                    const days = parseInt(btn.dataset.days, 10);
                    if (!isNaN(hours)) {
                        applyQuickExpiration(targetId, 'hours', hours);
                    } else if (!isNaN(days)) {
                        applyQuickExpiration(targetId, 'days', days);
                    }
                });
            }
        });
    }
}

