export function isOfficialStoreDomain(hostname) {
    if (!hostname) return false;
    const lower = hostname.toLowerCase();
    return OFFICIAL_ALLOWED_STORE_DOMAINS.some(allowed => lower === allowed || lower.endsWith('.' + allowed));
}

export function validateProductDigitalLink(rawVal) {
    if (!rawVal || typeof rawVal !== 'string') {
        return { isValid: false, isEmpty: true, formatted: '', domain: '', error: 'Informe o link do produto digital.' };
    }
    const val = rawVal.trim();
    if (!val) {
        return { isValid: false, isEmpty: true, formatted: '', domain: '', error: 'Informe o link do produto digital.' };
    }

    let urlCandidate = val;
    if (!urlCandidate.startsWith('http://') && !urlCandidate.startsWith('https://')) {
        urlCandidate = 'https://' + urlCandidate;
    }

    const url = safeParseURL(urlCandidate);
    if (!url || !url.hostname) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: '',
            error: 'Formato de link inválido. Insira uma URL completa (ex: https://mercadolivre.com.br ou seu site oficial).'
        };
    }

    const hostname = url.hostname.toLowerCase();
    const pathname = (url.pathname || '').toLowerCase();
    const search = (url.search || '').toLowerCase();
    const fullPathAndQuery = pathname + search;

    // 1. Validar protocolo HTTPS
    if (url.protocol !== 'https:' && !urlCandidate.startsWith('https://')) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Apenas links seguros com https:// são aceitos para proteger os compradores.'
        };
    }

    // 2. Bloquear IPs diretos e localhost
    if (
        /^(\d{1,3}\.){3}\d{1,3}$/.test(hostname) ||
        hostname === 'localhost' ||
        hostname.endsWith('.local')
    ) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Endereços de IP diretos ou locais não são permitidos. Use o domínio oficial do site.'
        };
    }

    // 3. Bloquear Encurtadores de Links e Domínios Gratuitos/Suspeitos
    if (FORBIDDEN_SHORTENER_DOMAINS.some(short => hostname === short || hostname.endsWith('.' + short))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Links encurtados não são permitidos por segurança para evitar spam. Insira o link direto e oficial.'
        };
    }
    if (SUSPICIOUS_TUNNEL_DOMAINS.some(tun => hostname === tun || hostname.endsWith('.' + tun))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Domínios de túnel temporário não são permitidos.'
        };
    }
    if (SUSPICIOUS_FREE_TLDS.some(tld => hostname.endsWith(tld))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Domínios temporários ou gratuitos suspeitos não são permitidos. Use um domínio próprio oficial.'
        };
    }

    // 4. Bloquear Downloads de APK e Arquivos Executáveis
    if (FORBIDDEN_APK_DOMAINS.some(apkHost => hostname === apkHost || hostname.endsWith('.' + apkHost))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Download direto de APK não é permitido para evitar malware. Para aplicativos, utilize o link oficial da Google Play Store.'
        };
    }
    for (const ext of FORBIDDEN_FILE_EXTENSIONS) {
        if (pathname.endsWith(ext) || fullPathAndQuery.includes(ext + '?') || fullPathAndQuery.includes(ext + '&')) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                domain: hostname,
                error: `Download direto de arquivos (${ext}) não é permitido por segurança. Para aplicativos, use a Google Play Store.`
            };
        }
    }

    // 5. Bloquear Links de Vídeos e Fotos
    if (FORBIDDEN_VIDEO_DOMAINS.some(vHost => hostname === vHost || hostname.endsWith('.' + vHost))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Links de vídeos não são permitidos para evitar conteúdo indesejado. Apenas lojas ou sites oficiais são aceitos.'
        };
    }
    for (const ext of FORBIDDEN_VIDEO_EXTENSIONS) {
        if (pathname.endsWith(ext) || fullPathAndQuery.includes(ext + '?') || fullPathAndQuery.includes(ext + '&')) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                domain: hostname,
                error: 'Links diretos para arquivos de vídeo não são permitidos.'
            };
        }
    }
    if (
        (hostname.includes('instagram.com') && (pathname.includes('/reel') || pathname.includes('/p/') || pathname.includes('/stories/'))) ||
        hostname.includes('fb.watch') ||
        (hostname.includes('facebook.com') && pathname.includes('/watch'))
    ) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Links de vídeos ou publicações de redes sociais não são permitidos.'
        };
    }
    if (FORBIDDEN_PHOTO_DOMAINS.some(pHost => hostname === pHost || hostname.endsWith('.' + pHost))) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Links de fotos ou hospedagem de imagens não são permitidos.'
        };
    }
    for (const ext of FORBIDDEN_PHOTO_EXTENSIONS) {
        if (pathname.endsWith(ext) || fullPathAndQuery.includes(ext + '?') || fullPathAndQuery.includes(ext + '&')) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                domain: hostname,
                error: 'Links diretos para imagens ou fotos não são permitidos.'
            };
        }
    }

    // 6. Bloquear Casas de Aposta / Bets / Cassinos
    const isBetHouse = BET_SPECIFIC_HOUSES.some(bh => hostname.includes(bh));
    const hasBetDomainToken = (
        hostname.endsWith('.bet') ||
        hostname.endsWith('.casino') ||
        hostname.endsWith('.poker') ||
        /(^|\.)bet\./i.test(hostname) ||
        /(^|[.-])bet([.-]|$)/i.test(hostname) ||
        hostname.includes('aposta') ||
        hostname.includes('cassino') ||
        hostname.includes('casino') ||
        hostname.includes('tigrinho') ||
        fullPathAndQuery.includes('tigrinho') ||
        fullPathAndQuery.includes('fortune-tiger') ||
        fullPathAndQuery.includes('aviator') ||
        fullPathAndQuery.includes('jogodobicho') ||
        fullPathAndQuery.includes('aposta') ||
        fullPathAndQuery.includes('cassino') ||
        fullPathAndQuery.includes('casino')
    );
    if (isBetHouse || hasBetDomainToken) {
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            domain: hostname,
            error: 'Links de apostas, cassinos ou jogos de azar (bets) são estritamente proibidos por segurança.'
        };
    }

    // 7. Verificar se é Marketplace / Plataforma Oficial Autorizada
    const isOfficial = isOfficialStoreDomain(hostname);
    if (isOfficial) {
        return {
            isValid: true,
            isEmpty: false,
            formatted: urlCandidate,
            domain: hostname,
            isOfficialMarketplace: true,
            label: 'Loja / Plataforma Oficial',
            error: ''
        };
    }

    // 8. Verificar se é "Site com domínio comprado e oficial"
    const isValidStructure = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/i.test(hostname);
    const hasValidTLD = VALID_PURCHASED_TLDS.some(tld => hostname.endsWith(tld));

    if (isValidStructure && hasValidTLD) {
        return {
            isValid: true,
            isEmpty: false,
            formatted: urlCandidate,
            domain: hostname,
            isOfficialMarketplace: false,
            label: 'Site Oficial com Domínio Próprio',
            error: ''
        };
    }

    return {
        isValid: false,
        isEmpty: false,
        formatted: val,
        domain: hostname,
        error: 'Domínio não reconhecido como oficial. Use uma loja oficial (Mercado Livre, Shopee, Amazon, AliExpress, Shein, Google Play...) ou site com domínio próprio oficial registrado.'
    };
}

export function applyDigitalLinkValidationFeedback(input, feedbackEl, res) {
    if (!input) return;
    if (res.isEmpty) {
        input.classList.remove('catalog-input-error', 'catalog-input-success');
        if (feedbackEl) {
            feedbackEl.innerText = '';
            feedbackEl.style.display = 'none';
            feedbackEl.className = 'catalog-field-hint catalog-link-feedback';
        }
        return;
    }

    if (res.isValid) {
        input.classList.remove('catalog-input-error');
        input.classList.add('catalog-input-success');
        if (feedbackEl) {
            feedbackEl.className = 'catalog-field-hint catalog-link-feedback valid';
            const badgeIcon = res.isOfficialMarketplace ? 'badge-check' : 'shield-check';
            feedbackEl.innerHTML = `<i data-lucide="${badgeIcon}"></i> <span>${escapeHTML(res.label || 'Link Seguro')}: <strong>${escapeHTML(res.domain)}</strong></span>`;
            feedbackEl.style.display = 'flex';
        }
    } else {
        input.classList.remove('catalog-input-success');
        input.classList.add('catalog-input-error');
        if (feedbackEl) {
            feedbackEl.className = 'catalog-field-hint catalog-link-feedback invalid';
            feedbackEl.innerHTML = `<i data-lucide="shield-alert"></i> <span>${escapeHTML(res.error)}</span>`;
            feedbackEl.style.display = 'flex';
        }
    }

    if (typeof window !== 'undefined' && window.lucide) {
        window.lucide.createIcons();
    }
}

export function setupProductDigitalLinkValidation() {
    const digitalLinkInput = document.getElementById('cat-prod-digital-link');
    const digitalFeedback = document.getElementById('cat-prod-digital-link-feedback');
    const ctaGroup = document.getElementById('cat-prod-digital-cta-group');

    if (digitalLinkInput && !digitalLinkInput.dataset.secBound) {
        digitalLinkInput.dataset.secBound = 'true';
        const handler = () => {
            const val = (digitalLinkInput.value || '').trim();
            if (!val) {
                applyDigitalLinkValidationFeedback(digitalLinkInput, digitalFeedback, { isEmpty: true });
                if (ctaGroup) ctaGroup.style.display = 'none';
                return;
            }
            const res = validateProductDigitalLink(val);
            applyDigitalLinkValidationFeedback(digitalLinkInput, digitalFeedback, res);
            if (ctaGroup) {
                ctaGroup.style.display = res.isValid ? 'block' : 'none';
            }
        };
        digitalLinkInput.addEventListener('input', handler);
        digitalLinkInput.addEventListener('change', handler);
        digitalLinkInput.addEventListener('blur', handler);
    }

    const bizUrlInput = document.getElementById('post-business-btn-url');
    const bizFeedback = document.getElementById('post-business-btn-url-feedback');
    if (bizUrlInput && !bizUrlInput.dataset.secBound) {
        bizUrlInput.dataset.secBound = 'true';
        const handler = () => {
            const val = (bizUrlInput.value || '').trim();
            if (!val) {
                applyDigitalLinkValidationFeedback(bizUrlInput, bizFeedback, { isEmpty: true });
                return;
            }
            const res = validateProductDigitalLink(val);
            applyDigitalLinkValidationFeedback(bizUrlInput, bizFeedback, res);
        };
        bizUrlInput.addEventListener('input', handler);
        bizUrlInput.addEventListener('change', handler);
        bizUrlInput.addEventListener('blur', handler);
    }
}

export function isBusinessAccount(profile = currentProfile) {
    return !!(profile && (profile.accountType === 'business' || profile.isBusiness === true));
}

// Carrinho de Compras (persistido por usuário no localStorage)
function getCartStorageKey() {
    const uid = (currentUser && currentUser.uid) ? currentUser.uid : 'anon';
    return `vortex_catalog_cart_${uid}`;
}

export function getCatalogCart() {
    try {
        if (typeof localStorage === 'undefined') return { sellerUid: '', sellerName: '', sellerPixKey: '', items: [], note: '' };
        const raw = localStorage.getItem(getCartStorageKey());
        if (!raw) return { sellerUid: '', sellerName: '', sellerPixKey: '', items: [], note: '' };
        const parsed = JSON.parse(raw);
        if (!parsed || !Array.isArray(parsed.items)) return { sellerUid: '', sellerName: '', sellerPixKey: '', items: [], note: '' };
        return parsed;
    } catch (e) {
        return { sellerUid: '', sellerName: '', sellerPixKey: '', items: [], note: '' };
    }
}

export function saveCatalogCart(cart) {
    try {
        if (typeof localStorage !== 'undefined') {
            localStorage.setItem(getCartStorageKey(), JSON.stringify(cart));
        }
    } catch (e) {}
    updateCatalogCartBadge();
}

export function clearCatalogCart() {
    appliedCartCoupon = null;
    saveCatalogCart({ sellerUid: '', sellerName: '', sellerPixKey: '', items: [], note: '' });
}

export function updateCatalogCartBadge() {
    const cart = getCatalogCart();
    const count = (cart.items || []).reduce((acc, item) => acc + (Number(item.quantity) || 0), 0);
    const total = (cart.items || []).reduce((acc, item) => {
        const p = (item.promoPrice !== null && item.promoPrice !== undefined && item.promoPrice !== '' && Number(item.promoPrice) > 0)
            ? Number(item.promoPrice)
            : Number(item.price || 0);
        return acc + (p * (Number(item.quantity) || 0));
    }, 0);

    const badge = document.getElementById('catalog-cart-badge');
    const cartBtn = document.getElementById('catalog-cart-btn');
    const cartBar = document.getElementById('catalog-cart-bar');
    const barCount = document.getElementById('catalog-cart-bar-count');
    const barTotal = document.getElementById('catalog-cart-bar-total');

    if (badge) {
        badge.innerText = count > 99 ? '99+' : String(count);
        badge.style.display = count > 0 ? 'inline-flex' : 'none';
    }
    if (cartBtn) {
        cartBtn.style.display = 'inline-flex';
    }
    if (cartBar) {
        // Mostrar barra inferior apenas quando há itens no carrinho e estivermos na vitrine
        const isStorefront = document.getElementById('catalog-view-storefront')?.style.display !== 'none';
        cartBar.style.display = (count > 0 && isStorefront) ? 'flex' : 'none';
    }
    if (barCount) barCount.innerText = `${count} ${count === 1 ? 'item' : 'itens'}`;
    if (barTotal) barTotal.innerText = formatBRL(total);
}

export function addToCatalogCart(product, sellerUid, sellerData = {}, options = {}) {
    if (!product || !sellerUid) return;

    // Verificar se compras estão desabilitadas na loja ou no produto
    const isStoreBuyEnabled = (sellerData?.storeBuyEnabled !== false);
    const isProdBuyEnabled = (product.buyEnabled !== false);
    if (!isStoreBuyEnabled || !isProdBuyEnabled) {
        showToast('Compras Desativadas', 'Esta loja está em modo catálogo no momento. Converse diretamente com o vendedor!', 'orange');
        return;
    }

    const cart = getCatalogCart();

    // Se o carrinho contém itens de outro vendedor, substitui com aviso
    if (cart.sellerUid && cart.sellerUid !== sellerUid && cart.items.length > 0) {
        showToast('Novo Vendedor', 'Seu carrinho anterior foi substituído pelos produtos desta loja.', 'teal');
        cart.items = [];
    }

    cart.sellerUid = sellerUid;
    cart.sellerName = sellerData.name || sellerData.storeName || 'Vendedor VORTEX';
    cart.sellerPixKey = sellerData.pixKey || '';
    if (sellerData.storeShipping) {
        sellerShippingCache.set(sellerUid, sellerData.storeShipping);
    }
    if (sellerData.storeCoupons) {
        sellerCouponsCache.set(sellerUid, sellerData.storeCoupons);
    }

    const selColor = options.selectedColor
        ? (typeof options.selectedColor === 'object' ? (options.selectedColor.name || options.selectedColor.hex) : String(options.selectedColor))
        : null;
    const selColorHex = (options.selectedColor && typeof options.selectedColor === 'object')
        ? options.selectedColor.hex
        : (Array.isArray(product.colors) ? product.colors.find(c => c.name === selColor)?.hex : null);
    const selSize = options.selectedSize ? String(options.selectedSize) : null;
    const selVoltage = options.selectedVoltage ? String(options.selectedVoltage) : null;

    const existingIndex = cart.items.findIndex(i =>
        i.productId === product.id &&
        (i.selectedColor || '') === (selColor || '') &&
        (i.selectedSize || '') === (selSize || '') &&
        (i.selectedVoltage || '') === (selVoltage || '')
    );
    const maxStock = (product.unlimitedStock || product.stock === null || product.stock === undefined || product.stock < 0)
        ? Infinity
        : Number(product.stock);

    const promoExpired = (product.promoType === 'temporario' && product.promoExpiresAt && Date.now() > product.promoExpiresAt);
    const discountExpired = (product.discountType === 'temporario' && product.discountExpiresAt && Date.now() > product.discountExpiresAt);
    const hasActivePromo = !promoExpired && (product.promoPrice !== null && product.promoPrice !== undefined && product.promoPrice !== '' && Number(product.promoPrice) > 0);

    const effectivePrice = hasActivePromo
        ? Number(product.promoPrice)
        : Number(product.price || 0);

    const itemPaymentMethods = (Array.isArray(product.paymentMethods) && product.paymentMethods.length > 0)
        ? [...product.paymentMethods]
        : ['Pix', 'Cartão de Crédito', 'Cartão de Débito', 'Dinheiro'];

    if (existingIndex >= 0) {
        const curQty = Number(cart.items[existingIndex].quantity) || 0;
        if (curQty + 1 > maxStock) {
            showToast('Estoque Limite', `Apenas ${maxStock} unidades disponíveis deste produto.`, 'red');
            return;
        }
        cart.items[existingIndex].quantity = curQty + 1;
        cart.items[existingIndex].price = Number(product.price);
        cart.items[existingIndex].promoPrice = hasActivePromo ? product.promoPrice : null;
        cart.items[existingIndex].effectivePrice = effectivePrice;
        if (product.discount && !discountExpired) cart.items[existingIndex].discount = product.discount;
        if (product.discountType) cart.items[existingIndex].discountType = product.discountType;
        if (product.promoType) cart.items[existingIndex].promoType = product.promoType;
        if (product.promoExpires) cart.items[existingIndex].promoExpires = product.promoExpires;
        if (product.promoExpiresAt) cart.items[existingIndex].promoExpiresAt = product.promoExpiresAt;
        if (product.discountExpires) cart.items[existingIndex].discountExpires = product.discountExpires;
        if (product.discountExpiresAt) cart.items[existingIndex].discountExpiresAt = product.discountExpiresAt;
        cart.items[existingIndex].kind = product.kind || (product.isDigital ? 'digital' : 'fisico');
        cart.items[existingIndex].isDigital = product.kind === 'digital' || !!product.isDigital;
        cart.items[existingIndex].digitalType = product.digitalType || null;
        cart.items[existingIndex].digitalLink = product.digitalLink || null;
        cart.items[existingIndex].digitalCta = product.digitalCta || null;
        if (product.paymentMethods && Array.isArray(product.paymentMethods)) {
            cart.items[existingIndex].paymentMethods = product.paymentMethods;
        }
    } else {
        if (maxStock < 1) {
            showToast('Sem Estoque', 'Este produto está esgotado.', 'red');
            return;
        }
        cart.items.push({
            productId: product.id,
            name: product.name,
            price: Number(product.price),
            promoPrice: hasActivePromo ? product.promoPrice : null,
            effectivePrice: effectivePrice,
            quantity: 1,
            cover: product.cover || (product.photos && product.photos[0]) || '',
            stock: product.stock,
            unlimitedStock: !!product.unlimitedStock,
            paymentMethods: itemPaymentMethods,
            selectedColor: selColor,
            selectedColorHex: selColorHex || null,
            selectedSize: selSize,
            selectedVoltage: selVoltage,
            weight: product.weight || null,
            kind: product.kind || (product.isDigital ? 'digital' : 'fisico'),
            isDigital: product.kind === 'digital' || !!product.isDigital,
            digitalType: product.digitalType || null,
            digitalLink: product.digitalLink || null,
            digitalCta: product.digitalCta || null,
            discount: (!discountExpired ? product.discount : null) || null,
            discountType: product.discountType || null,
            promoType: product.promoType || null,
            promoExpires: product.promoExpires || null,
            promoExpiresAt: product.promoExpiresAt || null,
            discountExpires: product.discountExpires || null,
            discountExpiresAt: product.discountExpiresAt || null
        });
    }

    saveCatalogCart(cart);
    playSound(clickSound);
    showToast('Adicionado! 🛒', `${product.name} adicionado ao carrinho.`, 'green');
    updateCatalogCartBadge();
}

export function updateCatalogCartItemQty(target, delta) {
    const cart = getCatalogCart();
    let item = null;
    let itemIndex = -1;

    if (typeof target === 'number' || (typeof target === 'string' && /^\d+$/.test(target) && Number(target) < cart.items.length)) {
        itemIndex = Number(target);
        item = cart.items[itemIndex];
    }
    if (!item) {
        itemIndex = cart.items.findIndex(i => i.productId === target);
        item = cart.items[itemIndex];
    }
    if (!item || itemIndex < 0) return;

    const newQty = (Number(item.quantity) || 0) + delta;
    if (newQty <= 0) {
        cart.items.splice(itemIndex, 1);
    } else {
        const maxStock = (item.unlimitedStock || item.stock === null || item.stock === undefined || item.stock < 0)
            ? Infinity
            : Number(item.stock);
        if (newQty > maxStock) {
            showToast('Estoque Limite', `Apenas ${maxStock} unidades disponíveis.`, 'red');
            return;
        }
        item.quantity = newQty;
    }

    if (cart.items.length === 0) {
        cart.sellerUid = '';
        cart.sellerName = '';
        cart.sellerPixKey = '';
    }

    saveCatalogCart(cart);
    renderCatalogCartUI();
    updateCatalogCartBadge();
}

