export function formatWebsiteLink(val) {
    if (!val || typeof val !== 'string') return '';
    let clean = val.trim();
    if (!clean) return '';

    if (clean.toLowerCase().startsWith('http://')) {
        clean = 'https://' + clean.slice(7);
    } else if (!clean.toLowerCase().startsWith('https://')) {
        clean = 'https://' + clean;
    }

    try {
        const urlObj = new URL(clean);
        if (urlObj.protocol !== 'https:') {
            urlObj.protocol = 'https:';
        }
        return urlObj.href.replace(/\/$/, '');
    } catch (e) {
        return clean;
    }
}

export function formatSocialLink(network, val) {
    if (!val || typeof val !== 'string') return '';
    const clean = val.trim();
    if (!clean) return '';

    if (typeof validateProfileLink === 'function') {
        const vRes = validateProfileLink(network, clean);
        if (vRes && vRes.isValid && vRes.formatted) {
            return vRes.formatted;
        }
    }

    if (network === 'youtube') {
        if (clean.startsWith('http://') || clean.startsWith('https://')) return clean;
        if (clean.startsWith('youtube.com') || clean.startsWith('www.youtube.com')) return `https://${clean}`;
        if (clean.startsWith('@')) return `https://www.youtube.com/${clean}`;
        return `https://www.youtube.com/@${clean}`;
    }

    if (network === 'instagram') {
        if (clean.startsWith('http://') || clean.startsWith('https://')) return clean;
        if (clean.startsWith('instagram.com') || clean.startsWith('www.instagram.com')) return `https://${clean}`;
        const user = clean.replace(/^@/, '');
        return `https://www.instagram.com/${user}`;
    }

    if (network === 'tiktok') {
        if (clean.startsWith('http://') || clean.startsWith('https://')) return clean;
        if (clean.startsWith('tiktok.com') || clean.startsWith('www.tiktok.com')) return `https://${clean}`;
        const user = clean.replace(/^@/, '');
        return `https://www.tiktok.com/@${user}`;
    }

    if (network === 'facebook') {
        if (clean.startsWith('http://') || clean.startsWith('https://')) return clean;
        if (clean.startsWith('facebook.com') || clean.startsWith('www.facebook.com')) return `https://${clean}`;
        const user = clean.replace(/^@/, '');
        return `https://www.facebook.com/${user}`;
    }

    if (network === 'whatsapp') {
        if (clean.startsWith('http://') || clean.startsWith('https://')) {
            return clean.replace(/^http:\/\//, 'https://');
        }
        if (clean.startsWith('wa.me/')) return `https://${clean}`;
        let digits = clean.replace(/\D/g, '');
        if (!digits) return '';
        if (digits.length === 10 || digits.length === 11) {
            digits = `55${digits}`;
        }
        return `https://wa.me/${digits}`;
    }

    if (network === 'website') {
        return formatWebsiteLink(clean);
    }

    return clean;
}

