let deletedUsersUnsubscribe = null;

export function listenToDeletedUsers() {
    if (deletedUsersUnsubscribe) {
        try { deletedUsersUnsubscribe(); } catch(e) {}
        deletedUsersUnsubscribe = null;
    }
    try {
        const deletedCol = collection(db, 'deleted_users');
        deletedUsersUnsubscribe = onSnapshot(deletedCol, (snapshot) => {
            if (snapshot && typeof snapshot.forEach === 'function') {
                snapshot.forEach(docSnap => {
                    const uid = docSnap.id;
                    if (uid) {
                        deletedUsersSet.add(uid);
                        if (currentUser && currentUser.uid === uid) {
                            handleAccountDeletedRealtime(uid);
                        }
                    }
                });
            }
            if (snapshot && typeof snapshot.docChanges === 'function') {
                try {
                    snapshot.docChanges().forEach(change => {
                        const uid = change.doc ? change.doc.id : null;
                        if (!uid) return;
                        if (change.type === 'added' || change.type === 'modified') {
                            deletedUsersSet.add(uid);
                            handleAccountDeletedRealtime(uid);
                        } else if (change.type === 'removed') {
                            deletedUsersSet.delete(uid);
                        }
                    });
                } catch (e) {}
            }
        }, (err) => {
            console.warn('Aviso deleted_users onSnapshot:', err);
        });
    } catch (err) {
        console.warn('Erro ao inicializar listenToDeletedUsers:', err);
    }
}

export function handleAccountDeletedRealtime(uid) {
    if (!uid) return;
    deletedUsersSet.add(uid);

    // 1. Se for o próprio usuário atualmente logado
    if (currentUser && currentUser.uid === uid) {
        try { signOut(auth); } catch(e) {}
        currentUser = null;
        currentProfile = null;
        try { localStorage.clear(); } catch(e) {}
        try { sessionStorage.clear(); } catch(e) {}
        const authScreen = document.getElementById('auth-screen');
        if (authScreen) authScreen.classList.remove('unlocked');
        showToast("Conta Apagada", "Sua conta foi permanentemente apagada do VORTEX VIP ⚡.", "red");
        setTimeout(() => {
            if (typeof location !== 'undefined' && location.reload) location.reload();
        }, 1200);
        return;
    }

    // 2. Se a conversa aberta for com o usuário deletado
    if (activeChatContact && activeChatContact.uid === uid) {
        if (typeof closeChat === 'function') closeChat();
        showToast("Contato Indisponível", "Esta conta foi apagada e não está mais disponível no VORTEX VIP ⚡.", "red");
    }

    // 3. Se os dados de perfil do contato estiverem abertos
    if (activeContactUserData && activeContactUserData.uid === uid) {
        const panel = document.getElementById('contact-profile-panel');
        if (panel) panel.classList.remove('active');
    }

    // 4. Remover da lista de conversas
    const card = document.querySelector(`.chat-card[data-uid="${uid}"]`);
    if (card) card.remove();

    // 5. Remover da lista de usuários admin
    adminUsers = adminUsers.filter(u => u.id !== uid);
    if (typeof currentAdminTab !== 'undefined' && currentAdminTab === 'users') {
        renderAdminUsers();
    }

    // 6. Remover postagens do usuário na tela
    const postCards = document.querySelectorAll(`[data-author-uid="${uid}"]`);
    postCards.forEach(c => c.remove());
}

export async function deleteUserAccountEntirely(targetUid, options = { deletedBy: 'self' }) {
    if (!targetUid) return;
    try {
        const isSelf = currentUser && currentUser.uid === targetUid;
        const isAdmin = (options && options.deletedBy === 'admin') || (currentProfile && checkIsAdminUser(currentProfile));

        // 1. Adicionar imediatamente ao conjunto de deletados para proteção instantânea
        deletedUsersSet.add(targetUid);

        // 2. Disparar rota backend para exclusão total no Firebase Auth e Firestore (se disponível)
        try {
            if (typeof fetch === 'function') {
                fetch('/api/delete-user-account', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        targetUid,
                        requesterUid: currentUser ? currentUser.uid : targetUid,
                        requesterEmail: (currentUser && currentUser.email) || (currentProfile && currentProfile.email) || '',
                        deletedBy: options.deletedBy || (isSelf ? 'self' : 'admin')
                    })
                }).catch(() => {});
            }
        } catch (apiErr) {
            console.warn('[VORTEX] Aviso chamada API delete-user-account:', apiErr);
        }

        // 3. Gravar tombstone definitivo em deleted_users no Firestore
        try {
            await setDoc(doc(db, 'deleted_users', targetUid), {
                uid: targetUid,
                deleted: true,
                isDeleted: true,
                deletedAt: Date.now(),
                deletedBy: options.deletedBy || (isSelf ? 'self' : 'admin')
            }, { merge: true });
        } catch (e) {
            console.warn('Erro ao gravar tombstone em deleted_users:', e);
        }

        // 4. Banir e marcar conta como apagada no Firestore
        await adminBanUser(targetUid, 'Conta permanentemente apagada do VORTEX VIP ⚡').catch(() => {});
        try {
            await setDoc(doc(db, 'users', targetUid), {
                isDeleted: true,
                deleted: true,
                banned: true,
                banReason: 'Conta permanentemente apagada do VORTEX VIP ⚡',
                name: 'Conta Excluída',
                username: 'conta_excluida',
                avatar: '',
                status: 'Conta apagada.',
                deletedAt: Date.now()
            }, { merge: true });
        } catch (e) {
            console.warn('Erro ao atualizar doc users:', e);
        }

        let deletedPostsCount = 0;
        let deletedStoriesCount = 0;
        let deletedGroupsCount = 0;

        // 5. Excluir postagens no feed deste autor
        try {
            const postsSnap = await getDocs(query(collection(db, 'posts'), where('authorUid', '==', targetUid)));
            if (postsSnap && postsSnap.docs) {
                await Promise.all(postsSnap.docs.map(docSnap => deleteDoc(docSnap.ref)));
                deletedPostsCount = postsSnap.docs.length;
            }
        } catch (e) {
            console.warn('Erro ao deletar posts:', e);
        }

        // 6. Excluir stories deste autor
        try {
            const storiesSnap = await getDocs(query(collection(db, 'stories'), where('authorUid', '==', targetUid)));
            if (storiesSnap && storiesSnap.docs) {
                await Promise.all(storiesSnap.docs.map(docSnap => deleteDoc(docSnap.ref)));
                deletedStoriesCount = storiesSnap.docs.length;
            }
        } catch (e) {
            console.warn('Erro ao deletar stories:', e);
        }

        // 7. Excluir grupos onde ele é criador
        try {
            const groupsSnap = await getDocs(query(collection(db, 'groups'), where('creatorUid', '==', targetUid)));
            if (groupsSnap && groupsSnap.docs) {
                await Promise.all(groupsSnap.docs.map(docSnap => deleteDoc(docSnap.ref)));
                deletedGroupsCount = groupsSnap.docs.length;
            }
        } catch (e) {
            console.warn('Erro ao deletar grupos:', e);
        }

        // 8. Excluir solicitações de amizade
        try {
            const reqsFromSnap = await getDocs(query(collection(db, 'requests'), where('fromUid', '==', targetUid)));
            const reqsToSnap = await getDocs(query(collection(db, 'requests'), where('toUid', '==', targetUid)));
            const allReqs = [...(reqsFromSnap?.docs || []), ...(reqsToSnap?.docs || [])];
            await Promise.all(allReqs.map(d => deleteDoc(d.ref)));
        } catch (e) {}

        // 9. Excluir notificações
        try {
            const notifsToSnap = await getDocs(query(collection(db, 'notifications'), where('toUid', '==', targetUid)));
            const notifsFromSnap = await getDocs(query(collection(db, 'notifications'), where('fromUid', '==', targetUid)));
            const allNotifs = [...(notifsToSnap?.docs || []), ...(notifsFromSnap?.docs || [])];
            await Promise.all(allNotifs.map(d => deleteDoc(d.ref)));
        } catch (e) {}

        // 10. Excluir usernames
        try {
            const uNamesSnap = await getDocs(query(collection(db, 'usernames'), where('uid', '==', targetUid)));
            if (uNamesSnap && uNamesSnap.docs) {
                await Promise.all(uNamesSnap.docs.map(d => deleteDoc(d.ref)));
            }
        } catch (e) {}

        // 11. Atualizar listas locais de administração
        adminPosts = adminPosts.filter(p => p.authorUid !== targetUid);
        adminGroups = adminGroups.filter(g => g.creatorUid !== targetUid);
        adminUsers = adminUsers.filter(u => u.id !== targetUid);

        if (typeof currentAdminTab !== 'undefined') {
            if (currentAdminTab === 'posts') renderAdminPosts();
            if (currentAdminTab === 'groups') renderAdminGroups();
            if (currentAdminTab === 'users') renderAdminUsers();
        }

        // 12. Propagar em tempo real na interface
        handleAccountDeletedRealtime(targetUid);

        if (isSelf) {
            showToast("Conta Apagada", "Sua conta foi apagada com sucesso do VORTEX VIP ⚡.", "blue");
            try { await signOut(auth); } catch(e) {}
            try { localStorage.clear(); } catch(e) {}
            try { sessionStorage.clear(); } catch(e) {}
            setTimeout(() => {
                if (typeof location !== 'undefined' && location.reload) location.reload();
            }, 800);
            return;
        }

        showToast("Conta Apagada", `A conta foi totalmente apagada para todos no VORTEX VIP ⚡.`, "green");
    } catch (err) {
        console.error('Erro ao apagar conta inteira:', err);
        showToast("Erro", "Não foi possível apagar a conta do usuário.", "red");
    }
}

export async function adminPurgeUserData(uid) {
    if (!uid) return;
    return await deleteUserAccountEntirely(uid, { deletedBy: 'admin' });
}

export function openUserDeleteAccountModal() {
    const modal = document.getElementById('user-delete-account-modal');
    if (modal) {
        modal.classList.add('active');
        if (window.lucide) lucide.createIcons();
    }
}

export function closeUserDeleteAccountModal() {
    const modal = document.getElementById('user-delete-account-modal');
    if (modal) modal.classList.remove('active');
}

export async function adminDeletePost(postId) {
    if (!postId) return;
    try {
        await deleteDoc(doc(db, 'posts', postId));
        adminPosts = adminPosts.filter(p => p.id !== postId);
        if (currentAdminTab === 'posts') renderAdminPosts();
        showToast("Post Removido", "Publicação excluída pelo Administrador.", "green");
    } catch (err) {
        console.error('Erro ao excluir post:', err);
        showToast("Erro", "Não foi possível excluir o post.", "red");
    }
}

export async function adminDeleteGroup(groupId) {
    if (!groupId) return;
    try {
        let members = [];
        try {
            const groupSnap = await getDoc(doc(db, 'groups', groupId));
            if (groupSnap.exists() && Array.isArray(groupSnap.data().members)) {
                members = groupSnap.data().members;
            }
        } catch(e) {}

        await deleteDoc(doc(db, 'groups', groupId));

        if (members.length > 0) {
            const batch = writeBatch(db);
            members.forEach(memberUid => {
                batch.delete(doc(db, 'users', memberUid, 'groups', groupId));
            });
            await batch.commit().catch(() => {});
        }

        adminGroups = adminGroups.filter(g => g.id !== groupId);
        if (currentAdminTab === 'groups') renderAdminGroups();
        showToast("Grupo Removido", "Grupo excluído pelo Administrador.", "green");
    } catch (err) {
        console.error('Erro ao excluir grupo:', err);
        showToast("Erro", "Não foi possível excluir o grupo.", "red");
    }
}

export async function adminTogglePauseGroup(groupId, paused) {
    if (!groupId) return;
    try {
        await updateDoc(doc(db, 'groups', groupId), { paused });
        const g = adminGroups.find(x => x.id === groupId);
        if (g) g.paused = paused;
        if (currentAdminTab === 'groups') renderAdminGroups();
        showToast("Grupo Atualizado", paused ? "Grupo pausado com sucesso." : "Grupo liberado com sucesso.", "blue");
    } catch (err) {
        console.error('Erro ao alterar status do grupo:', err);
        showToast("Erro", "Não foi possível atualizar o grupo.", "red");
    }
}

/* ===== ADMIN: Banir Grupo por 30 dias ===== */
export async function adminBanGroup(groupId) {
    if (!groupId) return;
    const g = adminGroups.find(x => x.id === groupId);
    const isBanned = g && g.bannedUntil && g.bannedUntil > Date.now();

    try {
        if (isBanned) {
            // Desbanir
            await updateDoc(doc(db, 'groups', groupId), { bannedUntil: null, banned: false });
            if (g) { g.bannedUntil = null; g.banned = false; }
            if (currentAdminTab === 'groups') renderAdminGroups();
            showToast("Grupo Desbanido", "O grupo foi desbanido e voltou ao normal.", "green");
        } else {
            // Banir por 30 dias
            const bannedUntil = Date.now() + 30 * 24 * 60 * 60 * 1000;
            await updateDoc(doc(db, 'groups', groupId), { bannedUntil, banned: true, paused: true });
            if (g) { g.bannedUntil = bannedUntil; g.banned = true; g.paused = true; }
            if (currentAdminTab === 'groups') renderAdminGroups();
            showToast("Grupo Banido", "O grupo foi banido por 30 dias. Mensagens bloqueadas.", "red");
        }
    } catch (err) {
        console.error('Erro ao banir/desbanir grupo:', err);
        showToast("Erro", "Não foi possível atualizar o status do grupo.", "red");
    }
}

/* ===== ADMIN: Preview de Post no Painel Posts & Feed ===== */
export async function adminOpenPostPreview(postId) {
    const post = adminPosts.find(p => p.id === postId);
    if (!post) {
        showToast('Erro', 'Post não encontrado.', 'red');
        return;
    }

    const modal = document.getElementById('admin-post-preview-modal');
    const content = document.getElementById('admin-post-preview-content');
    if (!modal || !content) return;

    // Mostrar modal com loading enquanto carrega mídia
    content.innerHTML = `
        <div class="admin-post-preview-author-row">
            <div class="avatar sm" style="background-image:url('${post.authorAvatar || ''}');"></div>
            <div>
                <strong style="color:var(--text-main);">${escapeHTML(post.authorName || 'Autor')}</strong>
                <div style="font-size:0.75rem; color:var(--text-dim);">${post.createdAt ? new Date(post.createdAt).toLocaleString('pt-BR') : ''}</div>
            </div>
        </div>
        <div id="admin-preview-media-slot" style="text-align:center; padding:12px 0; color:var(--text-dim); font-size:0.85rem;">⏳ Carregando mídia...</div>
        <p class="admin-post-preview-caption">${escapeHTML(post.caption || 'Sem legenda')}</p>
        ${post.actionButton && post.actionButton.url ? `
            <div class="feed-cta-wrapper" style="margin: 8px 0;">
                <a href="${escapeHTML(post.actionButton.url)}" target="_blank" rel="noopener noreferrer" class="feed-cta-btn" style="text-decoration:none;">
                    <i data-lucide="external-link"></i>
                    <span>${escapeHTML(post.actionButton.text || 'Saiba Mais')}</span>
                </a>
            </div>
        ` : ''}
        <div class="admin-post-preview-stats">
            <span>❤️ ${(post.likes || []).length} curtidas</span>
            <span>💬 ${(post.comments || []).length} comentários</span>
        </div>
        ${(post.comments || []).length > 0 ? `
        <div class="admin-post-preview-comments">
            <strong style="font-size:0.78rem; color:var(--text-dim);">Comentários recentes:</strong>
            ${(post.comments || []).slice(0, 6).map(c => `<div class="admin-post-preview-comment-item"><strong>${escapeHTML(c.author || 'Usuário')}:</strong> ${escapeHTML(c.text || '')}</div>`).join('')}
        </div>` : '<p style="color:var(--text-dim); font-size:0.8rem;">Nenhum comentário ainda.</p>'}
    `;

    modal.style.display = 'flex';
    modal.classList.add('active');
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
        window.lucide.createIcons();
    }

    // Carregar mídia assincronamente (mediaData ou chunks)
    const isVideo = post.type === 'video';
    let mediaSrc = post.mediaData || '';

    if (!mediaSrc && post.hasChunks && post.id) {
        try {
            mediaSrc = await loadMediaWithChunks('posts', post.id, '');
        } catch (e) {
            console.warn('[adminOpenPostPreview] Erro ao carregar chunks:', e);
        }
    }

    const mediaSlot = document.getElementById('admin-preview-media-slot');
    if (mediaSlot) {
        if (mediaSrc) {
            const mediaSrcFinal = isVideo && post.isTrimmed && !mediaSrc.includes('#t=')
                ? `${mediaSrc}#t=0,${post.videoDuration || 120}`
                : mediaSrc;

            mediaSlot.innerHTML = isVideo
                ? `<video class="admin-post-preview-media-video" controls playsinline src="${mediaSrcFinal}"></video>`
                : `<img class="admin-post-preview-media" src="${mediaSrcFinal}" alt="Mídia do post">`;
        } else {
            mediaSlot.innerHTML = '<p style="color:var(--text-dim); font-size:0.8rem; padding:8px 0;">📷 Post sem mídia</p>';
        }
    }

    if (window.lucide) lucide.createIcons();

    const closeBtn = document.getElementById('close-admin-post-preview-modal');
    if (closeBtn) {
        closeBtn.onclick = () => {
            modal.style.display = 'none';
            modal.classList.remove('active');
            content.innerHTML = '';
        };
    }

    modal.onclick = (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
            modal.classList.remove('active');
            content.innerHTML = '';
        }
    };
}


/* ===== ADMIN: Analisar Denúncia (Preview de Conteúdo ou Perfil de Conta/Grupo) ===== */
export async function adminAnalyzeReport(report) {
    if (!report) return;

    const modal = document.getElementById('admin-analyze-modal');
    const content = document.getElementById('admin-analyze-content');
    const titleEl = document.getElementById('admin-analyze-modal-title');
    if (!modal || !content) return;

    content.innerHTML = '<p style="color:var(--text-dim); padding:20px 0; text-align:center;">Carregando...</p>';
    modal.style.display = 'flex';
    modal.classList.add('active');

    const type = report.targetType || 'user';
    let html = '';

    try {
        if (type === 'post') {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="image"></i> Analisando Post Denunciado';
            // O campo correto é report.postId (não targetId)
            const postLookupId = report.postId || report.targetId || report.targetUid;
            let post = adminPosts.find(p => p.id === postLookupId);
            if (!post && postLookupId) {
                try {
                    const snap = await getDoc(doc(db, 'posts', postLookupId));
                    if (snap.exists()) post = { id: snap.id, ...snap.data() };
                } catch (e) {}
            }
            if (post) {
                const isVideo = post.type === 'video';
                // Carregar mídia (mediaData ou chunks)
                let mediaSrc = post.mediaData || '';
                if (!mediaSrc && post.hasChunks && post.id) {
                    try { mediaSrc = await loadMediaWithChunks('posts', post.id, ''); } catch (e) {}
                }
                const mediaSrcFinal = mediaSrc && isVideo && post.isTrimmed && !mediaSrc.includes('#t=')
                    ? `${mediaSrc}#t=0,${post.videoDuration || 120}`
                    : mediaSrc;

                const mediaHtml = mediaSrc
                    ? (isVideo
                        ? `<video class="admin-post-preview-media-video" controls playsinline src="${mediaSrcFinal}"></video>`
                        : `<img class="admin-post-preview-media" src="${mediaSrcFinal}" alt="Mídia do post">`)
                    : '<p style="color:var(--text-dim); font-size:0.8rem;">📷 Post sem mídia</p>';

                const commentsArr = (post.comments || []).slice(0, 5);
                html = `
                    <div class="admin-post-preview-author-row">
                        <div class="avatar sm" style="background-image:url('${post.authorAvatar || ''}');"></div>
                        <div>
                            <strong>${escapeHTML(post.authorName || 'Autor')}</strong>
                            <div style="font-size:0.72rem; color:var(--text-dim);">${post.createdAt ? new Date(post.createdAt).toLocaleString('pt-BR') : ''}</div>
                        </div>
                    </div>
                    ${mediaHtml}
                    ${post.caption ? `<p class="admin-post-preview-caption">${escapeHTML(post.caption)}</p>` : ''}
                    <div class="admin-post-preview-stats">
                        <span>❤️ ${(post.likes || []).length} curtidas</span>
                        <span>💬 ${(post.comments || []).length} comentários</span>
                    </div>
                    ${commentsArr.length > 0 ? `
                    <div class="admin-post-preview-comments">
                        <strong style="font-size:0.78rem; color:var(--text-dim);">Comentários:</strong>
                        ${commentsArr.map(c => `<div class="admin-post-preview-comment-item"><strong>${escapeHTML(c.author || 'Usuário')}:</strong> ${escapeHTML(c.text || '')}</div>`).join('')}
                    </div>` : ''}
                `;
            } else {
                html = '<p style="color:#ff6b6b;">Post não encontrado (pode ter sido removido).</p>';
                if (report.contentSnippet) {
                    html += `<div class="admin-analyze-content-snippet">"${escapeHTML(report.contentSnippet)}"</div>`;
                }
            }
        } else if (type === 'comment') {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="message-circle"></i> Analisando Comentário Denunciado';
            // Tentar buscar o post pai para ver o contexto completo
            const postLookupId = report.postId || report.targetId;
            let parentPost = postLookupId ? adminPosts.find(p => p.id === postLookupId) : null;
            if (!parentPost && postLookupId) {
                try {
                    const snap = await getDoc(doc(db, 'posts', postLookupId));
                    if (snap.exists()) parentPost = { id: snap.id, ...snap.data() };
                } catch (e) {}
            }
            html = `
                <p class="admin-analyze-label">Comentário denunciado:</p>
                <div class="admin-analyze-content-snippet">${escapeHTML(report.contentSnippet || report.details || 'Conteúdo não disponível')}</div>
                ${parentPost ? `<p style="color:var(--text-dim); font-size:0.78rem; margin-top:8px;">📝 Post do(a) <strong>${escapeHTML(parentPost.authorName || 'Autor')}</strong>: "${escapeHTML((parentPost.caption || '').substring(0, 80))}..."</p>` : ''}
                <p style="color:var(--text-dim); font-size:0.78rem; margin-top:4px;">Denunciado por: <strong>${escapeHTML(report.reporterName || 'Anônimo')}</strong></p>
                <p style="color:var(--text-dim); font-size:0.78rem;">Autor do comentário: <strong>${escapeHTML(report.targetName || 'N/A')}</strong></p>
            `;
        } else if (type === 'story') {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="play-circle"></i> Analisando Story Denunciado';
            // O campo correto é report.storyId (não targetId)
            const storyLookupId = report.storyId || report.targetId;
            let story = null;
            if (storyLookupId) {
                try {
                    const snap = await getDoc(doc(db, 'stories', storyLookupId));
                    if (snap.exists()) story = { id: snap.id, ...snap.data() };
                } catch (e) {}
            }
            if (story) {
                const isVideo = story.type === 'video';
                const mediaSrc = story.src || story.mediaData || '';
                const mediaHtml = mediaSrc
                    ? (isVideo
                        ? `<video class="admin-post-preview-media-video" controls playsinline src="${mediaSrc}"></video>`
                        : `<img class="admin-post-preview-media" src="${mediaSrc}" alt="Story">`)
                    : '<p style="color:var(--text-dim); font-size:0.8rem;">📷 Story sem mídia</p>';
                html = `
                    <div class="admin-post-preview-author-row">
                        <div class="avatar sm" style="background-image:url('${story.authorAvatar || ''}');"></div>
                        <strong>${escapeHTML(story.authorName || report.targetName || 'Autor')}</strong>
                    </div>
                    ${mediaHtml}
                    ${story.caption ? `<p class="admin-post-preview-caption">${escapeHTML(story.caption)}</p>` : ''}
                `;
            } else {
                html = `<p style="color:#ff6b6b;">Story não encontrado ou já expirou.</p>`;
                if (report.contentSnippet) html += `<div class="admin-analyze-content-snippet">"${escapeHTML(report.contentSnippet)}"</div>`;
            }
        } else if (type === 'user') {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="user"></i> Analisando Conta Denunciada';
            let userData = adminUsers.find(u => u.id === report.targetUid);
            if (!userData && report.targetUid) {
                try {
                    const snap = await getDoc(doc(db, 'users', report.targetUid));
                    if (snap.exists()) userData = { id: snap.id, ...snap.data() };
                } catch (e) {}
            }
            if (userData) {
                const isBanned = Boolean(userData.banned);
                const isRestricted = isUserRestricted(userData);
                const isVip = checkIsVipUser(userData);
                // Buscar quantidade de posts do usuário
                let postCount = 0;
                try {
                    const postsSnap = await getDocs(query(collection(db, 'posts'), where('authorUid', '==', report.targetUid)));
                    postCount = postsSnap.size;
                } catch (e) {}

                html = `
                    <div class="admin-analyze-user-card">
                        <div class="admin-analyze-user-header">
                            <div class="avatar md" style="background-image:url('${userData.avatar || ''}'); width:52px; height:52px; border-radius:50%; background-size:cover; background-position:center; flex-shrink:0;"></div>
                            <div class="admin-analyze-user-meta">
                                <span class="admin-analyze-user-name">${escapeHTML(userData.name || 'Usuário')} ${isVip ? '⭐' : ''}</span>
                                <span class="admin-analyze-user-username">@${escapeHTML(userData.username || 'sem_username')}</span>
                                <span style="font-size:0.72rem; color:var(--text-dim);">${userData.email || 'Sem e-mail'}</span>
                            </div>
                        </div>
                        ${userData.bio || userData.status ? `<p class="admin-analyze-user-bio">"${escapeHTML(userData.bio || userData.status || '')}"</p>` : ''}
                        <div class="admin-analyze-user-stats">
                            <span>📝 ${postCount} posts</span>
                            <span>🤝 ${(userData.contactCount || 0)} contatos</span>
                            <span>${isVip ? '⭐ VIP verificado' : '👤 Conta normal'}</span>
                        </div>
                        ${isBanned ? `<div class="admin-analyze-user-banned-info">🚫 Conta banida permanentemente</div>` : ''}
                        ${isRestricted ? `<div class="admin-analyze-user-banned-info">⏳ Em restrição temporária (${getRemainingRestrictionTimeFormatted(userData)})</div>` : ''}
                        ${!isBanned && !isRestricted ? `<div style="font-size:0.78rem; color:#34c759; font-weight:600; padding: 4px 0;">✅ Conta ativa sem restrições</div>` : ''}
                        <div class="admin-dossier-card">
                            <div class="admin-dossier-title"><i data-lucide="file-text"></i> Dossiê do Infrator</div>
                            <div class="admin-dossier-grid">
                                <div class="admin-dossier-stat">
                                    <span class="admin-dossier-num">${(typeof adminReports !== 'undefined' && Array.isArray(adminReports)) ? adminReports.filter(r => r.targetUid === report.targetUid).length : 1}</span>
                                    <span class="admin-dossier-label">Denúncias no Total</span>
                                </div>
                                <div class="admin-dossier-stat">
                                    <span class="admin-dossier-num">${userData.restrictedCount || (userData.restricted ? 1 : 0)}</span>
                                    <span class="admin-dossier-label">Restrições Tomadas</span>
                                </div>
                                <div class="admin-dossier-stat">
                                    <span class="admin-dossier-num">${isBanned ? 'Sim 🚫' : 'Não'}</span>
                                    <span class="admin-dossier-label">Banimento Anterior</span>
                                </div>
                            </div>
                            ${userData.createdAt && (Date.now() - userData.createdAt) < 24 * 3600 * 1000 ? `<div class="admin-dossier-alert"><i data-lucide="alert-triangle"></i> Conta criada há menos de 24 horas (Alta suspeita de conta fake).</div>` : ''}
                        </div>
                        <div style="font-size:0.72rem; color:var(--text-dim); margin-top:4px;">UID: ${report.targetUid}</div>
                    </div>
                `;
            } else {
                html = `<p style="color:#ff6b6b;">Conta não encontrada (pode ter sido deletada).</p><div style="font-size:0.78rem; color:var(--text-dim);">UID: ${report.targetUid}</div>`;
            }
        } else if (type === 'group') {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="users"></i> Analisando Grupo Denunciado';
            let groupData = adminGroups.find(g => g.id === report.targetUid || g.id === report.targetId);
            if (!groupData && (report.targetUid || report.targetId)) {
                try {
                    const snap = await getDoc(doc(db, 'groups', report.targetUid || report.targetId));
                    if (snap.exists()) groupData = { id: snap.id, ...snap.data() };
                } catch (e) {}
            }
            if (groupData) {
                const membersCount = (groupData.members || []).length;
                const isPaused = !!groupData.paused;
                const isBanned = groupData.bannedUntil && groupData.bannedUntil > Date.now();
                html = `
                    <div class="admin-analyze-group-card">
                        <div class="admin-analyze-group-header">
                            <div class="avatar sm" style="background-image:url('${groupData.avatar || ''}'); border-radius:50%; flex-shrink:0;"></div>
                            <div>
                                <span class="admin-analyze-group-name">${escapeHTML(groupData.name || 'Grupo VIP')}</span>
                                <div style="font-size:0.72rem; color:var(--text-dim); margin-top:2px;">Criador UID: ${groupData.creatorUid || 'N/A'}</div>
                            </div>
                        </div>
                        ${groupData.description ? `<p class="admin-analyze-group-desc">"${escapeHTML(groupData.description)}"</p>` : ''}
                        <div class="admin-analyze-group-stats">
                            <span>👥 ${membersCount} membros</span>
                            <span>🛡️ ${(groupData.admins || []).length} admins</span>
                            <span>${isPaused ? '⏸️ Pausado' : '✅ Ativo'}</span>
                            ${isBanned ? '<span style="color:#ff6b6b; font-weight:700;">🚫 Banido</span>' : ''}
                        </div>
                    </div>
                `;
            } else {
                html = `<p style="color:#ff6b6b;">Grupo não encontrado (pode ter sido excluído).</p>`;
            }
        } else {
            if (titleEl) titleEl.innerHTML = '<i data-lucide="search"></i> Analisando Denúncia';
            html = `
                <p class="admin-analyze-label">Conteúdo denunciado:</p>
                <div class="admin-analyze-content-snippet">${escapeHTML(report.contentSnippet || report.details || 'Sem conteúdo disponível')}</div>
                <p style="color:var(--text-dim); font-size:0.78rem; margin-top:8px;">Tipo: ${report.targetType || 'N/A'}</p>
            `;
        }
    } catch (e) {
        console.error('Erro ao analisar denúncia:', e);
        html = `<p style="color:#ff6b6b;">Erro ao carregar dados: ${e.message}</p>`;
    }

    // Adicionar motivo e detalhes da denúncia no final
    const reasonText = reportReasonLabels?.[report.reason] || report.reason || 'Não informado';
    html += `
        <div style="margin-top:12px; padding-top:12px; border-top: 1px solid rgba(255,255,255,0.07);">
            <p class="admin-analyze-label" style="margin-bottom:6px;">Detalhes da denúncia:</p>
            <div style="display:flex; flex-direction:column; gap:4px; font-size:0.8rem; color:var(--text-dim);">
                <span>📋 Motivo: <strong style="color:#ff6b6b;">${escapeHTML(reasonText)}</strong></span>
                ${report.details ? `<span>📝 Descrição: "${escapeHTML(report.details)}"</span>` : ''}
                <span>👤 Denunciante: <strong>${escapeHTML(report.reporterName || 'Anônimo')}</strong></span>
            </div>
        </div>
    `;

    // Adicionar Card de Diagnóstico do Algoritmo de Segurança (IA)
    const aiConfidence = report.algorithmConfidence || 'low';
    const confidenceText = aiConfidence === 'high' ? 'Alta (Detectado) 🔴' : (aiConfidence === 'medium' ? 'Média 🟡' : 'Baixa / Inconclusivo 🔵');
    const aiAction = report.algorithmAction || 'none';
    const hasAiAction = !!report.algorithmExplanation;

    if (hasAiAction) {
        html += `
            <div class="admin-ai-analysis-card">
                <div class="admin-ai-header">
                    <div style="display:flex; align-items:center; gap:6px;">
                        <i data-lucide="shield-alert"></i>
                        <span>Parecer do Algoritmo de Segurança (IA)</span>
                    </div>
                    <span class="admin-ai-confidence-pill ${aiConfidence}">${confidenceText}</span>
                </div>
                <div class="admin-ai-explanation">
                    ${escapeHTML(report.algorithmExplanation)}
                </div>
                ${Array.isArray(report.matchedKeywords) && report.matchedKeywords.length > 0 ? `
                    <div>
                        <span style="font-size:0.75rem; color:var(--text-dim); font-weight:700;">Termos críticos identificados:</span>
                        <div style="display:flex; flex-wrap:wrap; gap:4px; margin-top:4px;">
                            ${report.matchedKeywords.map(k => `<span class="admin-ai-keyword-tag">${escapeHTML(k)}</span>`).join('')}
                        </div>
                    </div>
                ` : ''}
                ${Array.isArray(report.previewSnippets) && report.previewSnippets.length > 0 ? `
                    <div>
                        <span style="font-size:0.75rem; color:var(--text-dim); font-weight:700;">Preview do Conteúdo Avaliado:</span>
                        <div style="display:flex; flex-direction:column; gap:4px; margin-top:4px;">
                            ${report.previewSnippets.map(s => `<div class="admin-analyze-content-snippet" style="font-size:0.78rem;">"${escapeHTML(s)}"</div>`).join('')}
                        </div>
                    </div>
                ` : ''}
                ${aiAction === 'pending_admin_approval' && !report.resolved ? `
                    <div class="admin-ai-actions-row">
                        <button type="button" class="admin-btn-action btn-warning admin-ai-restrict-btn" data-report-id="${report.id}">
                            <i data-lucide="clock"></i> Aplicar Restrição (24h)
                        </button>
                        <button type="button" class="admin-btn-action btn-danger admin-ai-ban-btn" data-report-id="${report.id}">
                            <i data-lucide="user-x"></i> Banir Infrator
                        </button>
                        <button type="button" class="admin-btn-action btn-secondary admin-ai-dismiss-btn" data-report-id="${report.id}">
                            <i data-lucide="check"></i> Descartar
                        </button>
                    </div>
                ` : ''}
            </div>
        `;
    }

    content.innerHTML = html;
    if (window.lucide) lucide.createIcons();

    // Wire up AI Action buttons
    content.querySelectorAll('.admin-ai-restrict-btn').forEach(btn => {
        btn.onclick = () => adminExecuteAiAction(btn.dataset.reportId, 'restrict');
    });
    content.querySelectorAll('.admin-ai-ban-btn').forEach(btn => {
        btn.onclick = () => adminExecuteAiAction(btn.dataset.reportId, 'ban');
    });
    content.querySelectorAll('.admin-ai-dismiss-btn').forEach(btn => {
        btn.onclick = () => adminExecuteAiAction(btn.dataset.reportId, 'dismiss');
    });

    const closeBtn = document.getElementById('close-admin-analyze-modal');
    if (closeBtn) {
        closeBtn.onclick = () => {
            modal.style.display = 'none';
            modal.classList.remove('active');
            content.innerHTML = '';
        };
    }

    modal.onclick = (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
            modal.classList.remove('active');
            content.innerHTML = '';
        }
    };
}


export async function adminToggleUserVip(uid, isVip) {
    if (!uid) return;
    try {
        const vipState = Boolean(isVip);
        await updateDoc(doc(db, 'users', uid), {
            isVip: vipState,
            isVerified: vipState,
            vipRequestStatus: vipState ? 'approved' : 'rejected'
        });

        const u = adminUsers.find(x => x.id === uid);
        if (u) {
            u.isVip = vipState;
            u.isVerified = vipState;
            u.vipRequestStatus = vipState ? 'approved' : 'rejected';
        }

        const req = adminVipRequests.find(r => r.id === uid || r.uid === uid);
        if (req) {
            req.status = vipState ? 'approved' : 'rejected';
            await updateDoc(doc(db, 'vip_requests', req.id || uid), {
                status: vipState ? 'approved' : 'rejected'
            }).catch(() => {});
        }

        if (currentUser && currentUser.uid === uid) {
            currentProfile.isVip = vipState;
            currentProfile.isVerified = vipState;
            currentProfile.vipRequestStatus = vipState ? 'approved' : 'rejected';
            updateProfileDOM();
        }

        const tagEl = document.getElementById(`vip-tag-${uid}`);
        if (tagEl) {
            tagEl.style.display = vipState ? 'inline-block' : 'none';
        }
        const card = document.querySelector(`.chat-card[data-uid="${uid}"]`);
        if (card) {
            card.dataset.isVip = vipState ? 'true' : 'false';
        }

        if (currentAdminTab === 'users') renderAdminUsers();
        if (currentAdminTab === 'vip-requests') renderAdminVipRequests();
        showToast("Status VIP", vipState ? "Selo VIP concedido com sucesso." : "Selo VIP removido com sucesso.", "blue");
    } catch (err) {
        console.error('Erro ao atualizar VIP:', err);
        showToast("Erro", "Não foi possível atualizar o selo VIP.", "red");
    }
}

export async function adminResolveReport(reportId) {
    if (!reportId) return;
    try {
        await updateDoc(doc(db, 'reports', reportId), {
            resolved: true,
            resolvedAt: Date.now()
        });
        const rep = adminReports.find(r => r.id === reportId);
        if (rep) rep.resolved = true;
        renderAdminReports();
        showToast("Denúncia Resolvida", "Denúncia marcada como tratada.", "green");
    } catch (err) {
        console.error('Erro ao resolver denúncia:', err);
        showToast("Erro", "Não foi possível resolver a denúncia.", "red");
    }
}

