/* ==========================================================================
   PWA - GERENCIAMENTO DE INSTALAÇÃO NO NAVEGADOR (VORTEX VIP ⚡)
   ========================================================================== */

let pwaDeferredPrompt = null;
let pwaIsInstalled = false;
export const CURRENT_APP_VERSION = '1.0.189';
export let pwaUpdateAvailable = false;
export let pwaWaitingWorker = null;
export let pwaRegistration = null;
let latestRemoteVersion = null;

export function compareAppVersions(v1, v2) {
    const parts1 = String(v1 || '0.0.0').split('.').map(n => parseInt(n, 10) || 0);
    const parts2 = String(v2 || '0.0.0').split('.').map(n => parseInt(n, 10) || 0);
    const len = Math.max(parts1.length, parts2.length);
    for (let i = 0; i < len; i++) {
        const a = parts1[i] || 0;
        const b = parts2[i] || 0;
        if (a > b) return 1;
        if (a < b) return -1;
    }
    return 0;
}

export function getEffectiveAppVersion() {
    let bestVersion = CURRENT_APP_VERSION;
    try {
        if (typeof document !== 'undefined' && typeof document.querySelector === 'function') {
            const linkEl = document.querySelector('link[href*="style.css?v="]');
            const scriptEl = document.querySelector('script[src*="script.js?v="]');
            const href = (scriptEl && scriptEl.getAttribute('src')) || (linkEl && linkEl.getAttribute('href')) || '';
            const match = href.match(/[?&]v=([0-9]+\.[0-9]+\.[0-9]+)/);
            if (match && match[1] && compareAppVersions(match[1], bestVersion) > 0) {
                bestVersion = match[1];
            }
        }
        if (typeof localStorage !== 'undefined') {
            const applied = localStorage.getItem('vortex_applied_version');
            if (applied && compareAppVersions(applied, bestVersion) > 0) {
                bestVersion = applied;
            }
        }
    } catch (_) {}
    return bestVersion;
}

function wasRecentlyUpdated() {
    try {
        if (typeof sessionStorage !== 'undefined') {
            const ts = parseInt(sessionStorage.getItem('vortex_just_updated') || '0', 10);
            if (ts && (Date.now() - ts) < 30000) return true;
        }
    } catch (_) {}
    return false;
}

export function setDeferredPrompt(promptEvent) {
    pwaDeferredPrompt = promptEvent;
}

export function getDeferredPrompt() {
    return pwaDeferredPrompt;
}

export function setPwaIsInstalled(val) {
    pwaIsInstalled = !!val;
    updateInstallUIVisibility();
}

export function getPwaIsInstalled() {
    return pwaIsInstalled;
}

export function isPwaUpdateAvailable() {
    return pwaUpdateAvailable;
}

export function setPwaUpdateAvailable(val) {
    pwaUpdateAvailable = !!val;
    updateInstallUIVisibility();
}

export function isAppInstalledPwa() {
    if (typeof window === 'undefined') return false;
    const isStandaloneDisplay = typeof window.matchMedia === 'function' && window.matchMedia('(display-mode: standalone)').matches;
    const isNavStandalone = typeof navigator !== 'undefined' && (navigator.standalone === true);
    const isAndroidApp = typeof document !== 'undefined' && document.referrer && document.referrer.includes('android-app://');
    return isStandaloneDisplay || isNavStandalone || isAndroidApp || pwaIsInstalled;
}

export function isIosSafari() {
    if (typeof window === 'undefined' || typeof navigator === 'undefined') return false;
    const ua = navigator.userAgent || '';
    const isIos = /iphone|ipad|ipod/i.test(ua);
    const isSafari = /safari/i.test(ua) && !/chrome|crios|fxios|edgios/i.test(ua);
    return isIos && isSafari && !isAppInstalledPwa();
}

export function updateInstallUIVisibility() {
    if (typeof document === 'undefined') return;
    const isInstalled = isAppInstalledPwa();
    const headerBtn = document.getElementById('install-app-header-btn');
    const settingRow = document.getElementById('install-app-setting-item');
    const banner = document.getElementById('pwa-install-banner');
    const installBtn = document.getElementById('install-pwa-btn');
    const settingDesc = document.getElementById('install-setting-desc');
    const settingLabel = settingRow?.querySelector?.('.install-setting-label');

    if (isInstalled) {
        if (banner) banner.style.display = 'none';

        if (pwaUpdateAvailable) {
            // Nova versão disponível para quem tem o app instalado no Celular ou PC!
            if (headerBtn) {
                headerBtn.style.display = 'flex';
                headerBtn.title = 'Atualizar VORTEX VIP (Nova Versão Disponível)';
                headerBtn.setAttribute('aria-label', 'Atualizar Aplicativo');
                headerBtn.innerHTML = '<i data-lucide="refresh-cw" class="install-inline-icon rotating-update-icon"></i>';
            }
            if (settingRow) {
                settingRow.style.display = 'flex';
                settingRow.classList.add('update-available-row');
                if (settingLabel) {
                    settingLabel.innerHTML = '<i data-lucide="refresh-cw" class="install-inline-icon rotating-update-icon"></i> Atualizar Aplicativo ⚡';
                }
                if (settingDesc) {
                    settingDesc.textContent = 'Nova versão disponível! Toque em Atualizar para aplicar as novidades.';
                }
            }
            if (installBtn) {
                installBtn.textContent = 'Atualizar';
                installBtn.title = 'Atualizar aplicativo para a versão mais recente';
                installBtn.classList.add('btn-update-pulse');
            }
            if (typeof window !== 'undefined' && window.lucide) {
                window.lucide.createIcons();
            }
            return;
        }

        // Instalado e sem atualização pendente: ocultar o botão Atualizar
        if (headerBtn) headerBtn.style.display = 'none';
        if (settingRow) {
            settingRow.style.display = 'none';
            settingRow.classList.remove('update-available-row');
        }
        if (installBtn) {
            installBtn.classList.remove('btn-update-pulse');
        }
        return;
    }

    // Não instalado: fluxo padrão de instalação
    const canInstall = !!pwaDeferredPrompt || isIosSafari();
    if (headerBtn) {
        headerBtn.style.display = canInstall ? 'flex' : 'none';
        headerBtn.title = 'Instalar VORTEX VIP no Dispositivo';
        headerBtn.setAttribute('aria-label', 'Instalar Aplicativo');
        headerBtn.innerHTML = '<i data-lucide="download"></i>';
    }
    if (settingRow) {
        settingRow.style.display = 'flex';
        settingRow.classList.remove('update-available-row');
        if (settingLabel) {
            settingLabel.innerHTML = '<i data-lucide="download" class="install-inline-icon"></i> Instalar Aplicativo ⚡';
        }
        if (settingDesc) {
            settingDesc.textContent = 'Instalar o VORTEX VIP no navegador ou na tela inicial';
        }
    }
    if (installBtn) {
        installBtn.textContent = 'Instalar';
        installBtn.title = 'Instalar aplicativo no dispositivo';
        installBtn.classList.remove('btn-update-pulse');
    }
    if (typeof window !== 'undefined' && window.lucide) {
        window.lucide.createIcons();
    }
}

export function showPwaBannerIfEligible() {
    if (typeof document === 'undefined' || isAppInstalledPwa()) return;
    try {
        if (sessionStorage.getItem('vortex_pwa_banner_dismissed') === 'true') return;
    } catch (_) {}

    const banner = document.getElementById('pwa-install-banner');
    if (banner) {
        banner.style.display = 'block';
    }
}

export function dismissPwaInstallBanner() {
    const banner = document.getElementById('pwa-install-banner');
    if (banner) banner.style.display = 'none';
    try {
        sessionStorage.setItem('vortex_pwa_banner_dismissed', 'true');
    } catch (_) {}
}

export function openPwaIosModal() {
    const modal = document.getElementById('pwa-ios-modal');
    if (modal) {
        modal.style.display = 'flex';
        if (window.lucide) lucide.createIcons();
    }
}

export function closePwaIosModal() {
    const modal = document.getElementById('pwa-ios-modal');
    if (modal) modal.style.display = 'none';
}

export async function triggerPwaUpdate() {
    // Ocultar imediatamente o botão de Atualizar ao clicar
    pwaUpdateAvailable = false;
    const workerToActivate = pwaWaitingWorker;
    pwaWaitingWorker = null;

    try {
        const targetVer = latestRemoteVersion || getEffectiveAppVersion();
        if (typeof localStorage !== 'undefined' && targetVer) {
            localStorage.setItem('vortex_applied_version', targetVer);
        }
        if (typeof sessionStorage !== 'undefined') {
            sessionStorage.setItem('vortex_just_updated', String(Date.now()));
        }
    } catch (_) {}

    updateInstallUIVisibility();
    showToast('Atualizando VORTEX VIP ⚡', 'Baixando a versão mais recente e reiniciando o aplicativo...', 'yellow');

    try {
        if (typeof fetch === 'function') {
            const verRes = await fetch('/version.json?t=' + Date.now(), { cache: 'no-store' }).catch(() => null);
            if (verRes && verRes.ok) {
                const verData = await verRes.json().catch(() => null);
                if (verData && verData.version && typeof localStorage !== 'undefined') {
                    localStorage.setItem('vortex_applied_version', verData.version);
                }
            }
        }
        if (workerToActivate) {
            workerToActivate.postMessage({ type: 'SKIP_WAITING' });
        }
        if (pwaRegistration && typeof pwaRegistration.update === 'function') {
            await pwaRegistration.update();
        }
        if (typeof window !== 'undefined' && 'caches' in window) {
            const keys = await caches.keys();
            await Promise.all(keys.map(k => caches.delete(k)));
        }
    } catch (err) {
        console.warn('[PWA] Erro durante atualização:', err);
    }

    setTimeout(() => {
        if (typeof window !== 'undefined' && window.location) {
            window.location.reload(true);
        }
    }, 600);
}

export async function checkForAppUpdates(manual = false) {
    if (typeof window === 'undefined' || typeof fetch === 'undefined') return false;
    try {
        if (pwaRegistration && typeof pwaRegistration.update === 'function') {
            await pwaRegistration.update();
        }

        const res = await fetch('/version.json?t=' + Date.now(), { cache: 'no-store' });
        if (res.ok) {
            const data = await res.json();
            const effectiveVersion = getEffectiveAppVersion();
            if (data && data.version && compareAppVersions(data.version, effectiveVersion) > 0 && !wasRecentlyUpdated()) {
                latestRemoteVersion = data.version;
                pwaUpdateAvailable = true;
                updateInstallUIVisibility();
                if (manual) {
                    showToast('Nova Versão Encontrada! ⚡', 'Versão ' + data.version + ' disponível. Toque em Atualizar!', 'yellow');
                }
                return true;
            } else {
                // Já está na versão mais recente: garantir que o botão Atualizar suma
                pwaUpdateAvailable = false;
                updateInstallUIVisibility();
            }
        }
    } catch (err) {
        console.warn('[PWA] Falha ao verificar atualizações:', err);
    }

    if (manual) {
        showToast('Aplicativo Atualizado ✅', 'Você já está utilizando a versão mais recente do VORTEX VIP (v' + getEffectiveAppVersion() + ').', 'green');
    }
    return false;
}

export async function triggerPwaInstall() {
    if (pwaUpdateAvailable) {
        await triggerPwaUpdate();
        return;
    }

    if (isIosSafari()) {
        openPwaIosModal();
        return;
    }

    if (pwaDeferredPrompt) {
        try {
            pwaDeferredPrompt.prompt();
            const choiceResult = await pwaDeferredPrompt.userChoice;
            if (choiceResult && choiceResult.outcome === 'accepted') {
                pwaIsInstalled = true;
                dismissPwaInstallBanner();
                showToast('Instalação Iniciada', 'VORTEX VIP ⚡ está sendo adicionado ao seu dispositivo!', 'yellow');
            }
            pwaDeferredPrompt = null;
            updateInstallUIVisibility();
        } catch (err) {
            console.warn('[PWA] Erro ao disparar prompt:', err);
        }
    } else {
        showToast('Instalação', 'Para instalar, clique no menu do navegador (⋮ ou configurações) e selecione "Instalar aplicativo" ou "Adicionar à tela inicial".', 'yellow');
    }
}

// Registro do Service Worker e escuta de eventos PWA
if (typeof window !== 'undefined') {
    if ('serviceWorker' in navigator) {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('/sw.js').then((reg) => {
                pwaRegistration = reg;
                console.log('[VORTEX VIP] Service Worker ativo com sucesso! Escopo:', reg.scope);

                // 1. Se já existe um worker em espera
                if (reg.waiting) {
                    if (wasRecentlyUpdated()) {
                        reg.waiting.postMessage({ type: 'SKIP_WAITING' });
                        pwaUpdateAvailable = false;
                        updateInstallUIVisibility();
                    } else {
                        pwaWaitingWorker = reg.waiting;
                        pwaUpdateAvailable = true;
                        updateInstallUIVisibility();
                    }
                }

                // 2. Se um novo worker for baixado
                reg.addEventListener('updatefound', () => {
                    const newWorker = reg.installing;
                    if (newWorker) {
                        newWorker.addEventListener('statechange', () => {
                            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                                if (wasRecentlyUpdated()) {
                                    newWorker.postMessage({ type: 'SKIP_WAITING' });
                                    pwaUpdateAvailable = false;
                                    updateInstallUIVisibility();
                                    return;
                                }
                                pwaWaitingWorker = newWorker;
                                pwaUpdateAvailable = true;
                                updateInstallUIVisibility();
                                showToast('Nova Versão Disponível ⚡', 'Uma atualização do VORTEX VIP está pronta. Vá em Configurações para Atualizar!', 'yellow');
                            }
                        });
                    }
                });

                // 3. Checar imediatamente se há nova versão no servidor
                checkForAppUpdates();
            }).catch((err) => {
                console.warn('[VORTEX VIP] Erro ao registrar Service Worker:', err);
            });
        });

        // Recarregar quando o novo worker assumir o controle
        let refreshing = false;
        navigator.serviceWorker.addEventListener('controllerchange', () => {
            if (!refreshing) {
                refreshing = true;
                pwaUpdateAvailable = false;
                updateInstallUIVisibility();
                window.location.reload();
            }
        });
    }

    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        pwaDeferredPrompt = e;
        updateInstallUIVisibility();
        showPwaBannerIfEligible();
    });

    window.addEventListener('appinstalled', () => {
        pwaIsInstalled = true;
        pwaDeferredPrompt = null;
        updateInstallUIVisibility();
        dismissPwaInstallBanner();
        showToast('Aplicativo Instalado! ⚡', 'VORTEX VIP foi instalado com sucesso. Agora você pode abrir diretamente pela tela inicial!', 'green');
    });

    window.addEventListener('focus', () => {
        if (isAppInstalledPwa()) {
            checkForAppUpdates();
        }
    });
}

