/* ==========================================================================
   HISTÓRICO DE LIGAÇÕES DENTRO DAS CONVERSAS & CHAMADAS WEBRTC P2P (v1.0.182)
   ========================================================================== */

export function formatCallDuration(seconds) {
    const s = Math.max(0, parseInt(seconds, 10) || 0);
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    if (mins === 0) {
        return `${secs} seg`;
    }
    return `${mins}m ${String(secs).padStart(2, '0')}s`;
}

export function formatCallDurationDigital(seconds) {
    const s = Math.max(0, parseInt(seconds, 10) || 0);
    const mins = String(Math.floor(s / 60)).padStart(2, '0');
    const secs = String(s % 60).padStart(2, '0');
    return `${mins}:${secs}`;
}

export function buildCallCardHTML(msg, isMe = null) {
    if (!msg) return '';
    if (isMe === null) {
        isMe = currentUser ? (msg.senderUid === currentUser.uid || msg.callerUid === currentUser.uid) : false;
    }

    const callType = msg.callType || 'video';
    const isVideo = callType !== 'audio';
    const status = msg.callStatus || 'completed';
    const seconds = Number(msg.durationSeconds) || 0;
    const durFormatted = msg.durationFormatted || formatCallDuration(seconds);

    let statusClass = 'call-status-completed';
    let iconName = isVideo ? 'video' : 'phone';
    let title = '';
    let subtitle = '';

    if (status === 'completed') {
        statusClass = 'call-status-completed';
        if (isMe) {
            iconName = isVideo ? 'video' : 'phone-outgoing';
            title = isVideo ? 'Chamada de vídeo efetuada' : 'Chamada de voz efetuada';
            subtitle = `Duração: ${durFormatted}`;
        } else {
            iconName = isVideo ? 'video' : 'phone-incoming';
            title = isVideo ? 'Chamada de vídeo recebida' : 'Chamada de voz recebida';
            subtitle = `Duração: ${durFormatted}`;
        }
    } else if (status === 'missed') {
        statusClass = 'call-status-missed';
        iconName = isVideo ? 'video-off' : 'phone-missed';
        if (isMe) {
            title = isVideo ? 'Chamada de vídeo não atendida' : 'Chamada de voz não atendida';
            subtitle = 'Sem resposta';
        } else {
            title = isVideo ? 'Chamada de vídeo perdida' : 'Chamada de voz perdida';
            subtitle = 'Toque para retornar';
        }
    } else if (status === 'rejected') {
        statusClass = 'call-status-rejected';
        iconName = isVideo ? 'video-off' : 'phone-off';
        if (isMe) {
            title = isVideo ? 'Chamada de vídeo recusada' : 'Chamada de voz recusada';
            subtitle = 'Recusada pelo contato';
        } else {
            title = isVideo ? 'Chamada de vídeo recusada' : 'Chamada de voz recusada';
            subtitle = 'Você recusou esta chamada';
        }
    } else {
        statusClass = 'call-status-canceled';
        iconName = isVideo ? 'video-off' : 'phone-missed';
        title = isVideo ? 'Chamada cancelada' : 'Chamada cancelada';
        subtitle = 'Cancelada antes de atender';
    }

    return `
        <div class="chat-call-card ${statusClass}" data-msg-id="${msg.id || ''}" data-call-type="${callType}" data-call-status="${status}">
            <div class="chat-call-main">
                <div class="chat-call-icon-wrap" title="${escapeHTML(title)}">
                    <i data-lucide="${iconName}"></i>
                </div>
                <div class="chat-call-info">
                    <span class="chat-call-title">${escapeHTML(title)}</span>
                    <span class="chat-call-subtitle">${escapeHTML(subtitle)}</span>
                </div>
            </div>
            <div class="chat-call-action-wrap">
                <button type="button" class="chat-call-return-btn" data-call-type="${callType}" title="Ligar de volta">
                    <i data-lucide="${isVideo ? 'video' : 'phone'}"></i>
                    <span>Retornar</span>
                </button>
            </div>
        </div>
    `;
}

export async function recordCallInChat(context, explicitStatus = null, explicitSeconds = null) {
    if (!context || !context.chatId) return;
    const finalSeconds = explicitSeconds !== null ? explicitSeconds : (callSeconds || context.durationSeconds || 0);
    let finalStatus = explicitStatus;
    if (!finalStatus) {
        if (context.isConnected || finalSeconds > 0) {
            finalStatus = 'completed';
        } else {
            finalStatus = 'missed';
        }
    }

    const durFormatted = formatCallDuration(finalSeconds);
    const isVideo = context.callType !== 'audio';
    const typeLabel = isVideo ? 'Chamada de vídeo' : 'Chamada de voz';
    let textSummary = '';
    if (finalStatus === 'completed') {
        textSummary = `📞 ${typeLabel} (${durFormatted})`;
    } else if (finalStatus === 'rejected') {
        textSummary = `📞 ${typeLabel} recusada`;
    } else {
        textSummary = `📞 ${typeLabel} perdida`;
    }

    const callMsgId = context.callId ? `call_${context.callId}` : `call_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    const msgData = {
        id: callMsgId,
        type: 'call',
        callType: context.callType || 'video',
        callStatus: finalStatus,
        durationSeconds: finalSeconds,
        durationFormatted: durFormatted,
        callerUid: context.callerUid,
        calleeUid: context.calleeUid,
        callerName: context.callerName || 'Usuário',
        calleeName: context.calleeName || 'Contato',
        senderUid: context.callerUid,
        senderName: context.callerName || 'Usuário',
        text: textSummary,
        createdAt: context.createdAt || Date.now()
    };

    try {
        if (typeof doc === 'function' && typeof setDoc === 'function') {
            const msgRef = doc(db, 'chats', context.chatId, 'messages', callMsgId);
            await setDoc(msgRef, msgData, { merge: true });

            // Atualiza resumo da conversa
            const chatDocRef = doc(db, 'chats', context.chatId);
            await setDoc(chatDocRef, {
                lastMessage: textSummary,
                lastMessageText: textSummary,
                lastMessageType: 'call',
                lastMessageTime: Date.now(),
                updatedAt: Date.now()
            }, { merge: true }).catch(() => {});
        }
    } catch (e) {
        console.warn('Erro ao registrar histórico de ligação no chat:', e);
    }
}

export let currentCallHistoryFilter = 'all';
export let currentCallHistoryContact = null;

export async function openCallHistoryModal(filter = 'all', targetContact = null) {
    const modal = document.getElementById('call-history-modal');
    if (!modal) return;

    // 1. Resolver o contato alvo para isolar estritamente o histórico
    let contact = targetContact;
    if (!contact) {
        const profilePanel = document.getElementById('contact-profile-panel');
        const isProfileActive = profilePanel && profilePanel.classList.contains('active');
        if (isProfileActive && (activeContactProfileData || activeContactProfileUid)) {
            contact = activeContactProfileData || (typeof contactUserDataMap !== 'undefined' && contactUserDataMap.get(activeContactProfileUid)) || { uid: activeContactProfileUid };
        } else {
            contact = activeChatContact;
        }
    }
    currentCallHistoryContact = contact || null;
    currentCallHistoryFilter = filter;

    // 2. Atualizar subtítulo com nome do contato no topo do modal
    const contactNameEl = document.getElementById('call-history-contact-name');
    if (contactNameEl) {
        const cName = contact?.name || contact?.displayName || '';
        if (cName) {
            contactNameEl.innerText = `Com ${cName}`;
            contactNameEl.style.display = 'block';
        } else {
            contactNameEl.style.display = 'none';
            contactNameEl.innerText = '';
        }
    }

    modal.style.display = 'flex';
    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    playSound(clickSound);

    document.querySelectorAll('.call-history-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.filter === filter);
    });

    await renderCallHistoryList(filter, null, contact);
}

export function closeCallHistoryModal() {
    const modal = document.getElementById('call-history-modal');
    if (!modal) return;
    modal.style.display = 'none';
    modal.classList.remove('active');
    modal.setAttribute('aria-hidden', 'true');
    playSound(clickSound);
}

export async function renderCallHistoryList(filter = 'all', customCalls = null, targetContact = null) {
    const content = document.getElementById('call-history-content');
    if (!content) return;

    if (Array.isArray(filter)) {
        customCalls = filter;
        filter = 'all';
    }

    // Resolver contato alvo (prioridade: targetContact > currentCallHistoryContact > perfil aberto > activeChatContact)
    let contact = targetContact || currentCallHistoryContact;
    if (!contact) {
        const profilePanel = document.getElementById('contact-profile-panel');
        const isProfileActive = profilePanel && profilePanel.classList.contains('active');
        if (isProfileActive && (activeContactProfileData || activeContactProfileUid)) {
            contact = activeContactProfileData || (typeof contactUserDataMap !== 'undefined' && contactUserDataMap.get(activeContactProfileUid)) || { uid: activeContactProfileUid };
        } else {
            contact = activeChatContact;
        }
    }
    const contactUid = contact?.uid || contact?.id || null;

    let callMessages = Array.isArray(customCalls) ? [...customCalls] : [];

    // 1. Mensagens em memória da conversa atual SOMENTE se for estritamente o mesmo contato
    const isActiveChatSameContact = activeChatContact && contactUid && (
        activeChatContact.uid === contactUid || activeChatContact.id === contactUid
    );

    if (callMessages.length === 0 && isActiveChatSameContact && typeof currentChatMessagesMap !== 'undefined' && currentChatMessagesMap && currentChatMessagesMap.size > 0) {
        currentChatMessagesMap.forEach(msg => {
            if (msg.type === 'call') {
                const belongsToContact = (
                    msg.callerUid === contactUid ||
                    msg.calleeUid === contactUid ||
                    msg.senderUid === contactUid
                );
                if (belongsToContact) {
                    callMessages.push(msg);
                }
            }
        });
    }

    // 2. Se vazio ou se não for o chat ativo, busca do Firestore pelo chatId específico deste contato
    if (callMessages.length === 0 && currentUser && contactUid && typeof db !== 'undefined') {
        const targetChatId = contact?.isGroup ? `group_${contactUid}` : [currentUser.uid, contactUid].sort().join('_');
        if (typeof getDocs === 'function' && typeof collection === 'function') {
            try {
                const q = query(
                    collection(db, 'chats', targetChatId, 'messages'),
                    where('type', '==', 'call'),
                    orderBy('createdAt', 'desc'),
                    limit(50)
                );
                const snap = await getDocs(q);
                snap.forEach(docSnap => {
                    const data = docSnap.data();
                    const belongs = (
                        data.callerUid === contactUid ||
                        data.calleeUid === contactUid ||
                        data.senderUid === contactUid
                    );
                    if (belongs) {
                        callMessages.push({ ...data, id: docSnap.id });
                    }
                });
            } catch (e) {
                console.warn('Erro na busca composta de chamadas no Firestore, tentando sem order:', e);
                try {
                    const qFallback = query(
                        collection(db, 'chats', targetChatId, 'messages'),
                        where('type', '==', 'call'),
                        limit(50)
                    );
                    const snap = await getDocs(qFallback);
                    snap.forEach(docSnap => {
                        const data = docSnap.data();
                        const belongs = (
                            data.callerUid === contactUid ||
                            data.calleeUid === contactUid ||
                            data.senderUid === contactUid
                        );
                        if (belongs) {
                            callMessages.push({ ...data, id: docSnap.id });
                        }
                    });
                } catch (e2) {
                    console.warn('Erro ao buscar ligações no fallback:', e2);
                }
            }
        }
    }

    // 3. Filtro rigoroso de isolamento por UID de contato: NUNCA misturar chamadas de outro contato
    if (contactUid) {
        callMessages = callMessages.filter(c => (
            c.callerUid === contactUid ||
            c.calleeUid === contactUid ||
            c.senderUid === contactUid
        ));
    }

    // 4. Ordenar por data decrescente
    callMessages.sort((a, b) => (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0));

    // 5. Calcular métricas isoladas para este contato
    const totalCount = callMessages.length;
    const completedCalls = callMessages.filter(c => c.callStatus === 'completed');
    const missedCalls = callMessages.filter(c => c.callStatus === 'missed' || c.callStatus === 'rejected');
    const totalSeconds = completedCalls.reduce((acc, c) => acc + (Number(c.durationSeconds) || 0), 0);

    const totalEl = document.getElementById('call-stat-total');
    const completedEl = document.getElementById('call-stat-completed');
    const missedEl = document.getElementById('call-stat-missed');
    const durationEl = document.getElementById('call-stat-duration');

    if (totalEl) totalEl.innerText = String(totalCount);
    if (completedEl) completedEl.innerText = String(completedCalls.length);
    if (missedEl) missedEl.innerText = String(missedCalls.length);
    if (durationEl) {
        const totalMins = Math.round(totalSeconds / 60);
        durationEl.innerText = totalMins > 0 ? `${totalMins}m` : (totalSeconds > 0 ? `${totalSeconds}s` : '0m');
    }

    // 6. Filtrar pela aba selecionada
    let filtered = callMessages;
    if (filter === 'completed') {
        filtered = completedCalls;
    } else if (filter === 'missed') {
        filtered = missedCalls;
    }

    // 7. Estado Vazio com nome do contato
    const contactDisplayName = contact?.name || contact?.displayName || 'este contato';
    if (filtered.length === 0) {
        content.innerHTML = `
            <div class="call-history-empty">
                <i data-lucide="phone-off"></i>
                <p>Nenhuma ligação encontrada</p>
                <small>${filter === 'all' ? `Você ainda não realizou ou recebeu chamadas com ${escapeHTML(contactDisplayName)}.` : 'Nenhuma ligação corresponde a este filtro.'}</small>
            </div>
        `;
        if (window.lucide) lucide.createIcons();
        return;
    }

    content.innerHTML = filtered.map(call => {
        const isMe = currentUser ? (call.senderUid === currentUser.uid || call.callerUid === currentUser.uid) : false;
        const callType = call.callType || 'video';
        const isVideo = callType !== 'audio';
        const status = call.callStatus || 'completed';
        const seconds = Number(call.durationSeconds) || 0;
        const durFormatted = call.durationFormatted || formatCallDuration(seconds);

        let iconClass = 'icon-completed';
        let iconName = isVideo ? 'video' : 'phone-outgoing';
        let title = '';
        let statusLabel = '';

        if (status === 'completed') {
            iconClass = 'icon-completed';
            if (isMe) {
                iconName = isVideo ? 'video' : 'phone-outgoing';
                title = isVideo ? 'Chamada de vídeo efetuada' : 'Chamada de voz efetuada';
                statusLabel = durFormatted ? `Atendida (${durFormatted})` : 'Atendida';
            } else {
                iconName = isVideo ? 'video' : 'phone-incoming';
                title = isVideo ? 'Chamada de vídeo recebida' : 'Chamada de voz recebida';
                statusLabel = durFormatted ? `Atendida (${durFormatted})` : 'Atendida';
            }
        } else if (status === 'missed') {
            iconClass = 'icon-missed';
            iconName = isVideo ? 'video-off' : 'phone-missed';
            if (isMe) {
                title = isVideo ? 'Chamada de vídeo não atendida' : 'Chamada de voz não atendida';
                statusLabel = 'Não atendida';
            } else {
                title = isVideo ? 'Chamada de vídeo perdida' : 'Chamada de voz perdida';
                statusLabel = 'Perdida';
            }
        } else {
            iconClass = 'icon-rejected';
            iconName = isVideo ? 'video-off' : 'phone-off';
            title = isVideo ? 'Chamada de vídeo recusada' : 'Chamada de voz recusada';
            statusLabel = 'Recusada';
        }

        let dateStr = '';
        if (call.createdAt) {
            try {
                const d = new Date(call.createdAt);
                if (!isNaN(d.getTime())) {
                    const day = String(d.getDate()).padStart(2, '0');
                    const month = String(d.getMonth() + 1).padStart(2, '0');
                    const hours = String(d.getHours()).padStart(2, '0');
                    const mins = String(d.getMinutes()).padStart(2, '0');
                    dateStr = `${day}/${month} às ${hours}:${mins}`;
                }
            } catch (_) {}
        }

        return `
            <div class="call-history-item" data-call-id="${call.id || ''}">
                <div class="call-history-item-left">
                    <div class="call-history-item-icon ${iconClass}">
                        <i data-lucide="${iconName}"></i>
                    </div>
                    <div class="call-history-item-details">
                        <span class="call-history-item-title">${escapeHTML(title)}</span>
                        <div class="call-history-item-meta">
                            <span>${escapeHTML(dateStr)}</span>
                            <span>•</span>
                            <span class="call-history-item-duration status-${status}">${escapeHTML(statusLabel)}</span>
                        </div>
                    </div>
                </div>
                <button type="button" class="call-history-call-btn" data-call-type="${callType}" title="Ligar para ${escapeHTML(contactDisplayName)}">
                    <i data-lucide="${isVideo ? 'video' : 'phone'}"></i>
                </button>
            </div>
        `;
    }).join('');

    if (window.lucide) lucide.createIcons();
}

export async function startCall(isVideo = true) {
    if (!activeChatContact || !currentUser) return;
    if (isUserBanned(currentProfile)) {
        showToast('Conta Suspensa', 'Sua conta está banida.', 'red');
        return;
    }
    if (isUserRestricted(currentProfile)) {
        showRestrictionActionNotice();
        return;
    }
    if (!activeChatContact.isGroup) {
        if (blockedContactsSet.has(activeChatContact.uid)) {
            showToast('Contato Bloqueado', 'Você bloqueou este contato. Desbloqueie para fazer chamadas.', 'red');
            return;
        }
        if (isBlockedByActiveContact) {
            showToast('Bloqueado', 'Você foi bloqueado por este contato e não pode realizar chamadas.', 'red');
            return;
        }
    }

    const overlay = document.getElementById('video-call-overlay');
    const nameEl = document.getElementById('call-name');
    const avatarEl = document.getElementById('call-avatar');
    const statusEl = document.getElementById('call-status');
    const timerEl = document.getElementById('call-timer');
    const userInfoBox = document.getElementById('call-user-info-box');
    const localPip = document.getElementById('local-video-wrapper');
    const switchCamBtn = document.getElementById('switch-camera-btn');

    if (nameEl) nameEl.innerText = activeChatContact.name;
    if (avatarEl) avatarEl.style.backgroundImage = activeChatContact.avatar ? `url('${activeChatContact.avatar}')` : '';
    if (statusEl) statusEl.innerText = isVideo ? 'Chamando (Vídeo)...' : 'Chamando (Áudio)...';
    if (timerEl) {
        timerEl.style.display = 'none';
        timerEl.innerText = '00:00';
    }
    if (userInfoBox) {
        userInfoBox.classList.remove('video-active');
        if (!isVideo) userInfoBox.classList.add('audio-only-call');
        else userInfoBox.classList.remove('audio-only-call');
    }

    if (overlay) {
        overlay.classList.add('active');
        if (!isVideo) overlay.classList.add('audio-call-mode');
        else overlay.classList.remove('audio-call-mode');
    }
    if (localPip) localPip.style.display = isVideo ? '' : 'none';
    if (switchCamBtn) switchCamBtn.style.display = isVideo ? 'flex' : 'none';

    playSound(clickSound);
    ringtoneSound.play().catch(() => {});

    try {
        isCallMuted = false;
        isCameraOff = !isVideo;
        updateCameraToggleButtonUI(isCameraOff);

        const callMedia = await requestCallMedia(isVideo);
        localStream = callMedia.stream;
        if (!callMedia.hasVideo || !isVideo) {
            if (statusEl) statusEl.innerText = isVideo ? 'Conectado somente com áudio' : 'Chamando (Áudio)...';
            if (userInfoBox) userInfoBox.classList.add('audio-only-call');
            if (localPip) localPip.style.display = 'none';
            if (switchCamBtn) switchCamBtn.style.display = 'none';
        }
        const localFeed = document.getElementById('local-webcam-feed');
        if (localFeed && callMedia.hasVideo) localFeed.srcObject = localStream;

        peerConnection = new RTCPeerConnection(rtcServers);
        remoteStream = new MediaStream();

        const remoteFeed = document.getElementById('remote-webcam-feed');
        if (remoteFeed) remoteFeed.srcObject = remoteStream;

        localStream.getTracks().forEach(track => peerConnection.addTrack(track, localStream));
        if (!isVideo && typeof peerConnection.addTransceiver === 'function') {
            try {
                peerConnection.addTransceiver('video', { direction: 'recvonly' });
            } catch (_) {}
        }

        peerConnection.ontrack = (event) => {
            event.streams[0].getTracks().forEach(track => remoteStream.addTrack(track));
            const hasVideo = (event.track && event.track.kind === 'video') || (remoteStream.getVideoTracks && remoteStream.getVideoTracks().length > 0);
            if (hasVideo && userInfoBox) {
                userInfoBox.classList.add('video-active');
                if (overlay) overlay.classList.remove('audio-call-mode');
                userInfoBox.classList.remove('audio-only-call');
            }
        };

        const targetChatId = getActiveChatId() || [currentUser.uid, activeChatContact.uid].sort().join('_');
        activeCallRecordContext = {
            callId: null,
            chatId: targetChatId,
            callerUid: currentUser.uid,
            callerName: currentProfile?.name || currentUser?.displayName || 'Você',
            calleeUid: activeChatContact.uid,
            calleeName: activeChatContact.name || 'Contato',
            callType: isVideo ? 'video' : 'audio',
            createdAt: Date.now(),
            isConnected: false,
            durationSeconds: 0
        };

        const callDocRef = await addDoc(collection(db, 'calls'), {
            callerUid: currentUser.uid,
            callerName: currentProfile.name,
            callerUsername: currentProfile.username,
            callerAvatar: currentProfile.avatar,
            calleeUid: activeChatContact.uid,
            calleeName: activeChatContact.name,
            chatId: targetChatId,
            status: 'ringing',
            type: isVideo ? 'video' : 'audio',
            createdAt: Date.now()
        });
        currentCallId = callDocRef.id;
        if (activeCallRecordContext) activeCallRecordContext.callId = currentCallId;

        const callerCandidatesCol = collection(db, 'calls', currentCallId, 'callerCandidates');
        peerConnection.onicecandidate = (event) => {
            if (event.candidate) addDoc(callerCandidatesCol, event.candidate.toJSON()).catch(() => {});
        };

        const offerDescription = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offerDescription);

        await updateDoc(callDocRef, {
            offer: { sdp: offerDescription.sdp, type: offerDescription.type }
        });

        // Acorda o celular do destinatário mesmo com o app fechado (push de chamada)
        notifyCallPush(currentCallId);

        if (activeCallDocUnsubscribe) activeCallDocUnsubscribe();
        activeCallDocUnsubscribe = onSnapshot(callDocRef, async (snap) => {
            if (snap && (typeof snap.exists === 'function' ? snap.exists() : !!snap.exists)) {
                const data = typeof snap.data === 'function' ? snap.data() : (snap.data || {});
                if (!peerConnection.currentRemoteDescription && data.answer) {
                    const answerDescription = new RTCSessionDescription(data.answer);
                    await peerConnection.setRemoteDescription(answerDescription);

                    if (activeCallRecordContext) activeCallRecordContext.isConnected = true;
                    ringtoneSound.pause();
                    ringtoneSound.currentTime = 0;
                    if (statusEl) {
                        statusEl.innerText = isVideo 
                            ? 'Conectado • Criptografia Quântica VIP'
                            : 'Conectado • Chamada de Áudio VIP';
                    }
                    if (timerEl) timerEl.style.display = 'block';

                    if (!callTimerInterval) {
                        callSeconds = 0;
                        callTimerInterval = setInterval(() => {
                            callSeconds++;
                            const mins = String(Math.floor(callSeconds / 60)).padStart(2, '0');
                            const secs = String(callSeconds % 60).padStart(2, '0');
                            if (timerEl) timerEl.innerText = `${mins}:${secs}`;
                        }, 1000);
                    }
                } else if (data.status === 'rejected') {
                    showToast("Chamada", "A chamada foi recusada.", "red");
                    if (activeCallRecordContext) {
                        recordCallInChat(activeCallRecordContext, 'rejected', 0);
                        activeCallRecordContext = null;
                    }
                    endCall();
                } else if (data.status === 'ended') {
                    endCall();
                }

                if (data.type === 'video' || data.isVideoCall) {
                    if (overlay && overlay.classList.contains('audio-call-mode')) {
                        overlay.classList.remove('audio-call-mode');
                        if (userInfoBox) {
                            userInfoBox.classList.remove('audio-only-call');
                            userInfoBox.classList.add('video-active');
                        }
                        if (statusEl && statusEl.innerText.includes('Áudio')) {
                            statusEl.innerText = 'Conectado • Chamada de Vídeo VIP';
                        }
                    }
                }
            }
        });

        const calleeCandidatesCol = collection(db, 'calls', currentCallId, 'calleeCandidates');
        if (calleeCandidatesUnsubscribe) calleeCandidatesUnsubscribe();
        calleeCandidatesUnsubscribe = onSnapshot(calleeCandidatesCol, (snapshot) => {
            if (snapshot && typeof snapshot.docChanges === 'function') {
                snapshot.docChanges().forEach(async (change) => {
                    if (change.type === 'added') {
                        const candidate = new RTCIceCandidate(change.doc.data());
                        await peerConnection.addIceCandidate(candidate).catch(() => {});
                    }
                });
            }
        });

    } catch (err) {
        console.error("Erro ao iniciar chamada WebRTC:", err);
        showToast("Erro", isVideo ? "Não foi possível acessar a câmera ou microfone." : "Não foi possível acessar o microfone.", "red");
        endCall();
    }
}

function listenToIncomingCalls() {
    if (!currentUser) return;
    const callsRef = collection(db, 'calls');
    const q = query(callsRef, where('calleeUid', '==', currentUser.uid), where('status', '==', 'ringing'), limit(1));

    incomingCallUnsubscribe = onSnapshot(q, (snap) => {
        const incomingOverlay = document.getElementById('incoming-call-overlay');
        if (!snap.empty) {
            const callDoc = snap.docs[0];
            const callData = callDoc.data();
            if (callData.callerUid && blockedContactsSet.has(callData.callerUid)) {
                updateDoc(doc(db, 'calls', callDoc.id), { status: 'rejected', endedAt: Date.now() }).catch(() => {});
                return;
            }
            currentCallId = callDoc.id;

            const targetChatId = callData.chatId || [callData.callerUid, currentUser.uid].sort().join('_');
            activeCallRecordContext = {
                callId: callDoc.id,
                chatId: targetChatId,
                callerUid: callData.callerUid,
                callerName: callData.callerName || 'Contato',
                calleeUid: currentUser.uid,
                calleeName: currentProfile?.name || currentUser?.displayName || 'Você',
                callType: callData.type || 'video',
                createdAt: callData.createdAt || Date.now(),
                isConnected: false,
                durationSeconds: 0
            };

            const nameEl = document.getElementById('incoming-caller-name');
            const userEl = document.getElementById('incoming-caller-username');
            const avatarEl = document.getElementById('incoming-caller-avatar');

            if (nameEl) nameEl.innerText = callData.callerName || 'Contato VIP';
            if (userEl) userEl.innerText = callData.callerUsername || '@usuario';
            if (avatarEl) avatarEl.style.backgroundImage = callData.callerAvatar ? `url('${callData.callerAvatar}')` : '';

            const isVideoCall = callData.type !== 'audio';
            const descEl = document.getElementById('incoming-caller-desc');
            if (descEl) {
                descEl.innerText = isVideoCall 
                    ? 'Chamada de Vídeo e Áudio P2P Criptografada'
                    : 'Chamada de Áudio P2P Criptografada';
            }
            const acceptBtn = document.getElementById('accept-call-btn');
            if (acceptBtn) {
                acceptBtn.innerHTML = `<i data-lucide="${isVideoCall ? 'video' : 'phone'}"></i>`;
                acceptBtn.title = isVideoCall ? 'Atender Chamada de Vídeo' : 'Atender Chamada de Áudio';
            }
            if (window.lucide && typeof window.lucide.createIcons === 'function') lucide.createIcons();

            if (incomingOverlay) incomingOverlay.classList.add('active');
            
            ringtoneSound.play().catch(() => {});
            startPhoneVibration();

            if (activeCallDocUnsubscribe) activeCallDocUnsubscribe();
            activeCallDocUnsubscribe = onSnapshot(doc(db, 'calls', currentCallId), (docSnap) => {
                if (docSnap.exists() && docSnap.data().status === 'ended') {
                    dismissIncomingCallUI();
                }
            });

            // Aberto pelo botão "Atender" da notificação: atende automaticamente
            consumePendingCallLink(callDoc.id);
        } else {
            dismissIncomingCallUI();
        }
    });
}

function dismissIncomingCallUI() {
    const incomingOverlay = document.getElementById('incoming-call-overlay');
    if (incomingOverlay) incomingOverlay.classList.remove('active');
    ringtoneSound.pause();
    ringtoneSound.currentTime = 0;
    stopPhoneVibration();
}

async function acceptIncomingCall() {
    if (!currentCallId) return;
    dismissIncomingCallUI();

    const overlay = document.getElementById('video-call-overlay');
    const nameEl = document.getElementById('call-name');
    const statusEl = document.getElementById('call-status');
    const timerEl = document.getElementById('call-timer');
    const userInfoBox = document.getElementById('call-user-info-box');
    const localPip = document.getElementById('local-video-wrapper');
    const switchCamBtn = document.getElementById('switch-camera-btn');

    if (overlay) overlay.classList.add('active');

    try {
        const callDocRef = doc(db, 'calls', currentCallId);
        const callSnap = await getDoc(callDocRef);
        const callData = callSnap.data() || {};
        const isVideo = callData.type !== 'audio';

        if (overlay) {
            if (!isVideo) overlay.classList.add('audio-call-mode');
            else overlay.classList.remove('audio-call-mode');
        }
        if (localPip) localPip.style.display = isVideo ? '' : 'none';
        if (switchCamBtn) switchCamBtn.style.display = isVideo ? 'flex' : 'none';

        isCallMuted = false;
        isCameraOff = !isVideo;
        updateCameraToggleButtonUI(isCameraOff);

        const callMedia = await requestCallMedia(isVideo);
        localStream = callMedia.stream;
        if (!callMedia.hasVideo || !isVideo) {
            if (statusEl) statusEl.innerText = isVideo ? 'Atendendo somente com áudio' : 'Conectado • Chamada de Áudio VIP';
            if (userInfoBox) userInfoBox.classList.add('audio-only-call');
            if (localPip) localPip.style.display = 'none';
            if (switchCamBtn) switchCamBtn.style.display = 'none';
        }
        const localFeed = document.getElementById('local-webcam-feed');
        if (localFeed && callMedia.hasVideo) localFeed.srcObject = localStream;

        peerConnection = new RTCPeerConnection(rtcServers);
        remoteStream = new MediaStream();

        const remoteFeed = document.getElementById('remote-webcam-feed');
        if (remoteFeed) remoteFeed.srcObject = remoteStream;

        localStream.getTracks().forEach(track => peerConnection.addTrack(track, localStream));
        if (!isVideo && typeof peerConnection.addTransceiver === 'function') {
            try {
                peerConnection.addTransceiver('video', { direction: 'recvonly' });
            } catch (_) {}
        }

        peerConnection.ontrack = (event) => {
            event.streams[0].getTracks().forEach(track => remoteStream.addTrack(track));
            const hasVideo = (event.track && event.track.kind === 'video') || (remoteStream.getVideoTracks && remoteStream.getVideoTracks().length > 0);
            if (hasVideo && userInfoBox) {
                userInfoBox.classList.add('video-active');
                if (overlay) overlay.classList.remove('audio-call-mode');
                userInfoBox.classList.remove('audio-only-call');
            }
        };

        if (nameEl) nameEl.innerText = callData.callerName || 'Contato';

        const calleeCandidatesCol = collection(db, 'calls', currentCallId, 'calleeCandidates');
        peerConnection.onicecandidate = (event) => {
            if (event.candidate) addDoc(calleeCandidatesCol, event.candidate.toJSON()).catch(() => {});
        };

        const offerDescription = callData.offer;
        await peerConnection.setRemoteDescription(new RTCSessionDescription(offerDescription));

        const answerDescription = await peerConnection.createAnswer();
        await peerConnection.setLocalDescription(answerDescription);

        await updateDoc(callDocRef, {
            answer: { type: answerDescription.type, sdp: answerDescription.sdp },
            status: 'connected',
            answeredAt: Date.now()
        });

        if (activeCallRecordContext) activeCallRecordContext.isConnected = true;

        const callerCandidatesCol = collection(db, 'calls', currentCallId, 'callerCandidates');
        if (callerCandidatesUnsubscribe) callerCandidatesUnsubscribe();
        callerCandidatesUnsubscribe = onSnapshot(callerCandidatesCol, (snapshot) => {
            if (snapshot && typeof snapshot.docChanges === 'function') {
                snapshot.docChanges().forEach(async (change) => {
                    if (change.type === 'added') {
                        const candidate = new RTCIceCandidate(change.doc.data());
                        await peerConnection.addIceCandidate(candidate).catch(() => {});
                    }
                });
            }
        });

        if (statusEl) {
            statusEl.innerText = isVideo 
                ? 'Conectado • Criptografia Quântica VIP'
                : 'Conectado • Chamada de Áudio VIP';
        }
        if (timerEl) {
            timerEl.style.display = 'block';
            callSeconds = 0;
            clearInterval(callTimerInterval);
            callTimerInterval = setInterval(() => {
                callSeconds++;
                const mins = String(Math.floor(callSeconds / 60)).padStart(2, '0');
                const secs = String(callSeconds % 60).padStart(2, '0');
                if (timerEl) timerEl.innerText = `${mins}:${secs}`;
            }, 1000);
        }

        if (activeCallDocUnsubscribe) activeCallDocUnsubscribe();
        activeCallDocUnsubscribe = onSnapshot(callDocRef, (snap) => {
            if (snap && (typeof snap.exists === 'function' ? snap.exists() : !!snap.exists) && typeof snap.data === 'function') {
                const data = snap.data();
                if (data.status === 'ended') {
                    endCall();
                    return;
                }
                if (data.type === 'video' || data.isVideoCall) {
                    const overlay = document.getElementById('video-call-overlay');
                    const userInfoBox = document.getElementById('call-user-info-box');
                    const statusEl = document.getElementById('call-status');
                    if (overlay && overlay.classList.contains('audio-call-mode')) {
                        overlay.classList.remove('audio-call-mode');
                        if (userInfoBox) {
                            userInfoBox.classList.remove('audio-only-call');
                            userInfoBox.classList.add('video-active');
                        }
                        if (statusEl && statusEl.innerText.includes('Áudio')) {
                            statusEl.innerText = 'Conectado • Chamada de Vídeo VIP';
                        }
                    }
                }
            }
        });

    } catch (e) {
        console.error("Erro ao aceitar chamada WebRTC:", e);
        endCall();
    }
}

async function declineIncomingCall() {
    if (!currentCallId) return;
    dismissIncomingCallUI();
    if (activeCallRecordContext) {
        recordCallInChat(activeCallRecordContext, 'rejected', 0);
        activeCallRecordContext = null;
    }
    await updateDoc(doc(db, 'calls', currentCallId), { status: 'rejected', endedAt: Date.now() }).catch(() => {});
    currentCallId = null;
}

async function endCall() {
    ringtoneSound.pause();
    ringtoneSound.currentTime = 0;
    stopPhoneVibration();
    clearInterval(callTimerInterval);
    const finalSeconds = callSeconds;
    callTimerInterval = null;

    if (activeCallDocUnsubscribe) {
        activeCallDocUnsubscribe();
        activeCallDocUnsubscribe = null;
    }
    if (calleeCandidatesUnsubscribe) {
        calleeCandidatesUnsubscribe();
        calleeCandidatesUnsubscribe = null;
    }
    if (callerCandidatesUnsubscribe) {
        callerCandidatesUnsubscribe();
        callerCandidatesUnsubscribe = null;
    }

    if (activeCallRecordContext) {
        const finalStatus = (activeCallRecordContext.isConnected || finalSeconds > 0) ? 'completed' : 'missed';
        recordCallInChat(activeCallRecordContext, finalStatus, finalSeconds);
        activeCallRecordContext = null;
    }

    if (currentCallId) {
        const idToEnd = currentCallId;
        currentCallId = null;
        await updateDoc(doc(db, 'calls', idToEnd), { status: 'ended', endedAt: Date.now(), duration: finalSeconds }).catch(() => {});
    }
    callSeconds = 0;

    if (peerConnection) {
        peerConnection.close();
        peerConnection = null;
    }

    if (localStream) {
        localStream.getTracks().forEach(t => t.stop());
        localStream = null;
    }

    const localFeed = document.getElementById('local-webcam-feed');
    const remoteFeed = document.getElementById('remote-webcam-feed');
    if (localFeed) localFeed.srcObject = null;
    if (remoteFeed) remoteFeed.srcObject = null;

    const overlay = document.getElementById('video-call-overlay');
    if (overlay) {
        overlay.classList.remove('active');
        overlay.classList.remove('audio-call-mode');
    }
    const localPip = document.getElementById('local-video-wrapper');
    if (localPip) localPip.style.display = '';
    const switchCamBtn = document.getElementById('switch-camera-btn');
    if (switchCamBtn) switchCamBtn.style.display = '';
    const userInfoBox = document.getElementById('call-user-info-box');
    if (userInfoBox) {
        userInfoBox.classList.remove('video-active');
        userInfoBox.classList.remove('audio-only-call');
    }
    dismissIncomingCallUI();
    playSound(clickSound);

    isCallMuted = false;
    isCameraOff = false;
    updateCameraToggleButtonUI(false);
    const micBtn = document.getElementById('mute-mic-btn');
    if (micBtn) {
        micBtn.style.background = 'rgba(255, 255, 255, 0.12)';
        micBtn.title = 'Silenciar Microfone';
        micBtn.setAttribute('aria-label', 'Silenciar Microfone');
        micBtn.innerHTML = '<i data-lucide="mic"></i>';
    }
    if (window.lucide) lucide.createIcons();
}

/* ==========================================================================
   MODAL DE SELEÇÃO DE TIPO DE CHAMADA (VÍDEO OU ÁUDIO) - v1.0.184
   ========================================================================== */
export function openCallTypeModal(targetContact = null) {
    const contact = targetContact || activeChatContact;
    if (!contact || !currentUser) return;
    if (isUserBanned(currentProfile)) {
        showToast('Conta Suspensa', 'Sua conta está banida.', 'red');
        return;
    }
    if (isUserRestricted(currentProfile)) {
        showRestrictionActionNotice();
        return;
    }
    if (!contact.isGroup) {
        if (blockedContactsSet.has(contact.uid)) {
            showToast('Contato Bloqueado', 'Você bloqueou este contato. Desbloqueie para fazer chamadas.', 'red');
            return;
        }
        if (isBlockedByActiveContact) {
            showToast('Bloqueado', 'Você foi bloqueado por este contato e não pode realizar chamadas.', 'red');
            return;
        }
    }

    const modal = document.getElementById('call-type-modal');
    if (!modal) {
        startCall(true);
        return;
    }

    const nameEl = document.getElementById('call-type-contact-name');
    const avatarEl = document.getElementById('call-type-avatar');
    const statusEl = document.getElementById('call-type-contact-status');

    const contactName = contact.name || 'Contato';
    if (nameEl) nameEl.innerText = contactName;
    if (avatarEl) {
        if (contact.avatar) {
            avatarEl.style.backgroundImage = `url('${contact.avatar}')`;
            avatarEl.innerText = '';
        } else {
            avatarEl.style.backgroundImage = '';
            avatarEl.innerText = contactName.charAt(0).toUpperCase();
        }
    }
    if (statusEl) {
        statusEl.innerText = contact.status || 'Disponível no VORTEX ⚡';
    }

    modal.style.display = 'flex';
    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    playSound(clickSound);
    if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons();
}

export function closeCallTypeModal() {
    const modal = document.getElementById('call-type-modal');
    if (modal) {
        modal.style.display = 'none';
        modal.classList.remove('active');
        modal.setAttribute('aria-hidden', 'true');
    }
}

