export function applyInputValidationFeedback(input, res) {
    if (!input) return;
    if (res.isEmpty) {
        input.classList.remove('input-valid', 'input-invalid');
        input.style.borderColor = '';
        input.style.boxShadow = '';
        input.style.color = '';
        if (typeof input.setCustomValidity === 'function') input.setCustomValidity('');
    } else if (res.isValid) {
        input.classList.add('input-valid');
        input.classList.remove('input-invalid');
        input.style.borderColor = '#34c759';
        input.style.boxShadow = '0 0 10px rgba(52, 199, 89, 0.35)';
        input.style.color = '#34c759';
        if (typeof input.setCustomValidity === 'function') input.setCustomValidity('');
    } else {
        input.classList.add('input-invalid');
        input.classList.remove('input-valid');
        input.style.borderColor = '#ff3b30';
        input.style.boxShadow = '0 0 10px rgba(255, 59, 48, 0.35)';
        input.style.color = '#ff6b6b';
        if (typeof input.setCustomValidity === 'function' && res.error) {
            input.setCustomValidity(res.error);
        }
    }
}

export function isValidCPF(cpf) {
    if (!cpf) return false;
    const clean = String(cpf).replace(/\D/g, '');
    if (clean.length !== 11) return false;
    if (/^(\d)\1{10}$/.test(clean)) return false;
    let sum = 0;
    for (let i = 0; i < 9; i++) sum += parseInt(clean.charAt(i), 10) * (10 - i);
    let rev = 11 - (sum % 11);
    if (rev === 10 || rev === 11) rev = 0;
    if (rev !== parseInt(clean.charAt(9), 10)) return false;
    sum = 0;
    for (let i = 0; i < 10; i++) sum += parseInt(clean.charAt(i), 10) * (11 - i);
    rev = 11 - (sum % 11);
    if (rev === 10 || rev === 11) rev = 0;
    return rev === parseInt(clean.charAt(10), 10);
}

export function isValidCNPJ(cnpj) {
    if (!cnpj) return false;
    const clean = String(cnpj).replace(/\D/g, '');
    if (clean.length !== 14) return false;
    if (/^(\d)\1{13}$/.test(clean)) return false;
    let size = clean.length - 2;
    let numbers = clean.substring(0, size);
    const digits = clean.substring(size);
    let sum = 0;
    let pos = size - 7;
    for (let i = size; i >= 1; i--) {
        sum += parseInt(numbers.charAt(size - i), 10) * pos--;
        if (pos < 2) pos = 9;
    }
    let result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
    if (result !== parseInt(digits.charAt(0), 10)) return false;
    size = size + 1;
    numbers = clean.substring(0, size);
    sum = 0;
    pos = size - 7;
    for (let i = size; i >= 1; i--) {
        sum += parseInt(numbers.charAt(size - i), 10) * pos--;
        if (pos < 2) pos = 9;
    }
    result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
    return result === parseInt(digits.charAt(1), 10);
}

export function validatePixKey(rawKey) {
    if (!rawKey || typeof rawKey !== 'string') {
        return { isValid: false, isEmpty: true, type: null, formatted: '', error: null };
    }
    const val = rawKey.trim();
    if (!val) {
        return { isValid: false, isEmpty: true, type: null, formatted: '', error: null };
    }

    // 1. E-mail: padrão com @ e domínio válido
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/i;
    if (emailRegex.test(val)) {
        return { isValid: true, isEmpty: false, type: 'email', formatted: val.toLowerCase(), error: null };
    }

    // 2. Chave Aleatória (EVP / UUID v4 gerado no banco do usuário): 8-4-4-4-12 hexadecimais ou 32 hex contínuos
    const uuidHyphenRegex = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
    const uuidCompactRegex = /^[0-9a-fA-F]{32}$/;
    if (uuidHyphenRegex.test(val)) {
        return { isValid: true, isEmpty: false, type: 'random', formatted: val.toLowerCase(), error: null };
    }
    if (uuidCompactRegex.test(val)) {
        const v = val.toLowerCase();
        const formattedUuid = `${v.slice(0, 8)}-${v.slice(8, 12)}-${v.slice(12, 16)}-${v.slice(16, 20)}-${v.slice(20)}`;
        return { isValid: true, isEmpty: false, type: 'random', formatted: formattedUuid, error: null };
    }

    // 3. Dígitos Numéricos (CPF, CNPJ, Celular)
    const digitsOnly = val.replace(/\D/g, '');

    // 3a. CPF (11 dígitos): validação matemática dos dígitos verificadores
    if (digitsOnly.length === 11 && isValidCPF(digitsOnly)) {
        const formattedCpf = digitsOnly.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
        return { isValid: true, isEmpty: false, type: 'cpf', formatted: formattedCpf, error: null };
    }

    // 3b. CNPJ (14 dígitos): validação matemática dos dígitos verificadores
    if (digitsOnly.length === 14 && isValidCNPJ(digitsOnly)) {
        const formattedCnpj = digitsOnly.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, '$1.$2.$3/$4-$5');
        return { isValid: true, isEmpty: false, type: 'cnpj', formatted: formattedCnpj, error: null };
    }

    // 3c. Celular / Telefone Brasileiro
    let phoneDigits = digitsOnly;
    if (val.startsWith('+55') || (phoneDigits.startsWith('55') && (phoneDigits.length === 12 || phoneDigits.length === 13))) {
        phoneDigits = phoneDigits.slice(2);
    }
    if (phoneDigits.length === 11 || phoneDigits.length === 10) {
        const ddd = parseInt(phoneDigits.slice(0, 2), 10);
        if (ddd >= 11 && ddd <= 99) {
            if (phoneDigits.length === 11 && phoneDigits[2] === '9') {
                return { isValid: true, isEmpty: false, type: 'phone', formatted: `+55${phoneDigits}`, error: null };
            }
            if (phoneDigits.length === 10) {
                return { isValid: true, isEmpty: false, type: 'phone', formatted: `+55${phoneDigits}`, error: null };
            }
        }
    }

    // Não atende a nenhuma modalidade aceita pelo Banco Central
    return {
        isValid: false,
        isEmpty: false,
        type: null,
        formatted: val,
        error: 'Chave Pix inválida. Digite E-mail, Celular, CPF, CNPJ ou Chave Aleatória criada no seu banco.'
    };
}

export function formatAndValidateProfilePix(input) {
    if (!input) return;
    const res = validatePixKey(input.value);
    applyInputValidationFeedback(input, res);
    return res;
}

const profilePixInput = document.getElementById('profile-pix-input');
profilePixInput?.addEventListener('input', () => {
    formatAndValidateProfilePix(profilePixInput);
});
profilePixInput?.addEventListener('blur', () => {
    formatAndValidateProfilePix(profilePixInput);
});
profilePixInput?.addEventListener('paste', () => {
    setTimeout(() => {
        formatAndValidateProfilePix(profilePixInput);
    }, 0);
});

const profileStatusInput = document.getElementById('profile-status-input');
profileStatusInput?.addEventListener('input', () => {
    if (profileStatusInput.value.length > 45) {
        profileStatusInput.value = profileStatusInput.value.slice(0, 45);
    }
});

export function safeParseURL(candidate) {
    if (!candidate || typeof candidate !== 'string') return null;
    try {
        if (typeof URL === 'function' && URL.prototype && URL.prototype.constructor) {
            return new URL(candidate);
        }
    } catch (e) {}

    const m = candidate.match(/^(https?:\/\/)?([^\/\s:]+)(?::\d+)?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);
    if (!m) return null;
    const rawProto = (m[1] || 'https:').toLowerCase().replace(/\/\/$/, '');
    const protocol = rawProto.endsWith(':') ? rawProto : rawProto + ':';
    const hostname = (m[2] || '').toLowerCase();
    const pathname = m[3] || '/';
    const search = m[4] || '';
    return {
        protocol,
        hostname,
        pathname,
        search,
        searchParams: {
            has: (k) => new RegExp('[?&]' + k + '(?:=([^&#]*))?').test(search),
            get: (k) => {
                const match = search.match(new RegExp('[?&]' + k + '=([^&#]*)'));
                return match ? decodeURIComponent(match[1]) : null;
            }
        },
        href: candidate
    };
}

export function validateProfileLink(network, rawVal) {
    if (!rawVal || typeof rawVal !== 'string') {
        return { isValid: false, isEmpty: true, formatted: '', error: '' };
    }
    const val = rawVal.trim();
    if (!val) {
        return { isValid: false, isEmpty: true, formatted: '', error: '' };
    }

    const lower = val.toLowerCase();

    // Identificar se colocou link de outra rede social
    const isOtherSocialNetwork = (urlStr, currentNet) => {
        const patterns = {
            youtube: [/youtube\.com/i, /youtu\.be/i],
            instagram: [/instagram\.com/i],
            tiktok: [/tiktok\.com/i],
            facebook: [/facebook\.com/i, /fb\.com/i, /fb\.watch/i],
            whatsapp: [/wa\.me/i, /whatsapp\.com/i]
        };
        for (const [net, regexes] of Object.entries(patterns)) {
            if (net !== currentNet && regexes.some(r => r.test(urlStr))) {
                return net;
            }
        }
        return null;
    };

    if (network === 'youtube') {
        const otherNet = isOtherSocialNetwork(val, 'youtube');
        if (otherNet) {
            const netNames = { instagram: 'Instagram', tiktok: 'TikTok', facebook: 'Facebook', whatsapp: 'WhatsApp' };
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: `Link incorreto! Você colocou um link do ${netNames[otherNet] || otherNet} no campo do YouTube.`
            };
        }

        // Bloquear vídeos, shorts, lives, embeds
        if (
            lower.includes('/watch') ||
            lower.includes('watch?v=') ||
            lower.includes('youtu.be/') ||
            lower.includes('/shorts/') ||
            lower.includes('/embed/') ||
            lower.includes('/live/')
        ) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Links de vídeos ou shorts do YouTube não são permitidos. Insira o link do seu canal ou perfil.'
            };
        }

        // Handle direto: @canal
        if (/^@[a-zA-Z0-9_.-]{3,30}$/.test(val)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.youtube.com/${val}`,
                error: ''
            };
        }

        // Nome simples de canal
        if (/^[a-zA-Z0-9_.-]{3,30}$/.test(val) && !val.includes('.') && !val.includes('/')) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.youtube.com/@${val}`,
                error: ''
            };
        }

        let urlCandidate = val;
        if (!urlCandidate.startsWith('http://') && !urlCandidate.startsWith('https://')) {
            if (urlCandidate.startsWith('youtube.com/') || urlCandidate.startsWith('www.youtube.com/')) {
                urlCandidate = 'https://' + urlCandidate;
            } else {
                return {
                    isValid: false,
                    isEmpty: false,
                    formatted: val,
                    error: 'Link do YouTube inválido. Use https://youtube.com/@seucanal ou @seucanal.'
                };
            }
        }

        const url = safeParseURL(urlCandidate);
        if (!url) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'URL do YouTube malformada.'
            };
        }
        const host = url.hostname.toLowerCase();
        if (host !== 'youtube.com' && host !== 'www.youtube.com' && host !== 'm.youtube.com') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'O link deve ser do canal do YouTube (youtube.com).'
            };
        }
        const path = url.pathname.replace(/\/$/, '');
        if (!path || path === '') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link incompleto. Insira o link completo do canal.'
            };
        }
        if (
            /^\/@[a-zA-Z0-9_.-]{3,30}$/.test(path) ||
            /^\/(channel|c|user)\/[a-zA-Z0-9_.-]{2,}$/.test(path) ||
            /^\/[a-zA-Z0-9_.-]{3,30}$/.test(path)
        ) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.youtube.com${path}`,
                error: ''
            };
        }
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            error: 'Link de canal do YouTube inválido.'
        };
    }

    if (network === 'instagram') {
        const otherNet = isOtherSocialNetwork(val, 'instagram');
        if (otherNet) {
            const netNames = { youtube: 'YouTube', tiktok: 'TikTok', facebook: 'Facebook', whatsapp: 'WhatsApp' };
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: `Link incorreto! Você colocou um link do ${netNames[otherNet] || otherNet} no campo do Instagram.`
            };
        }

        // Bloquear posts, reels, stories, tv
        if (
            lower.includes('/p/') ||
            lower.includes('/reel/') ||
            lower.includes('/reels/') ||
            lower.includes('/stories/') ||
            lower.includes('/tv/')
        ) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Links de publicações, reels ou stories não são permitidos. Insira apenas o perfil do Instagram.'
            };
        }

        // Handle: @usuario
        if (/^@[a-zA-Z0-9._]{1,30}$/.test(val)) {
            const user = val.slice(1);
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.instagram.com/${user}`,
                error: ''
            };
        }

        // Nome simples
        if (/^[a-zA-Z0-9._]{1,30}$/.test(val) && !val.includes('/')) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.instagram.com/${val}`,
                error: ''
            };
        }

        let urlCandidate = val;
        if (!urlCandidate.startsWith('http://') && !urlCandidate.startsWith('https://')) {
            if (urlCandidate.startsWith('instagram.com/') || urlCandidate.startsWith('www.instagram.com/')) {
                urlCandidate = 'https://' + urlCandidate;
            } else {
                return {
                    isValid: false,
                    isEmpty: false,
                    formatted: val,
                    error: 'Link do Instagram inválido. Use https://instagram.com/seuperfil ou @seuperfil.'
                };
            }
        }

        const url = safeParseURL(urlCandidate);
        if (!url) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'URL do Instagram malformada.'
            };
        }
        const host = url.hostname.toLowerCase();
        if (host !== 'instagram.com' && host !== 'www.instagram.com') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'O link deve ser do Instagram (instagram.com).'
            };
        }
        const pathParts = url.pathname.replace(/\/$/, '').split('/').filter(Boolean);
        if (pathParts.length !== 1) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link inválido. Insira apenas o link do perfil (ex: https://instagram.com/seuperfil).'
            };
        }
        const username = pathParts[0];
        if (['p', 'reel', 'reels', 'stories', 'tv', 'explore', 'direct'].includes(username.toLowerCase())) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Links de publicações ou seções do Instagram não são permitidos. Insira o perfil.'
            };
        }
        if (/^[a-zA-Z0-9._]{1,30}$/.test(username)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.instagram.com/${username}`,
                error: ''
            };
        }
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            error: 'Nome de usuário do Instagram inválido.'
        };
    }

    if (network === 'tiktok') {
        const otherNet = isOtherSocialNetwork(val, 'tiktok');
        if (otherNet) {
            const netNames = { youtube: 'YouTube', instagram: 'Instagram', facebook: 'Facebook', whatsapp: 'WhatsApp' };
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: `Link incorreto! Você colocou um link do ${netNames[otherNet] || otherNet} no campo do TikTok.`
            };
        }

        // Bloquear vídeos
        if (
            lower.includes('/video/') ||
            lower.includes('vm.tiktok.com') ||
            lower.includes('vt.tiktok.com')
        ) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Links de vídeos do TikTok não são permitidos. Insira apenas o perfil do TikTok.'
            };
        }

        // Handle: @usuario
        if (/^@[a-zA-Z0-9._]{1,30}$/.test(val)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.tiktok.com/${val}`,
                error: ''
            };
        }

        // Nome simples
        if (/^[a-zA-Z0-9._]{1,30}$/.test(val) && !val.includes('/')) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.tiktok.com/@${val}`,
                error: ''
            };
        }

        let urlCandidate = val;
        if (!urlCandidate.startsWith('http://') && !urlCandidate.startsWith('https://')) {
            if (urlCandidate.startsWith('tiktok.com/') || urlCandidate.startsWith('www.tiktok.com/')) {
                urlCandidate = 'https://' + urlCandidate;
            } else {
                return {
                    isValid: false,
                    isEmpty: false,
                    formatted: val,
                    error: 'Link do TikTok inválido. Use https://tiktok.com/@seuperfil ou @seuperfil.'
                };
            }
        }

        const url = safeParseURL(urlCandidate);
        if (!url) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'URL do TikTok malformada.'
            };
        }
        const host = url.hostname.toLowerCase();
        if (host !== 'tiktok.com' && host !== 'www.tiktok.com') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'O link deve ser do TikTok (tiktok.com).'
            };
        }
        const pathParts = url.pathname.replace(/\/$/, '').split('/').filter(Boolean);
        if (pathParts.length !== 1) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Insira apenas o link do perfil do TikTok.'
            };
        }
        let user = pathParts[0];
        if (!user.startsWith('@')) user = '@' + user;
        if (/^@[a-zA-Z0-9._]{1,30}$/.test(user)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.tiktok.com/${user}`,
                error: ''
            };
        }
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            error: 'Perfil do TikTok inválido.'
        };
    }

    if (network === 'facebook') {
        const otherNet = isOtherSocialNetwork(val, 'facebook');
        if (otherNet) {
            const netNames = { youtube: 'YouTube', instagram: 'Instagram', tiktok: 'TikTok', whatsapp: 'WhatsApp' };
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: `Link incorreto! Você colocou um link do ${netNames[otherNet] || otherNet} no campo do Facebook.`
            };
        }

        // Bloquear vídeos, reels, posts, fotos, stories
        if (
            lower.includes('/watch') ||
            lower.includes('/reel/') ||
            lower.includes('/reels/') ||
            lower.includes('/videos/') ||
            lower.includes('/posts/') ||
            lower.includes('/photo/') ||
            lower.includes('/photos/') ||
            lower.includes('/story.php')
        ) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Links de vídeos, reels ou publicações não são permitidos. Insira apenas a página ou perfil do Facebook.'
            };
        }

        // Handle: @pagina
        if (/^@[a-zA-Z0-9._-]{2,50}$/.test(val)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.facebook.com/${val.slice(1)}`,
                error: ''
            };
        }

        // Nome simples
        if (/^[a-zA-Z0-9._-]{2,50}$/.test(val) && !val.includes('/')) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://www.facebook.com/${val}`,
                error: ''
            };
        }

        let urlCandidate = val;
        if (!urlCandidate.startsWith('http://') && !urlCandidate.startsWith('https://')) {
            if (urlCandidate.startsWith('facebook.com/') || urlCandidate.startsWith('www.facebook.com/') || urlCandidate.startsWith('fb.com/')) {
                urlCandidate = 'https://' + urlCandidate;
            } else {
                return {
                    isValid: false,
                    isEmpty: false,
                    formatted: val,
                    error: 'Link do Facebook inválido. Use https://facebook.com/suapagina ou @suapagina.'
                };
            }
        }

        const url = safeParseURL(urlCandidate);
        if (!url) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'URL do Facebook malformada.'
            };
        }
        const host = url.hostname.toLowerCase();
        const validHosts = ['facebook.com', 'www.facebook.com', 'fb.com', 'www.fb.com', 'm.facebook.com'];
        if (!validHosts.includes(host)) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'O link deve ser do Facebook (facebook.com).'
            };
        }
        const path = url.pathname.replace(/\/$/, '');
        if (!path || path === '') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link incompleto. Insira o link da página ou perfil do Facebook.'
            };
        }
        const baseHost = (host === 'facebook.com') ? 'facebook.com' : 'www.facebook.com';
        if (path.includes('profile.php')) {
            if (url.searchParams && typeof url.searchParams.has === 'function' && url.searchParams.has('id')) {
                return {
                    isValid: true,
                    isEmpty: false,
                    formatted: `https://${baseHost}/profile.php?id=${url.searchParams.get('id')}`,
                    error: ''
                };
            }
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link de perfil do Facebook inválido.'
            };
        }
        if (/^\/(pages|pg)\/.+/.test(path) || /^\/[a-zA-Z0-9._-]{2,50}$/.test(path)) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://${baseHost}${path}`,
                error: ''
            };
        }
        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            error: 'Link do Facebook inválido.'
        };
    }

    if (network === 'whatsapp') {
        const otherNet = isOtherSocialNetwork(val, 'whatsapp');
        if (otherNet) {
            const netNames = { youtube: 'YouTube', instagram: 'Instagram', tiktok: 'TikTok', facebook: 'Facebook' };
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: `Link incorreto! Você colocou um link do ${netNames[otherNet] || otherNet} no campo do WhatsApp Comercial.`
            };
        }

        // WhatsApp Business Short Link: wa.me/message/XXXXXX ou https://wa.me/message/XXXXXX
        const bizMsgMatch = val.match(/wa\.me\/message\/([a-zA-Z0-9_-]{3,})/i) || val.match(/whatsapp\.com\/message\/([a-zA-Z0-9_-]{3,})/i);
        if (bizMsgMatch) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://wa.me/message/${bizMsgMatch[1]}`,
                error: ''
            };
        }

        // Link padrão wa.me/55...
        if (val.includes('wa.me/')) {
            const digits = val.replace(/\D/g, '');
            if (digits.length >= 10 && digits.length <= 15) {
                return {
                    isValid: true,
                    isEmpty: false,
                    formatted: `https://wa.me/${digits}`,
                    error: ''
                };
            }
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link wa.me inválido. Certifique-se de incluir o código do país e DDD.'
            };
        }

        // api.whatsapp.com
        if (val.includes('api.whatsapp.com')) {
            const digits = val.replace(/\D/g, '');
            if (digits.length >= 10 && digits.length <= 15) {
                return {
                    isValid: true,
                    isEmpty: false,
                    formatted: `https://api.whatsapp.com/send?phone=${digits}`,
                    error: ''
                };
            }
        }

        // Número direto com DDD
        const digits = val.replace(/\D/g, '');
        if (digits.length === 10 || digits.length === 11) {
            const ddd = parseInt(digits.slice(0, 2), 10);
            const VALID_DDDS = new Set([
                11, 12, 13, 14, 15, 16, 17, 18, 19,
                21, 22, 24, 27, 28,
                31, 32, 33, 34, 35, 37, 38,
                41, 42, 43, 44, 45, 46, 47, 48, 49,
                51, 53, 54, 55,
                61, 62, 63, 64, 65, 66, 67, 68, 69,
                71, 73, 74, 75, 77, 79,
                81, 82, 83, 84, 85, 86, 87, 88, 89,
                91, 92, 93, 94, 95, 96, 97, 98, 99
            ]);
            if (VALID_DDDS.has(ddd)) {
                return {
                    isValid: true,
                    isEmpty: false,
                    formatted: `https://wa.me/55${digits}`,
                    error: ''
                };
            }
        } else if ((digits.length === 12 || digits.length === 13) && digits.startsWith('55')) {
            return {
                isValid: true,
                isEmpty: false,
                formatted: `https://wa.me/${digits}`,
                error: ''
            };
        }

        return {
            isValid: false,
            isEmpty: false,
            formatted: val,
            error: 'Link ou número do WhatsApp inválido. Insira wa.me/message/..., wa.me/55... ou número com DDD.'
        };
    }

    if (network === 'website') {
        // "Eas 3 opções de links faça ele aceitar só link com https://"
        if (!lower.startsWith('https://')) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'O link do site deve começar obrigatoriamente com https://'
            };
        }

        const url = safeParseURL(val);
        if (!url) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Link de site inválido. Formato esperado: https://seusite.com'
            };
        }
        if (url.protocol !== 'https:') {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Apenas links seguros com https:// são aceitos.'
            };
        }
        const host = url.hostname.toLowerCase();
        if (!host.includes('.') || host.length < 4 || host.startsWith('.') || host.endsWith('.')) {
            return {
                isValid: false,
                isEmpty: false,
                formatted: val,
                error: 'Endereço de domínio inválido. Ex: https://seusite.com'
            };
        }
        const formattedHref = (url.href || val).replace(/\/$/, '');
        return {
            isValid: true,
            isEmpty: false,
            formatted: formattedHref,
            error: ''
        };
    }

    return { isValid: true, isEmpty: false, formatted: val, error: '' };
}

export function formatAndValidateProfileLink(network, input) {
    if (!input) return { isValid: false, isEmpty: true };
    const res = validateProfileLink(network, input.value);
    applyInputValidationFeedback(input, res);
    return res;
}

export const profileSocialLinkFields = [
    { id: 'profile-youtube-input', network: 'youtube', label: 'YouTube', reqBiz: false },
    { id: 'profile-instagram-input', network: 'instagram', label: 'Instagram', reqBiz: false },
    { id: 'profile-tiktok-input', network: 'tiktok', label: 'TikTok', reqBiz: false },
    { id: 'profile-whatsapp-input', network: 'whatsapp', label: 'WhatsApp Comercial', reqBiz: true },
    { id: 'profile-facebook-input', network: 'facebook', label: 'Facebook', reqBiz: true },
    { id: 'profile-website1-input', network: 'website', label: 'Site Oficial 1', reqBiz: true },
    { id: 'profile-website2-input', network: 'website', label: 'Site Oficial 2', reqBiz: true },
    { id: 'profile-website3-input', network: 'website', label: 'Site Oficial 3', reqBiz: true }
];

export function setupProfileLinkValidationListeners() {
    profileSocialLinkFields.forEach(({ id, network }) => {
        const input = document.getElementById(id);
        if (!input) return;
        const handler = () => {
            formatAndValidateProfileLink(network, input);
        };
        input.addEventListener('input', handler);
        input.addEventListener('blur', handler);
        input.addEventListener('paste', () => {
            setTimeout(handler, 0);
        });
    });

    document.getElementById('profile-type-business')?.addEventListener('change', () => {
        profileSocialLinkFields.filter(f => f.reqBiz).forEach(({ id, network }) => {
            const input = document.getElementById(id);
            if (input) formatAndValidateProfileLink(network, input);
        });
    });
}

document.getElementById('contact-profile-copy-phone-btn')?.addEventListener('click', () => {
    const phone = document.getElementById('contact-profile-phone-text')?.innerText?.trim();
    if (phone) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(phone);
        }
        showToast('Telefone Copiado', 'Número copiado para a área de transferência!', 'green');
    }
});

document.getElementById('contact-profile-call-phone-btn')?.addEventListener('click', () => {
    const phone = document.getElementById('contact-profile-phone-text')?.innerText?.trim();
    if (phone) {
        const raw = phone.replace(/\D/g, '');
        window.open(`https://wa.me/55${raw.replace(/^55/, '')}`, '_blank');
    }
});

const copyPixKeyToClipboard = () => {
    const pixKey = document.getElementById('contact-profile-pix-text')?.innerText?.trim() || activeContactProfileData?.pixKey;
    if (pixKey) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(pixKey);
        }
        showToast('Chave Pix Copiada! ⚡', 'Chave copiada para a área de transferência.', 'green');
    }
};
document.getElementById('contact-profile-copy-pix-btn')?.addEventListener('click', copyPixKeyToClipboard);
document.getElementById('contact-profile-pix-pill')?.addEventListener('click', copyPixKeyToClipboard);

document.getElementById('save-profile-btn')?.addEventListener('click', async () => {
    if (!currentUser) return;
    const rawName = document.getElementById('profile-name-input')?.value.trim() || 'Usuário';
    const rawSurname = document.getElementById('profile-lastname-input')?.value.trim() || '';

    if (rawName.length > 15) {
        showToast('Nome muito longo', 'O Nome pode ter no máximo 15 caracteres.', 'red');
        return;
    }
    if (rawSurname.length > 15) {
        showToast('Sobrenome muito longo', 'O Sobrenome pode ter no máximo 15 caracteres.', 'red');
        return;
    }

    const name = rawName.slice(0, 15);
    const surname = rawSurname.slice(0, 15);
    const usernameInputValue = profileUsernameInput?.value.trim() || '';
    const rawBio = document.getElementById('profile-status-input')?.value.trim() || 'Online';
    if (rawBio.length > 45) {
        showToast('Recado / Bio muito longo', 'O Recado / Bio pode ter no máximo 45 caracteres.', 'red');
        document.getElementById('profile-status-input')?.focus();
        return;
    }
    const bio = rawBio.slice(0, 45);
    const rawPhone = document.getElementById('profile-phone-input')?.value.trim() || '';
    let phone = '';
    if (rawPhone) {
        const phoneValidation = validateBrazilianPhone(rawPhone);
        if (!phoneValidation.isValid) {
            showToast('Telefone inválido', 'Por favor, insira um número de telefone válido com DDD (ex: (11) 99999-9999).', 'red');
            document.getElementById('profile-phone-input')?.focus();
            return;
        }
        phone = phoneValidation.formatted;
    }
    const rawPixKey = document.getElementById('profile-pix-input')?.value.trim() || '';
    let pixKey = '';
    if (rawPixKey) {
        const pixValidation = validatePixKey(rawPixKey);
        const pixInp = document.getElementById('profile-pix-input');
        if (pixInp) applyInputValidationFeedback(pixInp, pixValidation);
        if (!pixValidation.isValid) {
            showToast('Chave Pix Inválida ⚠️', pixValidation.error || 'Por favor, insira uma chave Pix válida (E-mail, Celular, CPF, CNPJ ou Chave Aleatória).', 'red');
            pixInp?.focus();
            return;
        }
        pixKey = rawPixKey;
    }
    const rawYoutube = document.getElementById('profile-youtube-input')?.value.trim() || '';
    const rawInstagram = document.getElementById('profile-instagram-input')?.value.trim() || '';
    const rawTiktok = document.getElementById('profile-tiktok-input')?.value.trim() || '';

    const isBusiness = document.getElementById('profile-type-business')?.checked || false;
    const accountType = isBusiness ? 'business' : 'personal';

    const rawWhatsapp = document.getElementById('profile-whatsapp-input')?.value.trim() || '';
    const rawFacebook = document.getElementById('profile-facebook-input')?.value.trim() || '';
    const rawWebsite1 = document.getElementById('profile-website1-input')?.value.trim() || '';
    const rawWebsite1Title = document.getElementById('profile-website1-title-input')?.value.trim() || '';
    const rawWebsite2 = document.getElementById('profile-website2-input')?.value.trim() || '';
    const rawWebsite2Title = document.getElementById('profile-website2-title-input')?.value.trim() || '';
    const rawWebsite3 = document.getElementById('profile-website3-input')?.value.trim() || '';
    const rawWebsite3Title = document.getElementById('profile-website3-title-input')?.value.trim() || '';

    // Validação estrita de Redes Sociais e Sites Oficiais
    let youtube = '';
    let instagram = '';
    let tiktok = '';
    let whatsapp = '';
    let facebook = '';
    let website1 = '';
    let website2 = '';
    let website3 = '';

    for (const item of profileSocialLinkFields) {
        if (item.reqBiz && !isBusiness) continue;
        const input = document.getElementById(item.id);
        const rawVal = input?.value?.trim() || '';
        if (rawVal) {
            const vRes = validateProfileLink(item.network, rawVal);
            applyInputValidationFeedback(input, vRes);
            if (!vRes.isValid) {
                showToast(`Link de ${item.label} inválido`, vRes.error || `Por favor, insira um link válido para ${item.label}.`, 'red');
                input?.focus();
                return;
            }
            if (item.network === 'youtube') youtube = vRes.formatted;
            if (item.network === 'instagram') instagram = vRes.formatted;
            if (item.network === 'tiktok') tiktok = vRes.formatted;
            if (item.network === 'whatsapp') whatsapp = vRes.formatted;
            if (item.network === 'facebook') facebook = vRes.formatted;
            if (item.id === 'profile-website1-input') website1 = vRes.formatted;
            if (item.id === 'profile-website2-input') website2 = vRes.formatted;
            if (item.id === 'profile-website3-input') website3 = vRes.formatted;
        }
    }

    const website1Title = rawWebsite1Title.slice(0, 30);
    const website2Title = rawWebsite2Title.slice(0, 30);
    const website3Title = rawWebsite3Title.slice(0, 30);

    const usernameKey = normalizeUsername(usernameInputValue);
    const usernameError = usernameValidationMessage(usernameKey);

    if (usernameError) {
        profileUsernameInput?.setCustomValidity(usernameError);
        profileUsernameInput?.reportValidity();
        showToast('Username inválido', usernameError, 'red');
        return;
    }

    const username = `@${usernameKey}`;
    const oldUsernameKey = normalizeUsername(currentProfile.username || '');
    const newUsernameRef = doc(db, 'usernames', usernameKey);
    const oldUsernameRef = oldUsernameKey ? doc(db, 'usernames', oldUsernameKey) : null;
    const userRef = doc(db, 'users', currentUser.uid);

    try {
        const existingUsersSnap = await getDocs(query(
            collection(db, 'users'),
            where('username', '==', username)
        ));
        const usernameUsedByAnotherUser = existingUsersSnap.docs.some(userDoc => userDoc.id !== currentUser.uid);
        if (usernameUsedByAnotherUser) {
            showToast('Username indisponível', 'Esse nome de usuário já está em uso.', 'red');
            return;
        }

        await runTransaction(db, async (transaction) => {
            const usernameSnap = await transaction.get(newUsernameRef);
            if (usernameSnap.exists() && usernameSnap.data().uid !== currentUser.uid) {
                throw new Error('USERNAME_TAKEN');
            }

            if (oldUsernameRef && oldUsernameKey !== usernameKey) {
                const oldUsernameSnap = await transaction.get(oldUsernameRef);
                if (oldUsernameSnap.exists() && oldUsernameSnap.data().uid === currentUser.uid) {
                    transaction.delete(oldUsernameRef);
                }
            }

            transaction.set(newUsernameRef, {
                uid: currentUser.uid,
                username,
                updatedAt: Date.now()
            });

            const userUpdatePayload = {
                name,
                surname,
                username,
                status: bio,
                phone,
                pixKey,
                accountType,
                whatsapp,
                facebook,
                website1,
                website1Title,
                website2,
                website2Title,
                website3,
                website3Title,
                youtube,
                instagram,
                tiktok,
                socialLinks: {
                    youtube,
                    instagram,
                    tiktok,
                    whatsapp,
                    facebook,
                    website1,
                    website1Title,
                    website2,
                    website2Title,
                    website3,
                    website3Title
                }
            };
            if (currentProfile.avatar !== undefined) {
                userUpdatePayload.avatar = currentProfile.avatar;
            }
            transaction.set(userRef, userUpdatePayload, { merge: true });
        });
    } catch (error) {
        if (error.message === 'USERNAME_TAKEN') {
            showToast('Username indisponível', 'Esse nome de usuário já está em uso.', 'red');
        } else {
            console.error('Erro ao salvar username:', error);
            showToast('Erro', 'Não foi possível salvar o nome de usuário.', 'red');
        }
        return;
    }

    currentProfile.name = name;
    currentProfile.surname = surname;
    currentProfile.username = username;
    currentProfile.status = bio;
    currentProfile.phone = phone;
    currentProfile.pixKey = pixKey;
    currentProfile.accountType = accountType;
    currentProfile.whatsapp = whatsapp;
    currentProfile.facebook = facebook;
    currentProfile.website1 = website1;
    currentProfile.website1Title = website1Title;
    currentProfile.website2 = website2;
    currentProfile.website2Title = website2Title;
    currentProfile.website3 = website3;
    currentProfile.website3Title = website3Title;
    currentProfile.youtube = youtube;
    currentProfile.instagram = instagram;
    currentProfile.tiktok = tiktok;
    currentProfile.socialLinks = {
        youtube,
        instagram,
        tiktok,
        whatsapp,
        facebook,
        website1,
        website1Title,
        website2,
        website2Title,
        website3,
        website3Title
    };
    updateProfileDOM();
    if (currentUser && currentUser.uid && currentProfile.avatar) {
        updateAuthorAvatarsInDOM(currentUser.uid, currentProfile.avatar);
        syncUserAvatarToPostsAndStories(currentUser.uid, currentProfile.avatar);
    }
    showToast("Perfil Salvo", "Dados atualizados com sucesso!", "green");
    document.getElementById('profile-edit-panel')?.classList.remove('active');
});

export async function compressImage(file, maxSize = 512, quality = 0.75) {
    return new Promise((resolve) => {
        if (!file) return resolve('');
        if (typeof file === 'string') return resolve(file);
        if (typeof FileReader === 'undefined') return resolve('');

        const reader = new FileReader();
        reader.onerror = () => resolve('');
        reader.onload = (e) => {
            const resultDataUrl = e.target.result;
            if (typeof Image === 'undefined' || typeof document === 'undefined' || typeof document.createElement !== 'function') {
                return resolve(resultDataUrl);
            }
            try {
                const img = new Image();
                img.onerror = () => resolve(resultDataUrl);
                img.onload = () => {
                    try {
                        let width = img.width || maxSize;
                        let height = img.height || maxSize;
                        if (width > height) {
                            if (width > maxSize) {
                                height = Math.round((height * maxSize) / width);
                                width = maxSize;
                            }
                        } else {
                            if (height > maxSize) {
                                width = Math.round((width * maxSize) / height);
                                height = maxSize;
                            }
                        }
                        const canvas = document.createElement('canvas');
                        canvas.width = width;
                        canvas.height = height;
                        const ctx = canvas.getContext ? canvas.getContext('2d') : null;
                        if (!ctx || typeof canvas.toDataURL !== 'function') {
                            return resolve(resultDataUrl);
                        }
                        ctx.drawImage(img, 0, 0, width, height);
                        const compressedDataUrl = canvas.toDataURL('image/jpeg', quality);
                        resolve(compressedDataUrl || resultDataUrl);
                    } catch (err) {
                        resolve(resultDataUrl);
                    }
                };
                img.src = resultDataUrl;
            } catch (err) {
                resolve(resultDataUrl);
            }
        };
        reader.readAsDataURL(file);
    });
}

export async function syncUserAvatarToPostsAndStories(uid, avatarDataUrl) {
    if (!uid || !avatarDataUrl || typeof collection !== 'function' || typeof query !== 'function' || typeof where !== 'function' || typeof getDocs !== 'function' || typeof db === 'undefined') return;
    try {
        const postsSnap = await getDocs(query(collection(db, 'posts'), where('authorUid', '==', uid)));
        if (postsSnap && typeof postsSnap.forEach === 'function') {
            postsSnap.forEach(pDoc => {
                if (pDoc && pDoc.ref) {
                    updateDoc(pDoc.ref, { authorAvatar: avatarDataUrl }).catch(() => {});
                }
            });
        }
    } catch (e) {
        // Silencioso
    }
    try {
        const storiesSnap = await getDocs(query(collection(db, 'stories'), where('authorUid', '==', uid)));
        if (storiesSnap && typeof storiesSnap.forEach === 'function') {
            storiesSnap.forEach(sDoc => {
                if (sDoc && sDoc.ref) {
                    updateDoc(sDoc.ref, { authorAvatar: avatarDataUrl }).catch(() => {});
                }
            });
        }
    } catch (e) {
        // Silencioso
    }
}

export async function updateProfileAvatar(avatarDataUrl) {
    if (!avatarDataUrl) return;
    currentProfile.avatar = avatarDataUrl;

    const prev = document.getElementById('profile-edit-avatar-preview');
    if (prev) prev.style.backgroundImage = `url('${avatarDataUrl}')`;
    const userAvatar = document.getElementById('user-avatar-display');
    if (userAvatar) userAvatar.style.backgroundImage = `url('${avatarDataUrl}')`;

    if (currentUser && currentUser.uid) {
        updateAuthorAvatarsInDOM(currentUser.uid, avatarDataUrl);
        try {
            await updateDoc(doc(db, 'users', currentUser.uid), {
                avatar: avatarDataUrl,
                updatedAt: Date.now()
            });
            syncUserAvatarToPostsAndStories(currentUser.uid, avatarDataUrl);
            showToast('Foto atualizada', 'Sua foto de perfil foi salva!', 'green');
        } catch (err) {
            console.error('Erro ao salvar foto de perfil no Firestore:', err);
            showToast('Aviso', 'Foto aplicada localmente. Salve o perfil para confirmar.', 'blue');
        }
    }
}

