export let userFavoriteTracks = [];
let userFavoriteTracksUnsubscribe = null;

export function isTrackFavorited(trackId) {
    if (!trackId) return false;
    return userFavoriteTracks.some(t => String(t.id) === String(trackId));
}

export function getUserFavoriteTracks() {
    return userFavoriteTracks;
}

export function setUserFavoriteTracks(tracks = []) {
    userFavoriteTracks = Array.isArray(tracks) ? tracks : [];
}

export async function loadUserFavoriteTracks() {
    if (userFavoriteTracksUnsubscribe) {
        userFavoriteTracksUnsubscribe();
        userFavoriteTracksUnsubscribe = null;
    }

    if (!currentUser) {
        userFavoriteTracks = [];
        return;
    }

    try {
        const local = localStorage.getItem(`vortex_fav_tracks_${currentUser.uid}`);
        if (local) {
            const parsed = JSON.parse(local);
            if (Array.isArray(parsed)) {
                userFavoriteTracks = parsed;
            }
        }
    } catch (e) {}

    try {
        if (typeof collection === 'function' && typeof onSnapshot === 'function' && typeof db !== 'undefined') {
            const favColRef = collection(db, 'users', currentUser.uid, 'favorite_tracks');
            userFavoriteTracksUnsubscribe = onSnapshot(favColRef, (snapshot) => {
                if (snapshot && Array.isArray(snapshot.docs)) {
                    const tracks = snapshot.docs.map(docSnap => ({
                        id: docSnap.id,
                        ...docSnap.data()
                    })).sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
                    userFavoriteTracks = tracks;
                    try {
                        localStorage.setItem(`vortex_fav_tracks_${currentUser.uid}`, JSON.stringify(tracks));
                    } catch (e) {}
                    updateFavoriteIconsUI();
                }
            }, (error) => {
                console.warn('Erro ao sincronizar favoritas do Firestore:', error);
            });
        }
    } catch (err) {
        console.warn('Erro ao configurar listener de favoritas:', err);
    }
}

export async function toggleFavoriteTrack(track) {
    if (!track || !track.id) return;
    if (!currentUser) {
        showToast('Login necessário', 'Entre na sua conta para salvar músicas favoritas.', 'red');
        return;
    }

    const trackId = String(track.id);
    const existingIndex = userFavoriteTracks.findIndex(t => String(t.id) === trackId);
    const isAdding = existingIndex === -1;

    if (isAdding) {
        const newFav = {
            id: trackId,
            title: track.title || 'Música',
            artist: track.artist || 'Artista',
            cover: track.cover || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&h=300&fit=crop',
            audioUrl: track.audioUrl || '',
            duration: track.duration || 30,
            savedAt: Date.now()
        };
        userFavoriteTracks.unshift(newFav);
        try {
            localStorage.setItem(`vortex_fav_tracks_${currentUser.uid}`, JSON.stringify(userFavoriteTracks));
        } catch (e) {}
        showToast('Favoritos ❤️', `"${newFav.title}" salva nas suas favoritas!`, 'green');

        try {
            if (typeof setDoc === 'function' && typeof doc === 'function' && typeof db !== 'undefined') {
                await setDoc(doc(db, 'users', currentUser.uid, 'favorite_tracks', trackId), newFav);
            }
        } catch (err) {
            console.warn('Erro ao salvar favorita no Firestore:', err);
        }
    } else {
        const removed = userFavoriteTracks.splice(existingIndex, 1)[0];
        try {
            localStorage.setItem(`vortex_fav_tracks_${currentUser.uid}`, JSON.stringify(userFavoriteTracks));
        } catch (e) {}
        showToast('Favoritos', `"${removed?.title || 'Música'}" removida dos favoritos.`, 'yellow');

        try {
            if (typeof deleteDoc === 'function' && typeof doc === 'function' && typeof db !== 'undefined') {
                await deleteDoc(doc(db, 'users', currentUser.uid, 'favorite_tracks', trackId));
            }
        } catch (err) {
            console.warn('Erro ao excluir favorita no Firestore:', err);
        }
    }

    updateFavoriteIconsUI();

    if (activeMusicGenre === 'favorites') {
        const searchInput = document.getElementById('music-search-input');
        loadMusicPickerResults(searchInput?.value || '', 'favorites');
    } else if (activeMusicGenre === 'for-you') {
        const searchInput = document.getElementById('music-search-input');
        loadMusicPickerResults(searchInput?.value || '', 'for-you');
    }
}

export function updateFavoriteIconsUI() {
    document.querySelectorAll('.track-fav-btn').forEach(btn => {
        const tid = btn.dataset.trackId;
        const isFav = isTrackFavorited(tid);
        btn.classList.toggle('favorited', isFav);
        btn.title = isFav ? 'Remover dos favoritos' : 'Salvar nos favoritos';
        const icon = btn.querySelector('i, svg');
        if (icon) {
            icon.classList.toggle('filled', isFav);
        }
    });
}

// Algoritmo de recomendação inteligente de músicas estilo Instagram
export async function getRecommendedTracks(query = '') {
    const q = (query || '').trim().toLowerCase();

    // Se o usuário digitou uma busca dentro de 'Para Você', busca diretamente
    if (q) {
        return searchMusicTracks(q, '');
    }

    // Se o usuário já favoritou músicas, analisa o gosto musical e recomenda
    if (userFavoriteTracks && userFavoriteTracks.length > 0) {
        try {
            // 1. Artistas favoritos únicos mais recentes (até 3)
            const favArtists = [...new Set(userFavoriteTracks.map(t => t.artist?.trim()).filter(Boolean))].slice(0, 3);

            // 2. Gêneros musicais detectados nos títulos e artistas favoritados
            const GENRE_KEYWORDS = [
                'sertanejo', 'funk', 'pop', 'trap', 'rap', 'hip hop', 'rock', 'lofi', 'lo-fi',
                'eletronica', 'electronic', 'pagode', 'forro', 'forró', 'gospel', 'reggae',
                'mpb', 'dance', 'acoustic', 'anime', 'kpop', 'piseiro', 'axe', 'drill', 'r&b'
            ];
            const detectedGenres = [];
            userFavoriteTracks.forEach(t => {
                const combined = `${t.title || ''} ${t.artist || ''}`.toLowerCase();
                GENRE_KEYWORDS.forEach(kw => {
                    if (combined.includes(kw) && !detectedGenres.includes(kw)) {
                        detectedGenres.push(kw);
                    }
                });
            });

            // 3. Montar buscas paralelas para compor o feed 'Para Você'
            const searchPromises = [];

            // Músicas dos artistas favoritos
            favArtists.forEach(artist => {
                const url = `https://itunes.apple.com/search?term=${encodeURIComponent(artist)}&media=music&entity=song&limit=10`;
                searchPromises.push(
                    fetch(url)
                        .then(r => r.ok ? r.json() : { results: [] })
                        .then(data => (data.results || []).filter(item => item.previewUrl))
                        .catch(() => [])
                );
            });

            // Se detectou algum estilo específico (ex: funk, sertanejo, trap)
            if (detectedGenres.length > 0) {
                const topGenre = detectedGenres[0];
                const genreUrl = `https://itunes.apple.com/search?term=${encodeURIComponent(topGenre + ' hits')}&media=music&entity=song&limit=10`;
                searchPromises.push(
                    fetch(genreUrl)
                        .then(r => r.ok ? r.json() : { results: [] })
                        .then(data => (data.results || []).filter(item => item.previewUrl))
                        .catch(() => [])
                );
            }

            // Hits recomendados gerais para dar variedade
            const trendingUrl = `https://itunes.apple.com/search?term=brasil+hits&media=music&entity=song&limit=10`;
            searchPromises.push(
                fetch(trendingUrl)
                    .then(r => r.ok ? r.json() : { results: [] })
                    .then(data => (data.results || []).filter(item => item.previewUrl))
                    .catch(() => [])
            );

            const resultsArrays = await Promise.all(searchPromises);
            const rawTracks = resultsArrays.flat();

            if (rawTracks.length > 0) {
                const seenIds = new Set();
                const recommended = [];

                rawTracks.forEach(item => {
                    const id = String(item.trackId || Math.random());
                    if (seenIds.has(id)) return;
                    seenIds.add(id);

                    recommended.push({
                        id,
                        title: item.trackName || 'Música',
                        artist: item.artistName || 'Artista',
                        cover: item.artworkUrl100 ? item.artworkUrl100.replace('100x100bb', '300x300bb') : 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&h=300&fit=crop',
                        audioUrl: item.previewUrl,
                        duration: 30, // Preview oficial do catálogo da Apple é de 30s
                        actualDuration: 30,
                        fullDuration: item.trackTimeMillis ? Math.round(item.trackTimeMillis / 1000) : 30,
                        isApplePreview: true,
                        isRecommended: true
                    });
                });

                // Prioriza faixas não favoritadas para descoberta (estilo Instagram) e embaralha levemente
                recommended.sort((a, b) => {
                    const aFav = isTrackFavorited(a.id) ? 1 : 0;
                    const bFav = isTrackFavorited(b.id) ? 1 : 0;
                    return aFav - bFav;
                });

                return recommended.slice(0, 30);
            }
        } catch (err) {
            console.warn('Erro ao gerar recomendações de música personalizadas:', err);
        }
    }

    // Fallback: se ainda não houver favoritos, recomenda os maiores sucessos
    const defaultHits = await searchMusicTracks('', 'trending');
    return defaultHits.map(t => ({ ...t, isRecommended: true }));
}

export async function searchMusicTracks(query = '', genre = '') {
    const q = (query || '').trim().toLowerCase();
    const g = (genre || '').trim();

    if (g === 'favorites') {
        if (q) {
            return userFavoriteTracks.filter(t =>
                (t.title && t.title.toLowerCase().includes(q)) ||
                (t.artist && t.artist.toLowerCase().includes(q))
            );
        }
        return [...userFavoriteTracks];
    }

    if (g === 'for-you') {
        return getRecommendedTracks(q);
    }

    const searchTerm = q || (g && g !== 'trending' ? `${g} hits` : 'top hits');

    try {
        const itunesUrl = `https://itunes.apple.com/search?term=${encodeURIComponent(searchTerm)}&media=music&entity=song&limit=25`;
        const res = await fetch(itunesUrl);
        if (res.ok) {
            const data = await res.json();
            if (data.results && Array.isArray(data.results) && data.results.length > 0) {
                const tracks = data.results
                    .filter(item => item.previewUrl)
                    .map(item => ({
                        id: String(item.trackId || Math.random()),
                        title: item.trackName || 'Música',
                        artist: item.artistName || 'Artista',
                        cover: item.artworkUrl100 ? item.artworkUrl100.replace('100x100bb', '300x300bb') : 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&h=300&fit=crop',
                        audioUrl: item.previewUrl,
                        duration: 30, // Preview oficial do catálogo da Apple é de 30s
                        actualDuration: 30,
                        fullDuration: item.trackTimeMillis ? Math.round(item.trackTimeMillis / 1000) : 30,
                        isApplePreview: true
                    }));
                if (tracks.length > 0) return tracks;
            }
        }
    } catch (err) {
        console.warn("Consulta à API de músicas online falhou, usando catálogo local:", err);
    }

    if (q) {
        const filtered = DEFAULT_TRENDING_TRACKS.filter(t => 
            t.title.toLowerCase().includes(q) || 
            t.artist.toLowerCase().includes(q)
        );
        return filtered.length ? filtered : DEFAULT_TRENDING_TRACKS;
    }
    return DEFAULT_TRENDING_TRACKS;
}

export function openMusicPicker(target = 'status') {
    activeMusicPickerTarget = target;
    const modal = document.getElementById('music-picker-modal');
    if (modal) modal.classList.add('active');
    
    loadUserFavoriteTracks();

    const searchInput = document.getElementById('music-search-input');
    if (searchInput) {
        searchInput.value = '';
    }
    const clearBtn = document.getElementById('music-clear-search-btn');
    if (clearBtn) clearBtn.style.display = 'none';

    // Abre direto na aba de recomendações 'Para Você' igual ao Instagram
    activeMusicGenre = 'for-you';
    document.querySelectorAll('.music-chip').forEach(chip => {
        chip.classList.toggle('active', chip.dataset.genre === 'for-you');
    });

    loadMusicPickerResults('', 'for-you');
}

export function closeMusicPicker() {
    stopMusicPreview();
    const modal = document.getElementById('music-picker-modal');
    if (modal) modal.classList.remove('active');
    activeMusicPickerTarget = null;
}

function stopMusicPreview() {
    if (musicPreviewAudio) {
        try { musicPreviewAudio.pause(); } catch(e) {}
        musicPreviewAudio = null;
    }
    if (currentlyPlayingPreviewTrackId) {
        updateTrackPreviewUI(currentlyPlayingPreviewTrackId, false);
        currentlyPlayingPreviewTrackId = null;
    }
}

function toggleTrackPreview(track) {
    if (currentlyPlayingPreviewTrackId === track.id) {
        stopMusicPreview();
        return;
    }

    stopMusicPreview();

    try {
        musicPreviewAudio = new Audio(track.audioUrl);
        currentlyPlayingPreviewTrackId = track.id;
        updateTrackPreviewUI(track.id, true);

        musicPreviewAudio.play().catch(err => {
            console.warn("Erro ao reproduzir prévia de música:", err);
            stopMusicPreview();
        });

        musicPreviewAudio.onended = () => {
            stopMusicPreview();
        };
        musicPreviewAudio.onerror = () => {
            stopMusicPreview();
        };
    } catch (err) {
        console.warn("Erro ao carregar áudio:", err);
        stopMusicPreview();
    }
}

function updateTrackPreviewUI(trackId, isPlaying) {
    const card = document.querySelector(`.music-track-card[data-track-id="${trackId}"]`);
    const icon = document.getElementById(`track-play-icon-${trackId}`);
    if (card) card.classList.toggle('playing', isPlaying);
    if (icon) {
        icon.setAttribute('data-lucide', isPlaying ? 'pause' : 'play');
        if (window.lucide) lucide.createIcons();
    }
}

let lastFetchedTracks = [];

async function loadMusicPickerResults(query = '', genre = '') {
    const loading = document.getElementById('music-loading-state');
    const empty = document.getElementById('music-empty-state');
    const list = document.getElementById('music-tracks-list');

    if (loading) loading.style.display = 'flex';
    if (empty) empty.style.display = 'none';
    if (list) list.innerHTML = '';

    stopMusicPreview();

    const tracks = await searchMusicTracks(query, genre);
    lastFetchedTracks = tracks;

    if (loading) loading.style.display = 'none';

    if (!tracks || tracks.length === 0) {
        if (empty) {
            if (genre === 'favorites') {
                empty.innerHTML = `
                    <div class="music-empty-favorites">
                        <i data-lucide="heart" style="width:38px;height:38px;color:#ff4d67;"></i>
                        <span>Nenhuma música favoritada ainda.<br>Toque no coração ❤️ ao lado de qualquer música para salvar aqui!</span>
                    </div>
                `;
            } else {
                empty.innerHTML = `
                    <i data-lucide="music-4" style="width: 32px; height: 32px; color: var(--text-dim);"></i>
                    <span>Nenhuma música encontrada. Tente outra busca!</span>
                `;
            }
            empty.style.display = 'flex';
            if (window.lucide) lucide.createIcons();
        }
        return;
    }

    if (list) {
        // Banner de Recomendação personalizado estilo Instagram quando estiver no "Para Você"
        let recommendationHeader = '';
        if (genre === 'for-you' && !query) {
            if (userFavoriteTracks && userFavoriteTracks.length > 0) {
                const favArtists = [...new Set(userFavoriteTracks.map(t => t.artist?.trim()).filter(Boolean))];
                const artistListStr = favArtists.slice(0, 2).join(', ') + (favArtists.length > 2 ? ' e mais' : '');
                recommendationHeader = `
                    <div class="music-recommendation-banner">
                        <i data-lucide="sparkles"></i>
                        <span>Recomendadas com base no seu gosto por <strong>${escapeHTML(artistListStr)}</strong></span>
                    </div>
                `;
            } else {
                recommendationHeader = `
                    <div class="music-recommendation-banner">
                        <i data-lucide="sparkles"></i>
                        <span>Toque no <strong>coração ❤️</strong> para personalizar suas recomendações musicais!</span>
                    </div>
                `;
            }
        }

        const cardsHtml = tracks.map(track => {
            const isCurrentPlaying = currentlyPlayingPreviewTrackId === track.id;
            const isFav = isTrackFavorited(track.id);
            const isRec = genre === 'for-you' && track.isRecommended;
            return `
                <div class="music-track-card ${isCurrentPlaying ? 'playing' : ''}" data-track-id="${escapeHTML(track.id)}">
                    <div class="track-cover-wrap">
                        <img src="${escapeHTML(track.cover)}" alt="Capa" class="track-cover-img" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&h=300&fit=crop'">
                        <button type="button" class="track-play-overlay" data-action="preview-track" data-track-id="${escapeHTML(track.id)}" title="Ouvir 30s">
                            <i data-lucide="${isCurrentPlaying ? 'pause' : 'play'}" id="track-play-icon-${escapeHTML(track.id)}"></i>
                        </button>
                    </div>
                    <div class="track-info">
                        <div style="display:flex; align-items:center; gap:4px; flex-wrap:wrap;">
                            <span class="track-title">${escapeHTML(track.title)}</span>
                            ${isRec ? `<span class="track-recommended-badge"><i data-lucide="sparkles" style="width:10px;height:10px;"></i> Para Você</span>` : ''}
                        </div>
                        <span class="track-artist">${escapeHTML(track.artist)}</span>
                        <span class="track-meta-tag"><i data-lucide="music-2" style="width:11px;height:11px;"></i> ${escapeHTML(track.isLocal ? `Música Completa (${formatMusicDuration(track.actualDuration || track.duration)})` : (track.isApplePreview ? `Prévia 30s • Original ${formatMusicDuration(track.fullDuration || track.duration)}` : formatMusicDuration(track.duration)))}</span>
                    </div>
                    <div class="track-actions-wrap">
                        <button type="button" class="track-fav-btn ${isFav ? 'favorited' : ''}" data-action="toggle-fav-track" data-track-id="${escapeHTML(track.id)}" title="${isFav ? 'Remover dos favoritos' : 'Salvar nos favoritos'}" aria-label="Favoritar">
                            <i data-lucide="heart" class="${isFav ? 'filled' : ''}"></i>
                        </button>
                        <button type="button" class="track-select-btn" data-action="select-track" data-track-id="${escapeHTML(track.id)}">
                            Usar
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        list.innerHTML = recommendationHeader + cardsHtml;

        if (window.lucide) lucide.createIcons();

        list.querySelectorAll('[data-action="preview-track"]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const tid = btn.dataset.trackId;
                const track = lastFetchedTracks.find(t => String(t.id) === String(tid)) || userFavoriteTracks.find(t => String(t.id) === String(tid));
                if (track) toggleTrackPreview(track);
            });
        });

        list.querySelectorAll('[data-action="toggle-fav-track"]').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                e.stopPropagation();
                const tid = btn.dataset.trackId;
                const track = lastFetchedTracks.find(t => String(t.id) === String(tid)) || userFavoriteTracks.find(t => String(t.id) === String(tid));
                if (track) await toggleFavoriteTrack(track);
            });
        });

        list.querySelectorAll('[data-action="select-track"]').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const tid = btn.dataset.trackId;
                const track = lastFetchedTracks.find(t => String(t.id) === String(tid)) || userFavoriteTracks.find(t => String(t.id) === String(tid));
                if (track) selectMusicTrack(track);
            });
        });
    }
}

export function audioBufferToWavBlob(audioBuffer) {
    const numChannels = audioBuffer.numberOfChannels;
    const sampleRate = audioBuffer.sampleRate;
    const format = 1; // PCM
    const bitDepth = 16;
    const bytesPerSample = bitDepth / 8;
    const blockAlign = numChannels * bytesPerSample;

    const channelData = [];
    for (let i = 0; i < numChannels; i++) {
        channelData.push(audioBuffer.getChannelData(i));
    }

    const numSamples = audioBuffer.length;
    const dataSize = numSamples * blockAlign;
    const headerSize = 44;
    const totalSize = headerSize + dataSize;

    const buffer = new ArrayBuffer(totalSize);
    const view = new DataView(buffer);

    function writeString(offset, string) {
        for (let i = 0; i < string.length; i++) {
            view.setUint8(offset + i, string.charCodeAt(i));
        }
    }

    // RIFF chunk descriptor
    writeString(0, 'RIFF');
    view.setUint32(4, 36 + dataSize, true);
    writeString(8, 'WAVE');

    // fmt sub-chunk
    writeString(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, format, true);
    view.setUint16(22, numChannels, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * blockAlign, true);
    view.setUint16(32, blockAlign, true);
    view.setUint16(34, bitDepth, true);

    // data sub-chunk
    writeString(36, 'data');
    view.setUint32(40, dataSize, true);

    // Write PCM samples
    let offset = 44;
    for (let i = 0; i < numSamples; i++) {
        for (let ch = 0; ch < numChannels; ch++) {
            let sample = channelData[ch][i];
            sample = Math.max(-1, Math.min(1, sample));
            const intSample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
            view.setInt16(offset, intSample, true);
            offset += 2;
        }
    }

    return new Blob([view], { type: 'audio/wav' });
}

export async function extractAudioSnippetAsWav(fileOrBlob, startSec = 0, durationSec = 15) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    const OfflineAudioContextClass = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!AudioContextClass || !OfflineAudioContextClass) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(fileOrBlob);
        });
    }

    const arrayBuffer = await fileOrBlob.arrayBuffer();
    const audioCtx = new AudioContextClass();
    let audioBuffer;
    try {
        audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
    } finally {
        try { audioCtx.close(); } catch(e) {}
    }

    const origSampleRate = audioBuffer.sampleRate;
    const totalFrames = audioBuffer.length;
    const safeStartSec = Math.max(0, Number(startSec) || 0);
    const safeDurSec = Math.max(1, Number(durationSec) || 15);

    const startFrame = Math.max(0, Math.floor(safeStartSec * origSampleRate));
    const maxFrames = Math.floor(safeDurSec * origSampleRate);
    const endFrame = Math.min(totalFrames, startFrame + maxFrames);
    const sliceFrames = Math.max(1, endFrame - startFrame);

    const targetSampleRate = 22050;
    const targetFrames = Math.max(1, Math.round(sliceFrames * (targetSampleRate / origSampleRate)));
    const targetChannels = 1;

    const offlineCtx = new OfflineAudioContextClass(targetChannels, targetFrames, targetSampleRate);
    const sourceNode = offlineCtx.createBufferSource();
    sourceNode.buffer = audioBuffer;
    sourceNode.connect(offlineCtx.destination);
    sourceNode.start(0, safeStartSec, safeDurSec);

    const renderedBuffer = await offlineCtx.startRendering();
    const wavBlob = audioBufferToWavBlob(renderedBuffer);

    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(wavBlob);
    });
}

export function formatSnippetSeconds(sec) {
    const s = Math.max(0, Math.floor(sec || 0));
    const m = Math.floor(s / 60);
    const rem = s % 60;
    return `${m}:${rem < 10 ? '0' : ''}${rem}`;
}

export function updateMusicSnippetUI(target) {
    const track = target === 'status' ? pendingStatusMusic : pendingPostMusic;
    if (!track) return;

    const rangeEl = document.getElementById(`${target}-music-snippet-range`);
    const badgeEl = document.getElementById(`${target}-snippet-time-badge`);
    const startLbl = document.getElementById(`${target}-snippet-start-label`);
    const endLbl = document.getElementById(`${target}-snippet-end-label`);

    if (!rangeEl || !badgeEl) return;

    // Determina a duração total disponível (padrão 30s se não informada)
    let totalDuration = Number(track.actualDuration || track.duration) || 30;

    // Tentar obter a duração exata do arquivo de áudio se ainda não carregada
    if (!track.actualDuration && track.audioUrl) {
        try {
            const probeAudio = new Audio();
            probeAudio.src = track.audioUrl;
            probeAudio.onloadedmetadata = () => {
                if (probeAudio.duration && !isNaN(probeAudio.duration) && isFinite(probeAudio.duration)) {
                    track.actualDuration = Math.round(probeAudio.duration);
                    updateMusicSnippetUI(target);
                }
            };
        } catch(e) {}
    }

    let snippetDuration = 15;
    if (target === 'status') {
        // Conforme a categoria selecionada (15s, 30s, 45s ou 1 min / 60s)
        snippetDuration = Number(selectedStoryDuration) || 15;
    } else {
        const vidDur = pendingPostMediaInfo?.duration || 0;
        snippetDuration = vidDur > 0 ? Math.round(vidDur) : 15;
        snippetDuration = Math.min(snippetDuration, totalDuration);
    }

    track.snippetDuration = snippetDuration;

    let maxStart = 0;
    if (totalDuration > snippetDuration) {
        maxStart = totalDuration - snippetDuration;
    } else {
        // Se a mídia de áudio for menor ou igual à duração selecionada (ex: prévia 30s para story de 30s/45s/60s),
        // travamos o início em 0:00 para tocar a música inteira disponível sem cortar após alguns segundos!
        maxStart = 0;
    }

    rangeEl.min = 0;
    rangeEl.max = maxStart;
    rangeEl.step = 1;
    rangeEl.disabled = maxStart <= 0;

    let currentStart = Number(track.snippetStart) || 0;
    if (currentStart > maxStart) {
        currentStart = maxStart;
        track.snippetStart = currentStart;
    }
    rangeEl.value = currentStart;

    const durLabel = snippetDuration === 60 ? '1 min' : `${snippetDuration}s`;
    const endSec = currentStart + snippetDuration;

    if (!track.isLocal && totalDuration <= 35 && snippetDuration > totalDuration) {
        badgeEl.innerText = `${formatSnippetSeconds(currentStart)} - ${formatSnippetSeconds(totalDuration)} (Prévia 30s repete até ${durLabel})`;
    } else {
        badgeEl.innerText = `${formatSnippetSeconds(currentStart)} - ${formatSnippetSeconds(endSec)} (${durLabel})`;
    }

    if (startLbl) startLbl.innerText = formatSnippetSeconds(currentStart);
    if (endLbl) endLbl.innerText = formatSnippetSeconds(Math.max(totalDuration, endSec));

    // Exibir ou ocultar dica de prévia online vs música completa
    const hintEl = document.getElementById(`${target}-snippet-hint`);
    if (hintEl) {
        if (!track.isLocal && totalDuration <= 35 && snippetDuration > totalDuration) {
            hintEl.style.display = 'flex';
            hintEl.style.background = 'rgba(255, 170, 0, 0.1)';
            hintEl.style.borderColor = 'rgba(255, 170, 0, 0.25)';
            hintEl.style.color = '#ffcc66';
            hintEl.innerHTML = `<i data-lucide="info" style="width:14px;height:14px;flex-shrink:0;"></i><span><strong>Prévia oficial de 30s da Apple</strong>: Este áudio online tem 30s e irá repetir para cobrir os ${durLabel}. Dica: Para tocar 1 min contínuo da música original, carregue o MP3 do seu aparelho!</span>`;
            if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons();
        } else if (track.isLocal) {
            hintEl.style.display = 'flex';
            hintEl.style.background = 'rgba(0, 243, 255, 0.1)';
            hintEl.style.borderColor = 'rgba(0, 243, 255, 0.3)';
            hintEl.style.color = '#00f3ff';
            hintEl.innerHTML = `<i data-lucide="check-circle" style="width:14px;height:14px;flex-shrink:0;"></i><span><strong>Música Completa do Aparelho</strong>: Tocará continuamente por ${durLabel} do trecho selecionado!</span>`;
            if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons();
        } else {
            hintEl.style.display = 'none';
        }
    }
}

export function initMusicSnippetListeners() {
    ['status', 'post'].forEach(target => {
        const rangeEl = document.getElementById(`${target}-music-snippet-range`);
        if (!rangeEl) return;

        rangeEl.addEventListener('input', (e) => {
            const start = Number(e.target.value) || 0;
            const track = target === 'status' ? pendingStatusMusic : pendingPostMusic;
            if (!track) return;

            track.snippetStart = start;
            const dur = Number(track.snippetDuration) || (target === 'status' ? (Number(selectedStoryDuration) || 15) : 15);
            const badgeEl = document.getElementById(`${target}-snippet-time-badge`);
            const startLbl = document.getElementById(`${target}-snippet-start-label`);

            const durLabel = dur === 60 ? '1 min' : `${dur}s`;
            if (badgeEl) {
                badgeEl.innerText = `${formatSnippetSeconds(start)} - ${formatSnippetSeconds(start + dur)} (${durLabel})`;
            }
            if (startLbl) {
                startLbl.innerText = formatSnippetSeconds(start);
            }

            // Se o preview de áudio no compositor estiver ativo, sincroniza imediatamente
            if (composerPreviewAudio && currentlyPlayingComposerTarget === target) {
                try {
                    composerPreviewAudio.currentTime = start;
                } catch (err) {}
            }
        });

        // Quando o usuário soltar o slider do trecho
        rangeEl.addEventListener('change', () => {
            const track = target === 'status' ? pendingStatusMusic : pendingPostMusic;
            if (!track || !track.audioUrl) return;

            if (!composerPreviewAudio || currentlyPlayingComposerTarget !== target) {
                toggleComposerMusicPreview(target);
            } else {
                composerPreviewAudio.currentTime = track.snippetStart || 0;
            }
        });
    });
}

export function selectMusicTrack(track) {
    stopMusicPreview();

    // Inicializa valores padrão do trecho da música
    track.snippetStart = Number(track.snippetStart) || 0;

    if (activeMusicPickerTarget === 'status') {
        track.snippetDuration = Number(selectedStoryDuration) || 15;
        pendingStatusMusic = track;
        const card = document.getElementById('status-selected-music-card');
        const cover = document.getElementById('status-selected-music-cover');
        const title = document.getElementById('status-selected-music-title');
        const artist = document.getElementById('status-selected-music-artist');
        const addBtn = document.getElementById('status-add-music-btn');

        if (cover) cover.src = track.cover;
        if (title) title.innerText = track.title;
        if (artist) artist.innerText = track.artist;
        if (card) card.style.display = 'flex';
        if (addBtn) addBtn.style.display = 'none';

        updateMusicSnippetUI('status');
    } else if (activeMusicPickerTarget === 'post') {
        const vidDur = pendingPostMediaInfo?.duration || 0;
        track.snippetDuration = vidDur > 0 ? Math.round(vidDur) : 15;
        pendingPostMusic = track;
        const card = document.getElementById('post-selected-music-card');
        const cover = document.getElementById('post-selected-music-cover');
        const title = document.getElementById('post-selected-music-title');
        const artist = document.getElementById('post-selected-music-artist');
        const addBtn = document.getElementById('post-add-music-btn');

        if (cover) cover.src = track.cover;
        if (title) title.innerText = track.title;
        if (artist) artist.innerText = track.artist;
        if (card) card.style.display = 'flex';
        if (addBtn) addBtn.style.display = 'none';

        updateMusicSnippetUI('post');
    }

    if (window.lucide) lucide.createIcons();
    closeMusicPicker();
    showToast('Música Anexada 🎵', `${track.title} • ${track.artist}`, 'green');
}

export function removeSelectedMusic(target) {
    if (composerPreviewAudio) {
        clearTimeout(composerPreviewTimer);
        composerPreviewTimer = null;
        try { composerPreviewAudio.pause(); } catch(e) {}
        composerPreviewAudio = null;
        currentlyPlayingComposerTarget = null;
    }

    if (target === 'status') {
        pendingStatusMusic = null;
        const card = document.getElementById('status-selected-music-card');
        const addBtn = document.getElementById('status-add-music-btn');
        if (card) card.style.display = 'none';
        if (addBtn) addBtn.style.display = 'inline-flex';
    } else if (target === 'post') {
        pendingPostMusic = null;
        const card = document.getElementById('post-selected-music-card');
        const addBtn = document.getElementById('post-add-music-btn');
        if (card) card.style.display = 'none';
        if (addBtn) addBtn.style.display = 'inline-flex';
    }
}

function toggleComposerMusicPreview(target) {
    const track = target === 'status' ? pendingStatusMusic : pendingPostMusic;
    if (!track || !track.audioUrl) return;

    const iconId = target === 'status' ? 'status-preview-music-icon' : 'post-preview-music-icon';
    const iconEl = document.getElementById(iconId);

    if (composerPreviewAudio && currentlyPlayingComposerTarget === target) {
        try { composerPreviewAudio.pause(); } catch(e) {}
        composerPreviewAudio = null;
        currentlyPlayingComposerTarget = null;
        if (iconEl) {
            clearTimeout(composerPreviewTimer);
            composerPreviewTimer = null;
            iconEl.setAttribute('data-lucide', 'play');
            if (window.lucide) lucide.createIcons();
        }
        return;
    }

    if (composerPreviewAudio) {
        clearTimeout(composerPreviewTimer);
        composerPreviewTimer = null;
        try { composerPreviewAudio.pause(); } catch(e) {}
        composerPreviewAudio = null;
    }

    try {
        const audio = new Audio(track.audioUrl);
        audio.loop = true; // Loop contínuo nativo do navegador para 15s, 30s, 45s ou 1 min
        composerPreviewAudio = audio;
        currentlyPlayingComposerTarget = target;
        if (iconEl) {
            iconEl.setAttribute('data-lucide', 'pause');
            if (window.lucide) lucide.createIcons();
        }

        const start = Number(track.snippetStart) || 0;
        const dur = Number(track.snippetDuration) || (target === 'status' ? (Number(selectedStoryDuration) || 15) : 15);

        let hasInitialSeek = false;
        const applySeek = () => {
            try {
                if (!hasInitialSeek && start > 0 && Math.abs(audio.currentTime - start) > 0.5) {
                    audio.currentTime = start;
                    hasInitialSeek = true;
                }
            } catch (e) {}
        };
        audio.addEventListener('loadedmetadata', applySeek, { once: true });
        audio.addEventListener('canplay', applySeek, { once: true });
        if (start > 0) {
            try { audio.currentTime = start; hasInitialSeek = true; } catch(e) {}
        }

        // Se dur for menor que a duração do arquivo, reinicia ao final do trecho
        audio.ontimeupdate = () => {
            if (composerPreviewAudio === audio) {
                const cur = audio.currentTime;
                if (dur < (audio.duration || 9999) && cur >= start + dur) {
                    audio.currentTime = start;
                }
            }
        };

        // Temporizador para parar no tempo exato da categoria selecionada (15s, 30s, 45s ou 60s / 1 min)
        clearTimeout(composerPreviewTimer);
        composerPreviewTimer = setTimeout(() => {
            if (composerPreviewAudio === audio) {
                audio.pause();
                if (iconEl) {
                    iconEl.setAttribute('data-lucide', 'play');
                    if (window.lucide) lucide.createIcons();
                }
                composerPreviewAudio = null;
                currentlyPlayingComposerTarget = null;
                composerPreviewTimer = null;
            }
        }, dur * 1000);

        audio.play().catch(err => {
            console.warn("Erro ao tocar preview do compositor:", err);
            clearTimeout(composerPreviewTimer);
            composerPreviewTimer = null;
            if (iconEl) {
                iconEl.setAttribute('data-lucide', 'play');
                if (window.lucide) lucide.createIcons();
            }
        });

        audio.onended = () => {
            if (composerPreviewAudio === audio) {
                try {
                    audio.currentTime = start;
                    audio.play().catch(() => {});
                } catch (e) {}
            }
        };
    } catch(err) {
        console.warn("Erro ao criar áudio:", err);
    }
}

export async function toggleFeedPostMusic(postId, audioUrl, snippetStart = 0, snippetDuration = 0) {
    if (currentFeedMusicAudio && currentFeedMusicPostId === postId) {
        if (!currentFeedMusicAudio.paused) {
            try { currentFeedMusicAudio.pause(); } catch(e) {}
            updateFeedMusicUI(postId, false);
        } else {
            updateFeedMusicUI(postId, true);
            try {
                await currentFeedMusicAudio.play();
            } catch (err) {
                console.warn("Erro ao retomar áudio:", err);
                updateFeedMusicUI(postId, false);
            }
        }
        return;
    }

    if (currentFeedMusicAudio) {
        try { currentFeedMusicAudio.pause(); } catch(e) {}
        if (currentFeedMusicPostId) updateFeedMusicUI(currentFeedMusicPostId, false);
        currentFeedMusicAudio = null;
        currentFeedMusicPostId = null;
    }

    if (storyMusicAudio) {
        try { storyMusicAudio.pause(); } catch(e) {}
        storyMusicAudio = null;
    }

    let finalAudio = audioUrl;
    if (!finalAudio && postId) {
        finalAudio = mediaChunkCache.get(`post_audio_${postId}`) || await loadMediaWithChunks('post_audio', postId);
    }

    if (!finalAudio) {
        showToast('Áudio indisponível', 'Não foi possível encontrar a faixa desta postagem.', 'red');
        return;
    }

    try {
        const audio = new Audio(finalAudio);
        const start = Number(snippetStart) || 0;
        const dur = Number(snippetDuration) || 0;

        let hasInitialSeek = false;
        const applyStartTime = () => {
            try {
                if (!hasInitialSeek && start > 0 && Math.abs(audio.currentTime - start) > 0.5) {
                    audio.currentTime = start;
                    hasInitialSeek = true;
                }
            } catch (e) {}
        };
        audio.addEventListener('loadedmetadata', applyStartTime, { once: true });
        audio.addEventListener('canplay', applyStartTime, { once: true });
        if (start > 0) {
            try { audio.currentTime = start; hasInitialSeek = true; } catch(e) {}
        }

        if (dur > 0) {
            audio.ontimeupdate = () => {
                if (currentFeedMusicAudio === audio) {
                    const cur = audio.currentTime;
                    if (dur < (audio.duration || 9999) && cur >= start + dur) {
                        audio.currentTime = start;
                    }
                }
            };
        } else {
            audio.loop = true;
        }

        audio.onended = () => {
            updateFeedMusicUI(postId, false);
            if (currentFeedMusicAudio === audio) {
                currentFeedMusicAudio = null;
                currentFeedMusicPostId = null;
            }
        };

        currentFeedMusicAudio = audio;
        currentFeedMusicPostId = postId;
        updateFeedMusicUI(postId, true);

        const playPromise = audio.play();
        if (playPromise !== undefined) {
            try {
                await playPromise;
            } catch (err) {
                console.warn("Erro ao reproduzir áudio do post:", err);
                if (currentFeedMusicAudio === audio) {
                    updateFeedMusicUI(postId, false);
                    showToast('Aviso', 'Toque novamente para iniciar a reprodução.', 'blue');
                }
            }
        }
    } catch (err) {
        console.warn("Erro ao criar áudio do feed:", err);
        updateFeedMusicUI(postId, false);
    }
}

export function updateFeedMusicUI(postId, isPlaying) {
    const badge = document.getElementById(`feed-music-badge-${postId}`);
    const previewBadge = document.getElementById(`preview-music-badge-${postId}`);
    [badge, previewBadge].forEach(b => {
        if (b) {
            b.classList.toggle('playing', isPlaying);
            const toggleBtn = b.querySelector('.feed-music-toggle-btn');
            if (toggleBtn) {
                toggleBtn.innerHTML = `<i data-lucide="${isPlaying ? 'pause' : 'play'}" id="feed-music-icon-${postId}"></i>`;
            }
        }
    });
    if (window.lucide) lucide.createIcons();
}

function initMusicFeatureListeners() {
    document.getElementById('status-add-music-btn')?.addEventListener('click', () => {
        playSound(clickSound);
        openMusicPicker('status');
    });

    document.getElementById('post-add-music-btn')?.addEventListener('click', () => {
        playSound(clickSound);
        openMusicPicker('post');
    });

    document.getElementById('close-music-picker-btn')?.addEventListener('click', () => {
        playSound(clickSound);
        closeMusicPicker();
    });

    const musicFileInput = document.getElementById('music-file-upload-input');
    if (musicFileInput) {
        musicFileInput.addEventListener('change', async (e) => {
            const file = e.target.files && e.target.files[0];
            if (!file) return;

            // Reset do input para permitir selecionar novamente
            e.target.value = '';

            try {
                let rawName = file.name.replace(/\.[^/.]+$/, "").trim();
                let artist = 'Música do Aparelho';
                let title = rawName;
                if (rawName.includes(' - ')) {
                    const parts = rawName.split(' - ');
                    artist = parts[0].trim();
                    title = parts.slice(1).join(' - ').trim();
                } else if (rawName.includes('_-_')) {
                    const parts = rawName.split('_-_');
                    artist = parts[0].trim();
                    title = parts.slice(1).join('_-_').trim();
                }

                const objectUrl = URL.createObjectURL(file);

                // Carrega metadados reais da música com timeout de segurança
                const probe = new Audio(objectUrl);
                const realDuration = await new Promise(resolve => {
                    probe.onloadedmetadata = () => {
                        const d = (probe.duration && !isNaN(probe.duration) && isFinite(probe.duration)) ? Math.round(probe.duration) : 180;
                        resolve(d);
                    };
                    probe.onerror = () => resolve(180);
                    setTimeout(() => resolve(180), 2500);
                });

                const localTrack = {
                    id: 'local_' + Date.now(),
                    title: title || 'Música do Aparelho',
                    artist: artist || 'Áudio Local',
                    cover: 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&h=300&fit=crop',
                    audioUrl: objectUrl,
                    duration: realDuration,
                    actualDuration: realDuration,
                    fullDuration: realDuration,
                    isLocal: true,
                    file: file
                };

                selectMusicTrack(localTrack);
                showToast("Música Carregada", `Música completa carregada (${formatMusicDuration(realDuration)})! Selecione o trecho desejado.`, "green");
            } catch (err) {
                console.error("Erro ao carregar música do aparelho:", err);
                showToast("Erro ao carregar", "Não foi possível carregar o arquivo de áudio.", "red");
            }
        });
    }

    document.getElementById('music-picker-modal')?.addEventListener('click', (e) => {
        if (e.target.id === 'music-picker-modal') {
            closeMusicPicker();
        }
    });

    document.getElementById('status-remove-music-btn')?.addEventListener('click', () => {
        playSound(clickSound);
        removeSelectedMusic('status');
    });

    document.getElementById('post-remove-music-btn')?.addEventListener('click', () => {
        playSound(clickSound);
        removeSelectedMusic('post');
    });

    document.getElementById('status-preview-music-btn')?.addEventListener('click', () => {
        toggleComposerMusicPreview('status');
    });

    document.getElementById('post-preview-music-btn')?.addEventListener('click', () => {
        toggleComposerMusicPreview('post');
    });

    document.getElementById('story-music-mute-btn')?.addEventListener('click', (e) => {
        e.stopPropagation();
        isStoryMusicMuted = !isStoryMusicMuted;
        if (storyMusicAudio) {
            storyMusicAudio.muted = isStoryMusicMuted;
        }
        const icon = document.getElementById('story-music-mute-icon');
        if (icon) {
            icon.setAttribute('data-lucide', isStoryMusicMuted ? 'volume-x' : 'volume-2');
            if (window.lucide) lucide.createIcons();
        }
    });

    const searchInput = document.getElementById('music-search-input');
    const clearBtn = document.getElementById('music-clear-search-btn');

    searchInput?.addEventListener('input', (e) => {
        const val = e.target.value;
        if (clearBtn) clearBtn.style.display = val ? 'flex' : 'none';

        clearTimeout(musicSearchDebounceTimer);
        musicSearchDebounceTimer = setTimeout(() => {
            loadMusicPickerResults(val, activeMusicGenre);
        }, 320);
    });

    clearBtn?.addEventListener('click', async () => {
        if (searchInput) searchInput.value = '';
        clearBtn.style.display = 'none';
        await loadMusicPickerResults('', activeMusicGenre);
    });

    document.querySelectorAll('.music-chip').forEach(chip => {
        chip.addEventListener('click', async () => {
            playSound(clickSound);
            document.querySelectorAll('.music-chip').forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            activeMusicGenre = chip.dataset.genre || 'trending';
            const currentQuery = searchInput?.value || '';
            await loadMusicPickerResults(currentQuery, activeMusicGenre);
        });
    });

    initMusicSnippetListeners();
}

initMusicFeatureListeners();

